/**
 * @file spz-parser.ts
 * Parser for the .spz compressed gaussian splatting format (Niantic).
 *
 * Uses @spz-loader/core (WASM decoder) to decompress, then converts the
 * GaussianCloud output to the PlyElement structure that PlayCanvas expects.
 *
 * GaussianCloud fields from spz-loader (AFTER its internal transforms):
 *   positions  : Float32Array  — [x,y,z, …]  world-space
 *   scales     : Float32Array  — [sx,sy,sz, …]  LINEAR (spz-loader applies exp())
 *   rotations  : Float32Array  — [w,x,y,z, …]  normalised quaternion
 *   alphas     : Float32Array  — [a, …]  sigmoid 0-1 (spz-loader applies sigmoid)
 *   colors     : Float32Array  — [r,g,b, …]  approx linear 0-1 (sh0 * 0.282 + 0.5)
 *
 * ENGINE UPGRADE: If PlayCanvas adds native .spz support, remove this file
 * and the `gsplatHandler.parsers.spz` registration in index.ts.
 */

import type { AppBase, Asset } from 'playcanvas';
import { fetchBinaryWithProgress, buildVertexElement, createGSplatResource } from './parser-utils';

const SH_C0 = 0.28209479177387814;

class SpzParser {
    app: AppBase;
    maxRetries: number;

    constructor(app: AppBase, maxRetries = 0) {
        this.app = app;
        this.maxRetries = maxRetries;
    }

    async load(
        url: { load: string; original: string } | string,
        callback: (err: string | null, resource?: any) => void,
        asset: Asset,
    ) {
        try {
            const buffer = await fetchBinaryWithProgress(url, asset);

            // Decode .spz using WASM decoder (lazy-loaded)
            const { loadSpz } = await import('@spz-loader/core');
            const cloud = await loadSpz(buffer);
            const numSplats = cloud.numPoints;

            if (numSplats === 0) {
                callback('Empty or invalid .spz file');
                return;
            }

            // Allocate output arrays
            const x = new Float32Array(numSplats);
            const y = new Float32Array(numSplats);
            const z = new Float32Array(numSplats);
            const scale_0 = new Float32Array(numSplats);
            const scale_1 = new Float32Array(numSplats);
            const scale_2 = new Float32Array(numSplats);
            const f_dc_0 = new Float32Array(numSplats);
            const f_dc_1 = new Float32Array(numSplats);
            const f_dc_2 = new Float32Array(numSplats);
            const opacity = new Float32Array(numSplats);
            const rot_0 = new Float32Array(numSplats);
            const rot_1 = new Float32Array(numSplats);
            const rot_2 = new Float32Array(numSplats);
            const rot_3 = new Float32Array(numSplats);

            const EPS = 1e-12;
            for (let i = 0; i < numSplats; i++) {
                // Positions: interleaved [x,y,z, …]
                x[i] = cloud.positions[i * 3];
                y[i] = cloud.positions[i * 3 + 1];
                z[i] = cloud.positions[i * 3 + 2];

                // Scales: interleaved [sx,sy,sz, …] — LINEAR (spz-loader applies exp())
                // PlayCanvas createIter applies exp() expecting log-scale,
                // so we convert back to log-space. Clamp to avoid log(0).
                scale_0[i] = Math.log(Math.max(EPS, cloud.scales[i * 3]));
                scale_1[i] = Math.log(Math.max(EPS, cloud.scales[i * 3 + 1]));
                scale_2[i] = Math.log(Math.max(EPS, cloud.scales[i * 3 + 2]));

                // Colors: linear 0-1 → SH0 coefficients
                f_dc_0[i] = (cloud.colors[i * 3] - 0.5) / SH_C0;
                f_dc_1[i] = (cloud.colors[i * 3 + 1] - 0.5) / SH_C0;
                f_dc_2[i] = (cloud.colors[i * 3 + 2] - 0.5) / SH_C0;

                // Opacity: spz-loader applies sigmoid, returning 0-1 probability.
                // PlayCanvas expects logit (inverse-sigmoid), so convert back.
                // Clamp to avoid log(0) or log(Infinity).
                const a = Math.max(1e-6, Math.min(1 - 1e-6, cloud.alphas[i]));
                opacity[i] = -Math.log(1 / a - 1);

                // Rotations: interleaved [w,x,y,z, …] — normalised quaternion
                rot_0[i] = cloud.rotations[i * 4];     // w
                rot_1[i] = cloud.rotations[i * 4 + 1]; // x
                rot_2[i] = cloud.rotations[i * 4 + 2]; // y
                rot_3[i] = cloud.rotations[i * 4 + 3]; // z
            }

            const vertexElement = buildVertexElement(numSplats, {
                x, y, z, scale_0, scale_1, scale_2,
                f_dc_0, f_dc_1, f_dc_2, opacity,
                rot_0, rot_1, rot_2, rot_3,
            });

            const resource = createGSplatResource(this.app.graphicsDevice, vertexElement);
            callback(null, resource);
        } catch (err) {
            callback(err instanceof Error ? err.message : String(err));
        }
    }

    open(url: any, data: any) {
        return data;
    }
}

export { SpzParser };
