/**
 * @file camera-limits.ts
 * CameraLimits — PlayCanvas port of cameraLimits.js.
 *
 * Maps the Babylon arc-rotate camera limits (alpha/beta/radius) to
 * PlayCanvas OrbitControllerPC properties (yawRange / pitchRange / zoomRange).
 *
 * Unit differences:
 *   Babylon betaMin/betaMax  = radians from zenith (0=up, π/2=horizon, π=down)
 *   PlayCanvas pitchRange    = Vec2(minDeg, maxDeg), 0=horizon, -90=up, +90=down
 *
 *   Babylon alphaMin/alphaMax = radians
 *   PlayCanvas yawRange       = Vec2(minDeg, maxDeg)
 *
 *   Zoom (radius/distance) units are the same (world units).
 *
 * Panning: controlled via viewerState.panningEnabled which InputController
 * reads each frame. setPanningEnabled() is the single write point.
 */

import { Vec2 } from 'playcanvas';
import { viewerState } from './viewer-state.js';

// ─── Default values ───────────────────────────────────────────────────────────

/**
 * Default limit values that match the original Babylon viewer configuration.
 * Exported so that settingsPanel and urlManager can reference the same
 * constants — prevents the four-way duplication of these magic numbers.
 *
 * - `zoom.min / zoom.max`  — World-unit distance range; 1–15 covers most
 *   normalised models (target size ≈ 2 world units, so 1 is close and 15 is
 *   a comfortable wide view).
 * - `vertical.upDeg`       — -80° lets the camera look nearly straight up
 *   without flipping; -90° would cause gimbal issues at the zenith.
 * - `vertical.downDeg`     — 5° prevents the camera from going underground on
 *   flat-floor scenes.
 * - `horizontal.totalAngle`— 360 = unrestricted rotation by default.
 * - `horizontal.offset`    — 0 = centred on the model's forward axis.
 * - `restrict.*`           — All per-axis restrictions start disabled; panning
 *   is enabled by default so the user is not surprised.
 */
export const DEFAULTS = {
    zoom: { min: 1.0, max: 15.0 },
    vertical: { upDeg: -80, downDeg: 5 },
    horizontal: { totalAngle: 360, offset: 0 },
    restrict: {
        distance:   false,
        vertical:   false,
        horizontal: false,
        panning:    true,
    },
} as const;

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * Internal state snapshot for all camera limit values.
 * Kept private inside {@link CameraLimits}; read-only copies are exposed via
 * {@link CameraLimits.getCurrentLimits}.
 *
 * Panning is intentionally absent — it lives in viewerState.panningEnabled,
 * which is the single source of truth read by InputController each frame.
 */
interface LimitsState {
    enabled: boolean;

    restrictDistance: boolean;
    /** Minimum orbit distance in world units. */
    radiusMin: number;
    /** Maximum orbit distance in world units. */
    radiusMax: number;

    restrictVertical: boolean;
    /** Minimum pitch in degrees (negative = looking up, e.g. -90). */
    pitchMin: number;
    /** Maximum pitch in degrees (positive = looking down, e.g. +90). */
    pitchMax: number;

    restrictHorizontal: boolean;
    /** Minimum yaw in degrees. */
    yawMin: number;
    /** Maximum yaw in degrees. */
    yawMax: number;
}

// ─── CameraLimits class ───────────────────────────────────────────────────────

/**
 * Manages camera movement constraints for the PlayCanvas orbit controller.
 *
 * Call `setEnabled(true)` to activate limits, then use the individual setter
 * methods to configure each axis.  Every setter calls `apply()` internally so
 * the orbit controller is updated immediately.
 *
 * Use the singleton {@link cameraLimits} rather than constructing directly.
 */
class CameraLimits {
    private limits: LimitsState = {
        enabled: false,

        restrictDistance: DEFAULTS.restrict.distance,
        radiusMin: DEFAULTS.zoom.min,
        radiusMax: DEFAULTS.zoom.max,

        restrictVertical: DEFAULTS.restrict.vertical,
        pitchMin: DEFAULTS.vertical.upDeg,
        pitchMax: DEFAULTS.vertical.downDeg,

        restrictHorizontal: DEFAULTS.restrict.horizontal,
        yawMin: DEFAULTS.horizontal.offset - DEFAULTS.horizontal.totalAngle / 2,
        yawMax: DEFAULTS.horizontal.offset + DEFAULTS.horizontal.totalAngle / 2,
    };

    // ─── Accessors ────────────────────────────────────────────────────────────

    /** Whether the camera limits master toggle is currently on. */
    get isEnabled(): boolean { return this.limits.enabled; }

    /**
     * Returns a shallow copy of the current limits state.
     * Safe to destructure; mutations do not affect the internal state.
     */
    getCurrentLimits(): LimitsState { return { ...this.limits }; }

    // ─── Master toggle ────────────────────────────────────────────────────────

    /**
     * Enables or disables all camera limits at once.
     * When disabled, the orbit controller reverts to unrestricted ranges.
     *
     * @param enabled - `true` to activate limits, `false` to remove them.
     */
    setEnabled(enabled: boolean): void {
        this.limits.enabled = enabled;
        this.apply();
    }

    // ─── Distance (zoom) ──────────────────────────────────────────────────────

    /**
     * Configures the zoom (orbit distance) range.
     *
     * @param enabled - Whether this specific limit is active.
     * @param min     - Minimum distance in world units (clamped to ≥ 0.01).
     * @param max     - Maximum distance in world units (clamped to > `min + 0.1`).
     */
    setDistanceLimits(enabled: boolean, min: number, max: number): void {
        this.limits.restrictDistance = enabled;
        this.limits.radiusMin = Math.max(0.01, min);
        this.limits.radiusMax = Math.max(this.limits.radiusMin + 0.1, max);
        this.apply();
    }

    // ─── Vertical (pitch) ─────────────────────────────────────────────────────

    /**
     * Configures the vertical (pitch) rotation range.
     *
     * @param enabled  - Whether this specific limit is active.
     * @param upDeg    - Upper limit in degrees (negative = looking up, min −90).
     * @param downDeg  - Lower limit in degrees (positive = looking down, max +90).
     */
    setVerticalLimitsUpDown(enabled: boolean, upDeg: number, downDeg: number): void {
        this.limits.restrictVertical = enabled;
        this.limits.pitchMin = Math.max(-90, Math.min(upDeg, downDeg));
        this.limits.pitchMax = Math.min(90, Math.max(upDeg, downDeg));
        this.apply();
    }

    // ─── Horizontal (yaw) ─────────────────────────────────────────────────────

    /**
     * Configures the horizontal (yaw) rotation range as a total arc and centre offset.
     *
     * @param enabled     - Whether this specific limit is active.
     * @param totalAngle  - Total degrees of freedom (30–360).
     * @param offset      - Centre offset in degrees (−180–180).
     */
    setHorizontalLimitsAngleOffset(enabled: boolean, totalAngle: number, offset: number): void {
        this.limits.restrictHorizontal = enabled;
        const half = totalAngle / 2;
        this.limits.yawMin = offset - half;
        this.limits.yawMax = offset + half;
        this.apply();
    }

    // ─── Panning ──────────────────────────────────────────────────────────────

    /**
     * Enables or disables orbit panning (middle-mouse / right-click drag).
     * viewerState.panningEnabled is the single source of truth; InputController
     * reads it each frame.
     *
     * @param enabled - Whether panning should be allowed.
     */
    setPanningEnabled(enabled: boolean): void {
        viewerState.panningEnabled = enabled;
    }

    // ─── Reset ────────────────────────────────────────────────────────────────

    /**
     * Resets all limit values to their defaults while preserving the master
     * `enabled` toggle state.
     */
    resetToDefaults(): void {
        this.limits = {
            enabled: this.limits.enabled, // keep master toggle state
            restrictDistance:  DEFAULTS.restrict.distance,
            radiusMin:         DEFAULTS.zoom.min,
            radiusMax:         DEFAULTS.zoom.max,
            restrictVertical:  DEFAULTS.restrict.vertical,
            pitchMin:          DEFAULTS.vertical.upDeg,
            pitchMax:          DEFAULTS.vertical.downDeg,
            restrictHorizontal: DEFAULTS.restrict.horizontal,
            yawMin: DEFAULTS.horizontal.offset - DEFAULTS.horizontal.totalAngle / 2,
            yawMax: DEFAULTS.horizontal.offset + DEFAULTS.horizontal.totalAngle / 2,
        };
        viewerState.panningEnabled = DEFAULTS.restrict.panning;
        this.apply();
    }

    // ─── Apply to OrbitControllerPC ───────────────────────────────────────────

    /** Pushes the current limit state into the PlayCanvas orbit controller. */
    private apply(): void {
        const orbit = viewerState.cameraManager?.orbitController?.controller; // [PC API]
        if (!orbit) return;

        const { limits } = this;
        const disabled = !limits.enabled;

        // Zoom // [PC API]
        orbit.zoomRange = (disabled || !limits.restrictDistance)
            ? new Vec2(0.01, Infinity)
            : new Vec2(limits.radiusMin, limits.radiusMax);

        // Pitch (vertical) // [PC API]
        orbit.pitchRange = (disabled || !limits.restrictVertical)
            ? new Vec2(-90, 90)
            : new Vec2(limits.pitchMin, limits.pitchMax);

        // Yaw (horizontal) // [PC API]
        orbit.yawRange = (disabled || !limits.restrictHorizontal)
            ? new Vec2(-Infinity, Infinity)
            : new Vec2(limits.yawMin, limits.yawMax);
    }

    // ─── URL serialisation ────────────────────────────────────────────────────

    /**
     * Returns a flat record of URL parameter key/value pairs representing the
     * active limits.  Returns an empty object when limits are disabled.
     * Values use Babylon-compatible radians for angles so existing share links
     * remain valid.
     */
    getLimitsForUrl(): Record<string, string> {
        if (!this.limits.enabled) return {};
        const { limits } = this;
        return {
            ...(limits.restrictDistance && {
                radiusMin: limits.radiusMin.toFixed(2),
                radiusMax: limits.radiusMax.toFixed(2),
            }),
            ...(limits.restrictVertical && {
                betaMin:  ((limits.pitchMin + 90) * Math.PI / 180).toFixed(3),
                betaMax:  ((limits.pitchMax + 90) * Math.PI / 180).toFixed(3),
            }),
            ...(limits.restrictHorizontal && {
                alphaMin: (limits.yawMin * Math.PI / 180).toFixed(3),
                alphaMax: (limits.yawMax * Math.PI / 180).toFixed(3),
            }),
        };
    }
}

// ─── Singleton ────────────────────────────────────────────────────────────────

/**
 * Shared CameraLimits singleton.  Import and use this directly; do not
 * construct additional instances.
 */
const cameraLimits = new CameraLimits();

export { cameraLimits };
export type { LimitsState };
