/**
 * @file camera-manager.ts
 * Camera controller orchestrator. Owns and switches between OrbitController,
 * FlyController, WalkController, and AnimController. Handles auto-rotate idle
 * detection, spin-up easing, and per-frame camera state updates.
 */

import {
    type BoundingBox,
    Quat,
    Vec3
} from 'playcanvas';

import { createFigure8Track } from './animation/create-figure8-track';
import { createRotateTrack } from './animation/create-rotate-track';
import { AnimController } from './cameras/anim-controller';
import { Camera, type CameraFrame, type CameraController } from './cameras/camera';
import { FlyController } from './cameras/fly-controller';
import { OrbitController } from './cameras/orbit-controller';
import { WalkController } from './cameras/walk-controller';
import { WalkSource } from './cameras/walk-source';
import type { Collision } from './collision';
import { easeOut } from './core/math';
import { Annotation } from './settings';
import { CameraMode, Global } from './types';

const tmpCamera = new Camera();
const tmpv = new Vec3();
const tmpFwd = new Vec3();
const tmpQuat = new Quat();

const createCamera = (position: Vec3, target: Vec3, fov: number) => {
    const result = new Camera();
    result.look(position, target);
    result.fov = fov;
    return result;
};

const createFrameCamera = (bbox: BoundingBox, fov: number) => {
    const sceneSize = bbox.halfExtents.length();
    const distance = sceneSize / Math.sin(fov / 180 * Math.PI * 0.5);
    return createCamera(
        new Vec3(2, 1, 2).normalize().mulScalar(distance).add(bbox.center),
        bbox.center,
        fov
    );
};

class CameraManager {
    update: (deltaTime: number, cameraFrame: CameraFrame) => void;

    // holds the camera state
    camera = new Camera();

    // exposed for CameraLimits — the PlayCanvas OrbitControllerPC instance
    orbitController: OrbitController;

    // exposed so drag-drop / normalizeAndReframe can hot-swap collision at runtime
    walkController: WalkController;
    flyController: FlyController;

    constructor(global: Global, bbox: BoundingBox, collision: Collision | null = null) {
        const { events, settings, state } = global;

        const camera0 = settings.cameras[0]?.initial;
        const defaultFov = camera0?.fov ?? 75;
        const frameCamera = createFrameCamera(bbox, defaultFov);
        const resetCamera = camera0 ?
            createCamera(new Vec3(camera0.position), new Vec3(camera0.target), camera0.fov) :
            frameCamera;

        const getAnimTrack = (initial: Camera, isObjectExperience: boolean) => {
            const { animTracks } = settings;

            // extract the camera animation track from settings
            if (animTracks?.length > 0 && settings.startMode === 'animTrack') {
                // use the first animTrack
                return animTracks[0];
            } else if (isObjectExperience) {
                // create basic rotation animation if no anim track is specified
                initial.calcFocusPoint(tmpv);
                return createRotateTrack(initial.position, tmpv, initial.fov);
            }
            // non-object experience: gentle figure-8 motion from inside the scene
            initial.calcFocusPoint(tmpv);
            return createFigure8Track(initial.position, tmpv, initial.fov);

        };

        // object experience starts outside the bounding box
        const isObjectExperience = !bbox.containsPoint(resetCamera.position);
        const animTrack = getAnimTrack(resetCamera, isObjectExperience);

        const controllers = {
            orbit: new OrbitController(),
            fly: new FlyController(),
            walk: new WalkController(),
            anim: animTrack ? new AnimController(animTrack) : null
        };

        controllers.orbit.fov = resetCamera.fov;
        this.orbitController = controllers.orbit;
        this.walkController  = controllers.walk;
        this.flyController   = controllers.fly;
        controllers.fly.fov = resetCamera.fov;
        controllers.fly.collision = collision;
        controllers.walk.collision = collision;

        const walkSource = new WalkSource();
        walkSource.onComplete = () => {
            events.fire('walkComplete');
        };

        const getController = (cameraMode: CameraMode): CameraController => {
            return controllers[cameraMode] as CameraController;
        };

        // set the global animation flag
        state.hasAnimation = !!controllers.anim;
        state.animationDuration = controllers.anim ? controllers.anim.animState.cursor.duration : 0;

        // initialize camera mode and initial camera position
        state.cameraMode = state.hasAnimation ? 'anim' : (isObjectExperience ? 'orbit' : (collision ? 'walk' : 'fly'));
        this.camera.copy(resetCamera);

        const target = new Camera(this.camera);             // the active controller updates this
        const from = new Camera(this.camera);               // stores the previous camera state during transition
        const defaultMode: CameraMode = isObjectExperience ? 'orbit' : (collision ? 'walk' : 'fly');
        let fromMode: CameraMode = defaultMode;

        // tracks the mode to restore when exiting walk
        let preWalkMode: CameraMode = isObjectExperience ? 'orbit' : 'fly';

        // enter the initial controller
        getController(state.cameraMode).onEnter(this.camera);

        // transition state
        const DEFAULT_TRANSITION_SPEED = 1.0;
        let transitionSpeed = DEFAULT_TRANSITION_SPEED;
        let transitionTimer = 1;

        // auto-rotate state
        let autoRotateEnabled = true;
        let autoRotateSpeed = 0.7; // degrees per second (max speed)
        const autoRotateIdleWait = 5000; // ms before rotation starts
        const autoRotateSpinUpTime = 4000; // ms to reach full speed
        let lastInputTime = performance.now(); // track last user interaction
        let autoRotateCurrentSpeed = 0; // current interpolated speed

        // start a new camera transition from the current pose. `speed` controls
        // how fast the cross-fade reaches the target (1.0 = ~1s, 0.5 = ~2s).
        const startTransition = (speed = DEFAULT_TRANSITION_SPEED) => {
            from.copy(this.camera);
            transitionTimer = 0;
            transitionSpeed = speed;
        };

        // application update
        this.update = (deltaTime: number, frame: CameraFrame) => {

            // use dt of 0 if animation is paused
            const dt = state.cameraMode === 'anim' && state.animationPaused ? 0 : deltaTime;

            // update transition timer
            transitionTimer = Math.min(1, transitionTimer + deltaTime * transitionSpeed);

            // auto-rotate: idle-aware rotation with spin-up
            if (autoRotateEnabled && state.cameraMode === 'orbit' && transitionTimer >= 1) {
                const now = performance.now();
                const idleTime = now - lastInputTime;

                if (idleTime >= autoRotateIdleWait) {
                    // Spin-up: ramp from 0 to full speed over spinUpTime
                    const spinUpElapsed = idleTime - autoRotateIdleWait;
                    const spinUpFactor = Math.min(1, spinUpElapsed / autoRotateSpinUpTime);
                    autoRotateCurrentSpeed = autoRotateSpeed * spinUpFactor;

                    tmpCamera.copy(this.camera);
                    tmpCamera.calcFocusPoint(tmpv);
                    tmpCamera.angles.y += autoRotateCurrentSpeed * dt;
                    tmpQuat.setFromEulerAngles(tmpCamera.angles).transformVector(Vec3.FORWARD, tmpFwd);
                    tmpCamera.position.copy(tmpv).sub(tmpFwd.mulScalar(tmpCamera.distance));
                    controllers.orbit.goto(tmpCamera);
                } else {
                    autoRotateCurrentSpeed = 0;
                }
            } else {
                autoRotateCurrentSpeed = 0;
            }

            const controller = getController(state.cameraMode);

            if (state.cameraMode === 'walk') {
                walkSource.update(dt, this.camera.position, this.camera.angles, frame);
            }

            controller.update(dt, frame, target);

            if (transitionTimer < 1) {
                // lerp away from previous camera during transition
                this.camera.lerp(from, target, easeOut(transitionTimer));
            } else {
                this.camera.copy(target);
            }

            // update animation timeline
            if (state.cameraMode === 'anim') {
                state.animationTime = controllers.anim.animState.cursor.value;
            }
        };

        // handle input events
        events.on('inputEvent', (eventName, event) => {
            // Reset idle timer on clicks/drags/wheel/keyboard (not passive mouse movement)
            if (eventName === 'interrupt' || eventName === 'dblclick') {
                lastInputTime = performance.now();
                autoRotateCurrentSpeed = 0;
            }

            switch (eventName) {
                case 'gotoCamera': {
                    // payload: { position:[x,y,z], angles:[pitch,yaw,0], distance:n, fov:n, transitionSpeed?:n }
                    const p = event as { position: [number, number, number]; angles: [number, number, number]; distance: number; fov: number; transitionSpeed?: number };
                    if (p) {
                        const cam = new Camera();
                        cam.position.set(p.position[0], p.position[1], p.position[2]);
                        cam.angles.set(p.angles[0], p.angles[1], p.angles[2]);
                        cam.distance = p.distance;
                        cam.fov = p.fov;
                        state.cameraMode = 'orbit';
                        controllers.orbit.goto(cam);
                        controllers.orbit.fov = p.fov;
                        startTransition(p.transitionSpeed ?? DEFAULT_TRANSITION_SPEED);
                    }
                    break;
                }
                case 'setFov': {
                    const p = event as { fov: number };
                    if (p) {
                        controllers.orbit.fov = p.fov;
                        controllers.fly.fov = p.fov;
                    }
                    break;
                }
                case 'setAutoRotate': {
                    const p = event as { enabled: boolean; speed?: number };
                    if (p) {
                        autoRotateEnabled = p.enabled;
                        if (p.speed !== undefined) autoRotateSpeed = p.speed;
                        // Switch to orbit if enabling auto-rotate in another mode
                        if (p.enabled && state.cameraMode !== 'orbit') {
                            state.cameraMode = 'orbit';
                        }
                    }
                    break;
                }
                case 'frame':
                    state.cameraMode = 'orbit';
                    controllers.orbit.goto(frameCamera);
                    startTransition();
                    break;
                case 'reset':
                    state.cameraMode = 'orbit';
                    controllers.orbit.goto(resetCamera);
                    // Reset uses a gentler transition than other camera moves so the
                    // user can track the camera's path back to the home view.
                    startTransition(0.5);
                    break;
                case 'playPause':
                    if (state.hasAnimation) {
                        if (state.cameraMode === 'anim') {
                            state.animationPaused = !state.animationPaused;
                        } else {
                            state.cameraMode = 'anim';
                            state.animationPaused = false;
                        }
                    }
                    break;
                case 'requestFirstPerson':
                    // When collision is loaded, the user's intent is "walk" (terrain-aware).
                    // Fly remains accessible via the UI Fly button.
                    state.cameraMode = this.walkController.collision ? 'walk' : 'fly';
                    break;
                case 'toggleWalk': {
                    // Use the live walkController.collision (not the constructor-time closure)
                    // so hot-swapped collision (drag-drop) is reflected correctly.
                    const walkTarget: CameraMode = this.walkController.collision ? 'walk' : 'fly';
                    const isFirstPerson = state.cameraMode === 'walk' || state.cameraMode === 'fly';
                    if (isFirstPerson) {
                        state.cameraMode = preWalkMode;
                    } else {
                        preWalkMode = state.cameraMode;
                        state.cameraMode = walkTarget;
                    }
                    break;
                }
                case 'exitWalk':
                    if (state.cameraMode === 'walk' || state.cameraMode === 'fly') {
                        state.cameraMode = preWalkMode;
                    }
                    break;
                case 'cancel':
                    if (state.cameraMode === 'anim') {
                        state.cameraMode = fromMode;
                    }
                    break;
                case 'interrupt':
                    if (state.cameraMode === 'anim') {
                        state.cameraMode = fromMode;
                    }
                    break;
            }
        });

        // handle camera mode switching
        events.on('cameraMode:changed', (value, prev) => {
            if (prev === 'walk') {
                walkSource.cancelWalk();
            }

            // snapshot the current pose before any controller mutation
            startTransition();

            target.copy(this.camera);
            fromMode = prev;

            // exit the old controller
            const prevController = getController(prev);
            prevController.onExit(this.camera);

            // enter new controller
            const newController = getController(value);
            newController.onEnter(this.camera);
        });

        // handle user scrubbing the animation timeline
        events.on('scrubAnim', (time) => {
            // switch to animation camera if we're not already there
            state.cameraMode = 'anim';

            // set time
            controllers.anim.animState.cursor.value = time;
        });

        // handle user picking in the scene
        events.on('pick', (position: Vec3) => {
            // switch to orbit camera on pick
            state.cameraMode = 'orbit';

            // construct camera
            tmpCamera.copy(this.camera);
            tmpCamera.look(this.camera.position, position);

            controllers.orbit.goto(tmpCamera);
            startTransition();
        });

        events.on('annotation.activate', (annotation: Annotation) => {
            // switch to orbit camera on pick
            state.cameraMode = 'orbit';

            const { initial } = annotation.camera;

            // construct camera
            tmpCamera.fov = initial.fov;
            tmpCamera.look(
                new Vec3(initial.position),
                new Vec3(initial.target)
            );

            controllers.orbit.goto(tmpCamera);
            startTransition();
        });

        // tap-to-walk: start auto-walking toward a picked 3D position
        events.on('walkTo', (position: Vec3, normal: Vec3) => {
            if (state.cameraMode === 'walk') {
                walkSource.walkTo(position);
                events.fire('walkTarget:set', position, normal);
            }
        });

        // cancel any active auto-walk
        events.on('walkCancel', () => {
            walkSource.cancelWalk();
            events.fire('walkTarget:clear');
        });

        events.on('walkComplete', () => {
            events.fire('walkTarget:clear');
        });
    }
}

export { CameraManager };
