/**
 * @file controls.ts
 * Reusable UI control factory functions — engine-agnostic, pure DOM.
 *
 * Provides:
 *  - `createElement`            — typed wrapper around `document.createElement`
 *  - `setupEnhancedRangeControl`— syncs a range slider with a companion number input
 *  - `createToggleSwitch`       — returns HTML string for a labelled checkbox toggle
 *  - `createRangeControl`       — returns HTML string for a labelled slider + number input
 *  - `createColorControl`       — returns HTML string for a labelled colour picker
 */

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * Options accepted by {@link createElement}.
 * All fields are optional; only provided ones are applied to the element.
 */
type ElementOptions = {
    className?: string;
    innerHTML?: string;
    id?: string;
    value?: string;
    type?: string;
    accept?: string;
    placeholder?: string;
    attributes?: Record<string, string>;
};

// ─── Factory ──────────────────────────────────────────────────────────────────

/**
 * Creates a typed DOM element and applies the given options to it.
 *
 * @param tag     - HTML tag name (e.g. `'div'`, `'input'`).
 * @param options - Properties to set on the created element.
 * @returns The newly created element with the correct inferred type.
 */
function createElement<K extends keyof HTMLElementTagNameMap>(
    tag: K,
    options: ElementOptions = {}
): HTMLElementTagNameMap[K] {
    const element = document.createElement(tag);
    if (options.className) element.className = options.className;
    if (options.innerHTML) element.innerHTML = options.innerHTML;
    if (options.id) element.id = options.id;
    if (options.value !== undefined && 'value' in element) (element as HTMLInputElement).value = options.value;
    if (options.type && 'type' in element) (element as HTMLInputElement).type = options.type;
    if (options.accept && 'accept' in element) (element as HTMLInputElement).accept = options.accept;
    if (options.placeholder && 'placeholder' in element) (element as HTMLInputElement).placeholder = options.placeholder;
    if (options.attributes) {
        Object.entries(options.attributes).forEach(([key, value]) => element.setAttribute(key, value));
    }
    return element;
}

// ─── Enhanced range control ───────────────────────────────────────────────────

/**
 * Wires a range `<input>` and its companion number `<input>` so that changes
 * to either element are reflected in the other, and the optional `callback` is
 * invoked with the numeric value.
 *
 * Expects elements with ids `id` (slider) and `${id}Input` (number field).
 * The slider element may carry a `data-precision` attribute to control decimal
 * places shown in the number field.
 *
 * @param id       - Base element id.  Slider is `#id`, number input is `#idInput`.
 * @param callback - Optional callback called with the current numeric value on change.
 */
function setupEnhancedRangeControl(id: string, callback: ((value: number) => void) | null = null): void {
    const slider = document.getElementById(id) as HTMLInputElement | null;
    const input = document.getElementById(`${id}Input`) as HTMLInputElement | null;
    if (!slider || !input) return;

    const precision = parseInt(slider.dataset.precision ?? '0') || 0;
    let updating = false;

    slider.addEventListener('input', (e) => {
        if (updating) return;
        updating = true;
        const value = parseFloat((e.target as HTMLInputElement).value);
        input.value = precision > 0 ? value.toFixed(precision) : String(value);
        if (callback) callback(value);
        updating = false;
    });

    input.addEventListener('input', (e) => {
        if (updating) return;
        const rawValue = (e.target as HTMLInputElement).value;
        if (rawValue === '' || rawValue === '-' || rawValue === '.') return;
        const value = parseFloat(rawValue);
        if (isNaN(value)) return;
        const min = parseFloat(slider.min);
        const max = parseFloat(slider.max);
        if (value >= min && value <= max) {
            updating = true;
            slider.value = String(value);
            if (callback) callback(value);
            updating = false;
        }
    });

    input.addEventListener('blur', (e) => {
        if (updating) return;
        updating = true;
        let value = parseFloat((e.target as HTMLInputElement).value);
        if (isNaN(value) || (e.target as HTMLInputElement).value === '') {
            value = parseFloat(slider.value);
        } else {
            value = Math.max(parseFloat(slider.min), Math.min(parseFloat(slider.max), value));
        }
        const formatted = precision > 0 ? value.toFixed(precision) : String(value);
        (e.target as HTMLInputElement).value = formatted;
        slider.value = String(value);
        if (callback) callback(value);
        updating = false;
    });

    input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
    });
}

// ─── HTML string builders ─────────────────────────────────────────────────────

/**
 * Returns an HTML string for a labelled toggle switch (checkbox).
 *
 * @param id      - The `id` attribute of the `<input type="checkbox">`.
 * @param label   - Human-readable label text.
 * @param checked - Whether the toggle starts in the checked state.
 */
function createToggleSwitch(id: string, label: string, checked = false): string {
    return `
        <div class="control-group">
            <label for="${id}">${label}</label>
            <label class="switch">
                <input type="checkbox" id="${id}"${checked ? ' checked' : ''}>
                <span class="slider round"></span>
            </label>
        </div>
    `;
}

/**
 * Returns an HTML string for a labelled range slider with a companion number
 * input and optional unit suffix.
 *
 * The slider element receives a `data-precision` attribute derived from `step`
 * (or `forcedPrecision` if provided), which {@link setupEnhancedRangeControl}
 * reads to format the companion number input.
 *
 * @param id              - Base element id (slider is `#id`, number input is `#idInput`).
 * @param label           - Human-readable label text.
 * @param min             - Minimum slider value.
 * @param max             - Maximum slider value.
 * @param value           - Initial slider value.
 * @param step            - Slider step size. Defaults to `1`.
 * @param unit            - Optional unit label displayed after the number input.
 * @param forcedPrecision - Override decimal precision; derived from `step` when `null`.
 */
function createRangeControl(
    id: string, label: string,
    min: number, max: number, value: number,
    step = 1, unit = '', forcedPrecision: number | null = null
): string {
    // Derive decimal places from the step value string:
    // e.g. step=0.01 → String(step)="0.01" → split('.')[1]="01" → length=2.
    // When step has no decimal part (step >= 1), precision defaults to 0.
    const calculatedPrecision = step < 1 ? (String(step).split('.')[1] ?? '').length : 0;
    const precision = forcedPrecision !== null ? forcedPrecision : calculatedPrecision;
    const formattedValue = precision > 0 ? parseFloat(String(value)).toFixed(precision) : String(value);
    return `
        <div class="control-group">
            <label for="${id}">${label}</label>
            <div class="range-container enhanced">
                <input type="range" id="${id}" min="${min}" max="${max}" value="${value}"
                       step="${step}" class="slider-range enhanced"
                       data-precision="${precision}" data-unit="${unit}">
                <input type="number" id="${id}Input" min="${min}" max="${max}"
                       value="${formattedValue}" step="${step}" class="range-input" data-unit="${unit}">
                <span class="range-unit">${unit}</span>
            </div>
        </div>
    `;
}

/**
 * Returns an HTML string for a labelled colour picker with a text display of
 * the current hex value.
 *
 * @param id    - The `id` attribute of the `<input type="color">`.
 * @param label - Human-readable label text.
 * @param value - Initial hex colour value (e.g. `'#191919'`).
 */
function createColorControl(id: string, label: string, value = '#191919'): string {
    return `
        <div class="control-group">
            <label for="${id}">${label}</label>
            <div class="color-container">
                <input type="color" id="${id}" value="${value}" class="color-picker">
                <span id="${id}Display" class="color-value">${value}</span>
            </div>
        </div>
    `;
}

export {
    createElement,
    setupEnhancedRangeControl,
    createToggleSwitch,
    createRangeControl,
    createColorControl,
};
