/**
 * @file drag-drop.ts
 * Drag-and-drop file loading — PlayCanvas port of dragDrop.js.
 *
 * Supported splat formats : .ply, .sog, .splat, .spz
 * Supported collision formats:
 *   .glb              → MeshCollision (BVH over triangles)
 *   .voxel.json +
 *   .voxel.bin        → VoxelCollision (sparse octree, SuperSplat platform format)
 *                        Both files must be dropped together in the same drop.
 *
 * Drop combinations:
 *   - Splat file alone              → loads model, replaces previous
 *   - .glb alone                    → replaces collision on the walk controller
 *   - .voxel.json + .voxel.bin      → replaces collision on the walk controller
 *   - Splat + collision             → loads model AND sets collision in one drop
 */

import { MeshCollision, ScaledCollision, loadVoxelCollisionFromData } from '../collision/index.js';
import type { Collision, VoxelMetadata } from '../collision/index.js';
import { loadModelFromUrl, normalizeAndReframe, scaleWalkController } from './model-utils.js';
import { isGalleryManifest, activateGallery } from './gallery.js';
import type { Global } from '../types.js';
import { viewerState } from './viewer-state.js';
import { showToast } from './toast.js';
import { AUDIO_EXTENSIONS, loadAudioFromFile } from './audio-player.js';

// ─── Constants ────────────────────────────────────────────────────────────────

/** File extensions recognised as splat assets. */
const SPLAT_EXTENSIONS = new Set(['.ply', '.sog', '.splat', '.spz']);

/** CSS outline applied to the canvas while a dragged file is over the window. */
const DRAG_OUTLINE = '3px solid var(--cui-accent, #00aaff)';

// ─── Module-level blob URL state ─────────────────────────────────────────────

/**
 * Blob URL for the most recently loaded collision asset.
 * Revoked when a new collision file is dropped so the previous one is freed.
 */
let lastCollisionBlobUrl: string | undefined;

/**
 * Blob URL for the most recently drag-dropped splat asset.
 * Revoked when a new splat file is dropped so the previous one is freed.
 */
let lastSplatBlobUrl: string | undefined;

// ─── Pending voxel half-pair buffer ──────────────────────────────────────────

/**
 * Holds a single voxel file from a previous drop, waiting for its pair.
 * The user can drop .voxel.json and .voxel.bin in two separate events
 * instead of having to select both simultaneously.
 *
 * Cleared when a new splat model is loaded (the pending files belonged to
 * the previous scene) or when a complete pair is assembled.
 */
let pendingVoxelJson: File | null = null;
let pendingVoxelBin:  File | null = null;

/** Strips the compound voxel extension to get the bare base name. */
function voxelBase(filename: string): string {
    return filename.replace(/\.voxel\.(json|bin)$/i, '');
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns the lower-case file extension (including the dot) for `filename`,
 * or an empty string if the filename has no extension.
 *
 * @param filename - A file name string, e.g. `"model.ply"`.
 */
function ext(filename: string): string {
    const dot = filename.lastIndexOf('.');
    return dot === -1 ? '' : filename.slice(dot).toLowerCase();
}

// ─── Collision scale helper ───────────────────────────────────────────────────

/**
 * Wraps `collision` in a ScaledCollision using the current normalised scale so
 * walk-mode queries align with the normalised model.  Also scales the walk
 * controller's physical dimensions proportional to `sf` — this keeps the capsule
 * at ~2 voxels wide in the collision's original coordinate system regardless of
 * how much the model was scaled, preventing the O(radius_voxels³) bounding-box
 * blowup that freezes the browser on large normalisation factors.
 */
function applyNormalizedScale(collision: Collision): Collision {
    const sf = viewerState.normalizedScale;
    scaleWalkController(sf); // keep capsule ≈2 voxels in original space
    return sf !== 1 ? new ScaledCollision(collision, sf) : collision;
}

// ─── Collision loader ─────────────────────────────────────────────────────────

/**
 * Loads a collision mesh from a dropped `.glb` file and hot-swaps it onto the
 * walk controller.  The blob URL is revoked once replaced.
 *
 * ## Coordinate system
 * GLB collision meshes must be exported at **visual (world-normalized) scale** —
 * the same scale you see in the viewer after `normalizeAndReframe` runs.
 * They are used *without* `ScaledCollision` wrapping, because:
 *
 *   - Voxel data is in the scene's *original* (pre-normalization) coordinate
 *     system, so `ScaledCollision(sf)` maps world-space queries into original
 *     space. e.g. for a 316-unit scene normalized to 2 world units (sf≈0.006),
 *     `ScaledCollision` multiplies queries by 1/sf ≈ 158 before querying.
 *   - A GLB exported to match the visual model is already in world space.
 *     Applying `ScaledCollision(sf)` would multiply those queries by ~158 and
 *     place every ray cast hundreds of units outside the mesh bounds → all misses.
 *
 * Walk-controller capsule parameters (`eyeHeight`, `capsuleRadius`, etc.) are
 * still scaled by `sf` via `scaleWalkController(sf)` — they remain correct
 * for world-space queries since they were designed for the original scale.
 *
 * ## Export checklist (Blender)
 * - Apply all transforms before exporting (`Object → Apply → All Transforms`)
 * - Export as glTF Binary (.glb)
 * - "Apply Modifiers" checked
 * - Coordinate system: Y Up (default glTF setting)
 * - Scale the mesh in Blender to match the visual model you see in the viewer
 *
 * @param file - The dropped `.glb` File object.
 */
async function applyCollision(file: File): Promise<void> {
    const app = viewerState.app;
    const cm = viewerState.cameraManager;
    if (!app || !cm) { showToast('Viewer not ready'); return; }

    showToast('Loading collision…');

    const blobUrl = URL.createObjectURL(file);

    try {
        const collision = await MeshCollision.fromGlb(app, blobUrl); // [PC API]

        // Revoke the PREVIOUS blob only after the new one has fully loaded.
        // Revoking before load completes would invalidate the in-flight fetch.
        if (lastCollisionBlobUrl) URL.revokeObjectURL(lastCollisionBlobUrl);
        lastCollisionBlobUrl = blobUrl;

        // ── Debug: log mesh bounds so we can verify coordinate alignment ────────
        const bounds = collision.getBounds();
        const sf = viewerState.normalizedScale;
        const cam = viewerState.cameraManager?.camera;
        console.group('[GLB collision] loaded:', file.name);
        console.log(`  triangles     : ${collision.triangleCount}`);
        console.log(`  raw bounds X  : [${bounds.minX.toFixed(3)}, ${bounds.maxX.toFixed(3)}]`);
        console.log(`  raw bounds Y  : [${bounds.minY.toFixed(3)}, ${bounds.maxY.toFixed(3)}]`);
        console.log(`  raw bounds Z  : [${bounds.minZ.toFixed(3)}, ${bounds.maxZ.toFixed(3)}]`);
        console.log(`  normalizedScale (sf): ${sf}`);
        if (cam) {
            const p = cam.position;
            console.log(`  camera world  : [${p.x.toFixed(3)}, ${p.y.toFixed(3)}, ${p.z.toFixed(3)}]`);
        }
        console.groupEnd();

        // GLB meshes are exported at visual (world-normalized) scale — they
        // already live in the same coordinate space as walk-controller queries.
        // ScaledCollision would wrongly divide world positions by sf (×~158),
        // placing every query far outside the mesh bounds. Use the raw collision
        // directly. scaleWalkController(sf) is still called so the capsule
        // dimensions stay proportional in world space.
        scaleWalkController(sf);
        cm.walkController.collision = collision;
        if (cm.flyController) cm.flyController.collision = collision;
        viewerState.collisionUrl = ''; // blob — not shareable
        viewerState.events?.fire('collisionLoaded'); // [PC API] update state + auto-switch
        showToast(`Collision loaded: ${file.name}`);
    } catch (err) {
        // Load failed — revoke the new blob (nothing replaced the old one)
        URL.revokeObjectURL(blobUrl);
        showToast(`Collision failed: ${file.name}`);
        console.error('MeshCollision load error:', err);
    }
}

// ─── Voxel collision loader ───────────────────────────────────────────────────

/**
 * Loads a VoxelCollision from a pair of File objects (.voxel.json + .voxel.bin)
 * and hot-swaps it onto the walk controller.
 * Exported so the dev-panel file picker can reuse it without going through drag-drop.
 *
 * @param jsonFile - The `.voxel.json` metadata file.
 * @param binFile  - The `.voxel.bin` binary file.
 */
export async function applyVoxelCollision(jsonFile: File, binFile: File): Promise<void> {
    const cm = viewerState.cameraManager;
    if (!cm) { showToast('Viewer not ready'); return; }

    showToast('Loading voxel collision…');

    try {
        const [jsonText, binBuffer] = await Promise.all([jsonFile.text(), binFile.arrayBuffer()]);
        const metadata: VoxelMetadata = JSON.parse(jsonText);
        const collision = loadVoxelCollisionFromData(metadata, binBuffer);

        // Diagnostic: log collision metadata so the user can verify alignment
        console.log(`[collision] version=${metadata.version}, flipXY=${'flipXY' in collision && (collision as any).flipXY}`);
        console.log(`[collision] grid bounds: min=[${metadata.gridBounds.min}] max=[${metadata.gridBounds.max}]`);
        console.log(`[collision] normalizedScale=${viewerState.normalizedScale}`);

        const scaled = applyNormalizedScale(collision);
        cm.walkController.collision = scaled;
        if (cm.flyController) cm.flyController.collision = scaled;
        viewerState.collisionUrl = ''; // in-memory only — not shareable
        viewerState.events?.fire('collisionLoaded'); // [PC API] update state + auto-switch
        showToast(`Voxel collision loaded: ${jsonFile.name}`);
    } catch (err) {
        showToast(`Voxel collision failed: ${jsonFile.name}`);
        console.error('VoxelCollision load error:', err);
    }
}

// ─── Splat loader ─────────────────────────────────────────────────────────────

/**
 * Loads a gsplat model from a dropped `.ply` or `.sog` file, destroying any
 * previously loaded splat entity to free VRAM.
 *
 * @param global - The PlayCanvas Global context object.
 * @param file   - The dropped splat File object.
 */
async function loadSplat(global: Global, file: File): Promise<void> {
    const { app, events } = global;
    const filename = file.name;

    // Discard any pending voxel half-pair — it belonged to the previous scene.
    pendingVoxelJson = null;
    pendingVoxelBin  = null;

    showToast('Loading…');

    const blobUrl = URL.createObjectURL(file);

    try {
        const entity = await loadModelFromUrl(app, blobUrl, filename);

        // Revoke the PREVIOUS blob only after the new one has fully loaded.
        if (lastSplatBlobUrl) URL.revokeObjectURL(lastSplatBlobUrl);
        lastSplatBlobUrl = blobUrl;

        viewerState.contentUrl = ''; // blob — not shareable
        // Normalise scale and reframe camera after one frame so customAabb is
        // populated and the orbit controller is ready to receive gotoCamera.
        app.once('frameend', () => normalizeAndReframe(entity, events)); // [PC API]
        showToast(`Loaded: ${filename}`);
    } catch (err) {
        // Load failed — revoke the new blob (nothing replaced the old one)
        URL.revokeObjectURL(blobUrl);
        showToast(`Failed: ${filename}`);
        console.error('Splat load error:', err);
    }
}

// ─── Drop handler ─────────────────────────────────────────────────────────────

/**
 * Dispatches the dropped files to the appropriate loader(s).
 * Splat and collision loads run in parallel when both are dropped at once.
 *
 * @param global - The PlayCanvas Global context object.
 * @param files  - Array of files from the drop event.
 */
async function handleDrop(global: Global, files: File[]): Promise<void> {
    const splatFile     = files.find(f => SPLAT_EXTENSIONS.has(ext(f.name)));
    const glbFile       = files.find(f => ext(f.name) === '.glb');
    const voxelJsonFile = files.find(f => f.name.endsWith('.voxel.json'));
    const voxelBinFile  = files.find(f => f.name.endsWith('.voxel.bin'));
    const audioFile     = files.find(f => AUDIO_EXTENSIONS.has(ext(f.name)));
    const jsonFile      = files.find(f => ext(f.name) === '.json' && !f.name.endsWith('.voxel.json'));

    const isKnown = (f: File) =>
        SPLAT_EXTENSIONS.has(ext(f.name)) ||
        ext(f.name) === '.glb' ||
        ext(f.name) === '.json' ||
        f.name.endsWith('.voxel.json') ||
        f.name.endsWith('.voxel.bin') ||
        AUDIO_EXTENSIONS.has(ext(f.name));

    const unknown = files.filter(f => !isKnown(f));
    const hasAnyKnown = splatFile || glbFile || voxelJsonFile || voxelBinFile || audioFile || jsonFile;

    if (unknown.length > 0 && !hasAnyKnown) {
        showToast(`Unsupported: ${unknown[0].name}`);
        return;
    }

    // Gallery JSON — takes priority over everything else in the drop
    if (jsonFile) {
        try {
            const text = await jsonFile.text();
            const data = JSON.parse(text);
            if (isGalleryManifest(data)) {
                showToast(`Gallery: ${jsonFile.name}`);
                await activateGallery(global, data);
                return;
            }
            showToast(`Not a gallery manifest: ${jsonFile.name}`);
        } catch {
            showToast(`Invalid JSON: ${jsonFile.name}`);
        }
        return;
    }

    // ── Voxel collision — supports sequential single-file drops ───────────────
    // The user can drop .voxel.json and .voxel.bin in two separate events.
    // Each half is buffered until its pair arrives.
    let voxelReady: { json: File; bin: File } | null = null;

    if (voxelJsonFile && voxelBinFile) {
        // Both files in this drop — immediate load, clear any stale buffer.
        voxelReady = { json: voxelJsonFile, bin: voxelBinFile };
        pendingVoxelJson = null;
        pendingVoxelBin  = null;
    } else if (voxelJsonFile) {
        const base = voxelBase(voxelJsonFile.name);
        if (pendingVoxelBin) {
            if (voxelBase(pendingVoxelBin.name) === base) {
                // Completes the pending pair.
                voxelReady = { json: voxelJsonFile, bin: pendingVoxelBin };
                pendingVoxelJson = null;
                pendingVoxelBin  = null;
            } else {
                // Name mismatch — replace the pending slot.
                pendingVoxelJson = voxelJsonFile;
                pendingVoxelBin  = null;
                showToast(`Saved ${voxelJsonFile.name} — drop ${base}.voxel.bin`);
            }
        } else {
            pendingVoxelJson = voxelJsonFile;
            showToast(`Saved ${voxelJsonFile.name} — now drop ${base}.voxel.bin`);
        }
    } else if (voxelBinFile) {
        const base = voxelBase(voxelBinFile.name);
        if (pendingVoxelJson) {
            if (voxelBase(pendingVoxelJson.name) === base) {
                // Completes the pending pair.
                voxelReady = { json: pendingVoxelJson, bin: voxelBinFile };
                pendingVoxelJson = null;
                pendingVoxelBin  = null;
            } else {
                // Name mismatch — replace the pending slot.
                pendingVoxelBin  = voxelBinFile;
                pendingVoxelJson = null;
                showToast(`Saved ${voxelBinFile.name} — drop ${base}.voxel.json`);
            }
        } else {
            pendingVoxelBin = voxelBinFile;
            showToast(`Saved ${voxelBinFile.name} — now drop ${base}.voxel.json`);
        }
    }

    // Run splat + collision in parallel — splat load takes longer, collision is fast
    const tasks: Promise<void>[] = [];
    if (splatFile) tasks.push(loadSplat(global, splatFile));
    if (voxelReady) tasks.push(applyVoxelCollision(voxelReady.json, voxelReady.bin));
    else if (glbFile) tasks.push(applyCollision(glbFile));

    // Audio is synchronous setup (no await needed)
    if (audioFile) {
        loadAudioFromFile(audioFile);
        showToast(`Audio loaded: ${audioFile.name}`);
    }

    await Promise.all(tasks);

    if (splatFile && (voxelReady || glbFile)) {
        showToast('Loaded model + collision');
    }
}

// ─── Setup ────────────────────────────────────────────────────────────────────

/**
 * Attaches drag-and-drop event listeners to the document.
 * A visual outline is shown on the canvas while files are dragged over the
 * window so the user has feedback that a drop is possible.
 *
 * @param global - The PlayCanvas Global context object.
 */
export function setupDragDrop(global: Global): void {
    const canvas = global.app.graphicsDevice.canvas; // [PC API]

    document.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer!.dropEffect = 'copy';
    });

    document.addEventListener('drop', (e) => {
        e.preventDefault();
        canvas.style.outline = '';
        const files = Array.from(e.dataTransfer?.files ?? []);
        if (files.length > 0) handleDrop(global, files).catch(() => {});
    });

    document.addEventListener('dragenter', (e) => {
        if (Array.from(e.dataTransfer?.items ?? []).some(i => i.kind === 'file')) {
            canvas.style.outline = DRAG_OUTLINE;
        }
    });

    document.addEventListener('dragleave', (e) => {
        if (e.relatedTarget === null) canvas.style.outline = '';
    });
}
