/**
 * @file gallery.ts
 * Multi-model gallery — album-style navigation between related splat models.
 *
 * Activated when the viewer is loaded with ?gallery=<manifest-url>.
 * Each entry in the manifest is a share URL generated by the viewer's Share
 * button — no custom authoring format needed.
 *
 * Navigation flow for each model:
 *   1. Decompress share URL params
 *   2. Load model via loadModelFromUrl
 *   3. Wait for frameend → normalizeAndReframe (scale normalisation + home camera)
 *   4. If share URL has baked camera params → override with applyCameraFromUrl
 *   5. Apply baked settings (background, render scale, etc.)
 *   6. Load collision + audio from share URL params if present
 *   7. Update nav bar UI
 */

import { MeshCollision, ScaledCollision, loadVoxelCollision } from '../collision/index.js';
import type { Collision } from '../collision/index.js';
import { loadModelFromUrl, normalizeAndReframe, scaleWalkController } from './model-utils.js';
import { decompressUrlParameters, applyCameraFromUrl, applySettingsFromUrl } from './urlManager.js';
import { setupAudioPlayer, destroyAudioPlayer } from './audio-player.js';
import { showToast } from './toast.js';
import { viewerState } from './viewer-state.js';
import type { Global, GalleryManifest } from '../types.js';

// ─── Module state ─────────────────────────────────────────────────────────────

let _global: Global | null = null;
let _manifest: GalleryManifest | null = null;
let _currentIndex = 0;
let _isLoading = false;
/** The URL the manifest was fetched from. Used to restore viewerState.galleryUrl
 *  after loadModelFromUrl clears it on every model load. */
let _manifestUrl = '';

// ─── Public API ───────────────────────────────────────────────────────────────

/** Returns true when a gallery manifest has been loaded. */
export function isGalleryActive(): boolean {
    return _manifest !== null;
}

/**
 * Validates that a parsed JSON object looks like a gallery manifest.
 * Returns `true` if it has at least one entry with a `shareUrl` string.
 * Only the first entry is checked — individual entries are validated lazily
 * in `navigateTo` via the `if (!contentUrl)` guard.
 */
export function isGalleryManifest(data: unknown): data is GalleryManifest {
    if (!data || typeof data !== 'object') return false;
    const d = data as Record<string, unknown>;
    if (!Array.isArray(d.models) || d.models.length === 0) return false;
    return typeof (d.models[0] as Record<string, unknown>).shareUrl === 'string';
}

/**
 * Initialises gallery mode from a parsed manifest and immediately loads the
 * first model.  Call this when a gallery JSON is drag-dropped or picked via
 * the dev panel file button — i.e. when the viewer is already running.
 *
 * @param global      - PlayCanvas Global context.
 * @param manifest    - Already-parsed and validated gallery manifest.
 * @param manifestUrl - Optional URL the manifest was fetched from.  Stored in
 *                      `viewerState.galleryUrl` so the Share button can include
 *                      `gallery=<url>` in the generated link.
 */
export async function activateGallery(global: Global, manifest: GalleryManifest, manifestUrl = ''): Promise<void> {
    _manifestUrl = manifestUrl;
    viewerState.galleryUrl = manifestUrl;

    // If loaded from a local file (no manifest URL) and the page URL still has a
    // ?gallery= param from a previous URL-based session, strip it so the Share
    // button doesn't re-inject the old (stale) manifest URL into share links.
    if (!manifestUrl && new URLSearchParams(location.search).has('gallery')) {
        const p = new URLSearchParams(location.search);
        p.delete('gallery');
        const qs = p.toString();
        history.replaceState(null, '', qs ? `${location.pathname}?${qs}` : location.pathname);
    }

    initGallery(global, manifest);
    await navigateTo(0);
}

/**
 * Initialises the gallery with the given manifest and immediately shows
 * the nav bar.  The first model is assumed to already be loaded (by index.html
 * + index.ts eager fetch) — this only builds the UI.
 *
 * @param global   - PlayCanvas Global context.
 * @param manifest - Parsed gallery manifest.
 */
export function initGallery(global: Global, manifest: GalleryManifest, manifestUrl = ''): void {
    _global   = global;
    _manifest = manifest;
    _currentIndex = 0;
    viewerState.galleryIndex = 0;
    if (manifestUrl) _manifestUrl = manifestUrl;

    _buildNavBar(manifest.models.length);
    _updateNavUI();
}

/**
 * Navigates to the model at `index` in the manifest.
 * No-op if already loading or if index is out of range.
 */
export async function navigateTo(index: number): Promise<void> {
    if (!_global || !_manifest) return;
    if (_isLoading) return;
    if (index < 0 || index >= _manifest.models.length) return;

    _isLoading = true;
    _setNavEnabled(false);

    const entry = _manifest.models[index];

    if (typeof entry.shareUrl !== 'string') {
        showToast('Gallery entry has no share URL');
        _isLoading = false;
        _setNavEnabled(true);
        return;
    }

    const params = decompressUrlParameters(entry.shareUrl);
    const rawContentUrl = params.get('content') ?? '';
    // When the manifest is hosted alongside the models the share URL may use
    // bare filenames or relative paths (e.g. "model-a.sog"). Resolve those
    // against the manifest URL rather than the viewer's page URL.
    const contentUrl = _resolveRelativeToManifest(rawContentUrl);

    if (!contentUrl) {
        showToast('Gallery entry has no content URL');
        _isLoading = false;
        _setNavEnabled(true);
        return;
    }

    const filename = new URL(contentUrl, location.href).pathname.split('/').pop() || 'model.sog';
    showToast('Loading…');

    try {
        const { app, events } = _global;

        // Load the model (clears collision overlay, resets normalizedScale, clears galleryUrl)
        const entity = await loadModelFromUrl(app, contentUrl, filename);
        // Restore gallery state that loadModelFromUrl unconditionally clears
        viewerState.galleryUrl   = _manifestUrl;
        viewerState.galleryIndex = index;
        viewerState.contentUrl   = contentUrl;

        const hasCamera = params.has('camPosX') && params.has('camAngY') && params.has('camDist');

        // Start collision load in parallel while we wait for the next frame
        const collisionUrl = _resolveRelativeToManifest(params.get('collision') ?? '');
        let collisionPromise: Promise<Collision | null> | undefined;
        if (collisionUrl) {
            collisionPromise = (_loadCollisionFromUrl(app, collisionUrl) as Promise<Collision | null>)
                .catch((err: unknown): null => { console.warn('Gallery collision load failed:', err); return null; });
        }

        // Wait for next frame: normalizeAndReframe scales the model and fires home camera.
        // If the share URL has a baked camera we override it immediately after.
        // 8-second timeout guards against the tab being throttled (background, battery
        // saver, GPU stall) — without it _isLoading stays true and nav locks permanently.
        // Cancellation flag prevents the stale frameend callback from corrupting state
        // when the timeout fires first.
        let frameendFired = false;
        let timedOut = false;
        await Promise.race([
            new Promise<void>(resolve => {
                app.once('frameend', () => { // [PC API]
                    if (timedOut) return;
                    frameendFired = true;
                    normalizeAndReframe(entity, events);
                    if (hasCamera) {
                        applyCameraFromUrl(_global!, params);
                    }
                    resolve();
                });
            }),
            new Promise<void>((_, reject) =>
                setTimeout(() => {
                    if (frameendFired) return;
                    timedOut = true;
                    reject(new Error('frameend timeout — tab may be throttled'));
                }, 8000)
            ),
        ]);

        // Restore settings (background, render scale, sharpen, audio volume…)
        applySettingsFromUrl(_global!, params);

        // Apply collision now that normalizedScale is set by normalizeAndReframe
        if (collisionPromise) {
            const collision = await collisionPromise;
            const cm = viewerState.cameraManager;
            if (collision && cm) {
                const sf = viewerState.normalizedScale;
                const scaled = sf !== 1 ? new ScaledCollision(collision, sf) : collision;
                // Scale walk params to prevent O(radius_voxels³) bounding-box blowup
                scaleWalkController(sf);
                cm.walkController.collision = scaled;
                if (cm.flyController) cm.flyController.collision = scaled;
                viewerState.collisionUrl = collisionUrl;
                viewerState.events?.fire('collisionLoaded'); // show Walk button + auto-switch
            }
        }

        // Audio — setupAudioPlayer handles stop/start internally
        const audioUrl = params.get('audio') ?? '';
        if (audioUrl) {
            setupAudioPlayer(audioUrl);
            viewerState.audioUrl = audioUrl;
        } else {
            // No audio in this entry — stop any previous audio
            destroyAudioPlayer();
            viewerState.audioUrl = '';
        }

        _currentIndex = index;
        viewerState.galleryIndex = index;
        _updateNavUI();
        showToast(entry.title ? `${entry.title}` : `Model ${index + 1} / ${_manifest!.models.length}`);
    } catch (err) {
        showToast(`Failed to load model ${index + 1}`);
        console.error('Gallery navigateTo error:', err);
        // Restore index so nav bar and share URL reflect the model that is actually visible
        viewerState.galleryIndex = _currentIndex;
    } finally {
        _isLoading = false;
        _setNavEnabled(true);
    }
}

/** Navigates to the next model, wrapping around. */
export function navigateNext(): void {
    if (!_manifest) return;
    navigateTo((_currentIndex + 1) % _manifest.models.length);
}

/** Navigates to the previous model, wrapping around. */
export function navigatePrev(): void {
    if (!_manifest) return;
    navigateTo((_currentIndex - 1 + _manifest.models.length) % _manifest.models.length);
}

// ─── URL helpers ──────────────────────────────────────────────────────────────

/**
 * Resolves a (possibly relative) URL from inside a share URL against the
 * manifest URL when one is known. Lets users author share entries with bare
 * filenames like `?content=model-a.sog` when the gallery JSON sits alongside
 * the models. Returns the input unchanged when no manifest URL is set or the
 * input is already absolute / blob.
 */
function _resolveRelativeToManifest(url: string): string {
    if (!url) return url;
    if (!_manifestUrl) return url;
    // Skip absolute URLs (http/https/blob/data) — they're already complete.
    if (/^(https?:|blob:|data:)/i.test(url)) return url;
    try {
        // The manifest URL may itself be relative — resolve it against the page first.
        const manifestAbs = new URL(_manifestUrl, location.href).href;
        return new URL(url, manifestAbs).href;
    } catch {
        return url;
    }
}

// ─── Collision loader ─────────────────────────────────────────────────────────

async function _loadCollisionFromUrl(app: any, url: string): Promise<Collision> {
    const ext = new URL(url, location.href).pathname.split('.').pop()?.toLowerCase();
    if (ext === 'glb') {
        return MeshCollision.fromGlb(app, url); // [PC API]
    }
    return loadVoxelCollision(url);
}

// ─── Nav bar DOM ──────────────────────────────────────────────────────────────

let _navBar: HTMLElement | null = null;
let _dots: HTMLButtonElement[] = [];
let _titleEl: HTMLElement | null = null;
let _prevBtn: HTMLButtonElement | null = null;
let _nextBtn: HTMLButtonElement | null = null;

let _keydownListener: ((e: KeyboardEvent) => void) | null = null;

function _buildNavBar(count: number): void {
    if (_navBar) _navBar.remove();

    // Remove previous keyboard listener before registering a new one
    if (_keydownListener) {
        document.removeEventListener('keydown', _keydownListener);
        _keydownListener = null;
    }

    const bar = document.createElement('div');
    bar.className = 'gallery-nav';
    bar.id = 'galleryNav';

    // Prev button
    const prevBtn = document.createElement('button');
    prevBtn.className = 'gallery-arrow';
    prevBtn.id = 'galleryPrev';
    prevBtn.setAttribute('aria-label', 'Previous model');
    prevBtn.innerHTML = '&#8249;';
    prevBtn.addEventListener('click', () => navigatePrev());
    _prevBtn = prevBtn;

    // Title
    const title = document.createElement('span');
    title.className = 'gallery-title';
    title.id = 'galleryTitle';
    _titleEl = title;

    // Dots
    const dotsWrap = document.createElement('div');
    dotsWrap.className = 'gallery-dots';
    _dots = [];
    for (let i = 0; i < count; i++) {
        const dot = document.createElement('button');
        dot.className = 'gallery-dot';
        dot.setAttribute('aria-label', `Go to model ${i + 1}`);
        const idx = i;
        dot.addEventListener('click', () => navigateTo(idx));
        dotsWrap.appendChild(dot);
        _dots.push(dot);
    }

    // Next button
    const nextBtn = document.createElement('button');
    nextBtn.className = 'gallery-arrow';
    nextBtn.id = 'galleryNext';
    nextBtn.setAttribute('aria-label', 'Next model');
    nextBtn.innerHTML = '&#8250;';
    nextBtn.addEventListener('click', () => navigateNext());
    _nextBtn = nextBtn;

    bar.appendChild(prevBtn);
    bar.appendChild(title);
    bar.appendChild(dotsWrap);
    bar.appendChild(nextBtn);
    document.body.appendChild(bar);
    _navBar = bar;

    // Keyboard navigation — stored so it can be removed on re-activation
    _keydownListener = (e: KeyboardEvent) => {
        if (!isGalleryActive()) return;
        const tag = (document.activeElement as HTMLElement)?.tagName?.toLowerCase();
        if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
        if (e.key === 'ArrowLeft')  { e.preventDefault(); navigatePrev(); }
        if (e.key === 'ArrowRight') { e.preventDefault(); navigateNext(); }
    };
    document.addEventListener('keydown', _keydownListener);
}

function _updateNavUI(): void {
    if (!_manifest) return;

    // Update dots
    _dots.forEach((dot, i) => {
        dot.classList.toggle('active', i === _currentIndex);
    });

    // Update title
    const entry = _manifest.models[_currentIndex];
    if (_titleEl) {
        _titleEl.textContent = entry.title
            ? `${entry.title} (${_currentIndex + 1} / ${_manifest.models.length})`
            : `${_currentIndex + 1} / ${_manifest.models.length}`;
    }

    // Hide prev/next arrows when only one model
    if (_prevBtn) _prevBtn.style.visibility = _manifest.models.length > 1 ? '' : 'hidden';
    if (_nextBtn) _nextBtn.style.visibility = _manifest.models.length > 1 ? '' : 'hidden';
}

function _setNavEnabled(enabled: boolean): void {
    if (_prevBtn) _prevBtn.disabled = !enabled;
    if (_nextBtn) _nextBtn.disabled = !enabled;
    _dots.forEach(d => { d.disabled = !enabled; });
}
