/**
 * @file splat-parser.ts
 * Parser for the .splat binary format (antimatter15/splat convention).
 *
 * Layout: 32 bytes per splat, tightly packed:
 *   - position : 3 × float32 (x, y, z)
 *   - scale    : 3 × float32 (LINEAR scale — antimatter15 convert.py applies exp())
 *   - color    : 4 × uint8   (r, g, b, opacity  — 0-255 linear)
 *   - rotation : 4 × uint8   (rot_0 … rot_3     — 0-255 → -1..1)
 *
 * Conversion to PlayCanvas GSplatData format:
 *   - f_dc_0/1/2 : SH0 coefficients → (c / 255 - 0.5) / SH_C0
 *   - opacity    : inverse-sigmoid   → -ln(255 / o - 1)
 *   - rot_*      : float quaternion  → (v / 128 - 1), then normalise
 *   - scale_*    : log(linear_scale) — PlayCanvas applies exp() in createIter,
 *                  so we must convert back to log-space to avoid double-exp
 *
 * ENGINE UPGRADE: If PlayCanvas adds native .splat support, remove this file
 * and the `gsplatHandler.parsers.splat` registration in index.ts.
 */

import type { AppBase, Asset } from 'playcanvas';
import { fetchBinaryWithProgress, buildVertexElement, createGSplatResource } from './parser-utils';

const SH_C0 = 0.28209479177387814;
const BYTES_PER_SPLAT = 32;

class SplatParser {
    app: AppBase;
    maxRetries: number;

    constructor(app: AppBase, maxRetries = 0) {
        this.app = app;
        this.maxRetries = maxRetries;
    }

    async load(
        url: { load: string; original: string } | string,
        callback: (err: string | null, resource?: any) => void,
        asset: Asset,
    ) {
        try {
            const buffer = await fetchBinaryWithProgress(url, asset);
            const numSplats = Math.floor(buffer.byteLength / BYTES_PER_SPLAT);

            if (numSplats === 0) {
                callback('Empty or invalid .splat file');
                return;
            }

            // Allocate output arrays
            const x = new Float32Array(numSplats);
            const y = new Float32Array(numSplats);
            const z = new Float32Array(numSplats);
            const scale_0 = new Float32Array(numSplats);
            const scale_1 = new Float32Array(numSplats);
            const scale_2 = new Float32Array(numSplats);
            const f_dc_0 = new Float32Array(numSplats);
            const f_dc_1 = new Float32Array(numSplats);
            const f_dc_2 = new Float32Array(numSplats);
            const opacity = new Float32Array(numSplats);
            const rot_0 = new Float32Array(numSplats);
            const rot_1 = new Float32Array(numSplats);
            const rot_2 = new Float32Array(numSplats);
            const rot_3 = new Float32Array(numSplats);

            const dataView = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);

            const EPS = 1e-12;
            for (let i = 0; i < numSplats; i++) {
                const base = i * BYTES_PER_SPLAT;

                // Position (3 × float32, little-endian)
                x[i] = dataView.getFloat32(base + 0, true);
                y[i] = dataView.getFloat32(base + 4, true);
                z[i] = dataView.getFloat32(base + 8, true);

                // Scale (3 × float32, LINEAR in antimatter15 format)
                // antimatter15 convert.py applies exp() when writing .splat,
                // so values are linear. PlayCanvas createIter applies exp()
                // expecting log-scale → we must convert back to log-space.
                // Clamp to epsilon to avoid Math.log(0) = -Infinity.
                scale_0[i] = Math.log(Math.max(EPS, dataView.getFloat32(base + 12, true)));
                scale_1[i] = Math.log(Math.max(EPS, dataView.getFloat32(base + 16, true)));
                scale_2[i] = Math.log(Math.max(EPS, dataView.getFloat32(base + 20, true)));

                // Color (4 × uint8 → SH0 coefficients + logit opacity)
                const r = buffer[base + 24];
                const g = buffer[base + 25];
                const b = buffer[base + 26];
                const a = buffer[base + 27];

                f_dc_0[i] = (r / 255 - 0.5) / SH_C0;
                f_dc_1[i] = (g / 255 - 0.5) / SH_C0;
                f_dc_2[i] = (b / 255 - 0.5) / SH_C0;

                // Inverse sigmoid for opacity: clamp to avoid Infinity
                const aClamped = Math.max(1, Math.min(254, a));
                opacity[i] = -Math.log(255 / aClamped - 1);

                // Rotation (4 × uint8 → normalised quaternion)
                let rw = (buffer[base + 28] / 128) - 1;
                let rx = (buffer[base + 29] / 128) - 1;
                let ry = (buffer[base + 30] / 128) - 1;
                let rz = (buffer[base + 31] / 128) - 1;

                const len = Math.sqrt(rw * rw + rx * rx + ry * ry + rz * rz) || 1;
                rot_0[i] = rw / len;
                rot_1[i] = rx / len;
                rot_2[i] = ry / len;
                rot_3[i] = rz / len;
            }

            const vertexElement = buildVertexElement(numSplats, {
                x, y, z, scale_0, scale_1, scale_2,
                f_dc_0, f_dc_1, f_dc_2, opacity,
                rot_0, rot_1, rot_2, rot_3,
            });

            const resource = createGSplatResource(this.app.graphicsDevice, vertexElement);
            callback(null, resource);
        } catch (err) {
            callback(err instanceof Error ? err.message : String(err));
        }
    }

    open(url: any, data: any) {
        return data;
    }
}

export { SplatParser };
