/**
 * @file audio-player.ts
 * Floating audio pill — play/pause, seek bar, volume slider, mute toggle.
 *
 * Shown only when an `?audio=<url>` parameter is present or an audio file is
 * drag-dropped (editor mode only).  Loop is always on.  Starts paused to
 * respect browser autoplay policies, but the first user interaction anywhere
 * on the page triggers playback automatically.
 *
 * ENGINE UPGRADE: No PlayCanvas API calls — purely HTML5 Audio + DOM.
 */

import { ICONS } from './icons.js';
import { viewerState } from './viewer-state.js';

// ─── Constants ───────────────────────────────────────────────────────────────

/** Accepted audio extensions for drag-drop detection. */
export const AUDIO_EXTENSIONS = new Set(['.mp3', '.wav', '.ogg', '.m4a', '.aac', '.flac', '.webm']);

/** Update interval for the seek bar (ms). */
const SEEK_UPDATE_INTERVAL = 250;

// ─── Module state ────────────────────────────────────────────────────────────

let audio: HTMLAudioElement | null = null;
let pillEl: HTMLElement | null = null;
let seekInterval: ReturnType<typeof setInterval> | null = null;

// ─── DOM construction ────────────────────────────────────────────────────────

/**
 * Builds the floating audio pill element and returns it (not yet appended).
 */
function createAudioPill(): HTMLElement {
    const pill = document.createElement('div');
    pill.id = 'audioPill';
    pill.className = 'audio-pill';
    pill.innerHTML = `
        <button id="audioPlayBtn" class="audio-pill-btn" title="Play">${ICONS.play}</button>
        <span id="audioTimeLabel" class="audio-time-label">0:00</span>
        <div id="audioSeekTrack" class="audio-seek-track">
            <div id="audioSeekFill" class="audio-seek-fill"></div>
        </div>
        <span id="audioDurationLabel" class="audio-time-label">0:00</span>
        <input id="audioVolSlider" type="range" class="audio-vol-slider" min="0" max="1" step="0.01" value="1" title="Volume">
        <button id="audioVolumeBtn" class="audio-pill-btn" title="Mute">${ICONS.volume_on}</button>
    `;
    return pill;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Formats seconds as M:SS. */
function formatTime(s: number): string {
    if (!isFinite(s) || s < 0) return '0:00';
    const mins = Math.floor(s / 60);
    const secs = Math.floor(s % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
}

/** Updates the seek bar fill width and time labels. */
function updateSeekUI(): void {
    if (!audio || !pillEl) return;
    const fill = pillEl.querySelector('#audioSeekFill') as HTMLElement | null;
    const timeLabel = pillEl.querySelector('#audioTimeLabel') as HTMLElement | null;
    const durationLabel = pillEl.querySelector('#audioDurationLabel') as HTMLElement | null;

    const pct = audio.duration > 0 ? (audio.currentTime / audio.duration) * 100 : 0;
    if (fill) fill.style.width = `${pct}%`;
    if (timeLabel) timeLabel.textContent = formatTime(audio.currentTime);
    if (durationLabel) durationLabel.textContent = formatTime(audio.duration);
}

// ─── Event wiring ────────────────────────────────────────────────────────────

/**
 * Wires play/pause, seek, volume slider, and mute interactions.
 * Also registers a one-shot first-interaction listener so the first click or
 * touch anywhere on the page starts playback (respects browser autoplay policy).
 */
function wireEvents(): void {
    if (!audio || !pillEl) return;

    const playBtn   = pillEl.querySelector('#audioPlayBtn')  as HTMLElement | null;
    const volumeBtn = pillEl.querySelector('#audioVolumeBtn') as HTMLElement | null;
    const volSlider = pillEl.querySelector('#audioVolSlider') as HTMLInputElement | null;
    const seekTrack = pillEl.querySelector('#audioSeekTrack') as HTMLElement | null;

    // Play / Pause
    playBtn?.addEventListener('click', () => {
        if (!audio) return;
        if (audio.paused) {
            audio.play().catch(() => { /* autoplay blocked — user must click again */ });
        } else {
            audio.pause();
        }
    });

    // Update play/pause icon
    const syncPlayIcon = () => {
        if (playBtn) {
            playBtn.innerHTML = audio!.paused ? ICONS.play : ICONS.pause;
            playBtn.title = audio!.paused ? 'Play' : 'Pause';
        }
    };
    audio.addEventListener('play', syncPlayIcon);
    audio.addEventListener('pause', syncPlayIcon);

    // Volume slider
    volSlider?.addEventListener('input', () => {
        if (!audio || !volSlider) return;
        const vol = parseFloat(volSlider.value);
        audio.volume = vol;
        // If dragging to > 0 while muted, unmute
        if (vol > 0 && audio.muted) {
            audio.muted = false;
            syncMuteIcon();
        }
        // Sync dev panel slider
        const devSlider = document.getElementById('devAudioVolume') as HTMLInputElement | null;
        if (devSlider) devSlider.value = volSlider.value;
    });

    // Mute toggle
    const syncMuteIcon = () => {
        if (!audio || !volumeBtn) return;
        volumeBtn.innerHTML = audio.muted ? ICONS.volume_off : ICONS.volume_on;
        volumeBtn.title = audio.muted ? 'Unmute' : 'Mute';
    };
    volumeBtn?.addEventListener('click', () => {
        if (!audio) return;
        audio.muted = !audio.muted;
        syncMuteIcon();
    });

    // Seek on click/drag
    if (seekTrack) {
        const seekTo = (e: MouseEvent | PointerEvent) => {
            if (!audio || !audio.duration) return;
            const rect = seekTrack.getBoundingClientRect();
            const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
            audio.currentTime = pct * audio.duration;
            updateSeekUI();
        };

        let dragging = false;
        seekTrack.addEventListener('pointerdown', (e) => {
            dragging = true;
            seekTrack.setPointerCapture(e.pointerId);
            seekTo(e);
        });
        seekTrack.addEventListener('pointermove', (e) => {
            if (dragging) seekTo(e);
        });
        seekTrack.addEventListener('pointerup', () => { dragging = false; });
        seekTrack.addEventListener('pointercancel', () => { dragging = false; });
    }

    // Duration available
    audio.addEventListener('loadedmetadata', updateSeekUI);

    // Surface load errors so they're visible in the console
    audio.addEventListener('error', () => {
        const err = audio?.error;
        console.error('[audio-player] failed to load audio:', err?.message ?? 'unknown error', `(code ${err?.code})`);
    });

    // Periodic seek bar update
    seekInterval = setInterval(updateSeekUI, SEEK_UPDATE_INTERVAL);

    // First-interaction autoplay — the first click or touch anywhere on the
    // page starts audio.  Removed automatically after firing once.
    const tryAutoplay = () => {
        if (audio && audio.paused) {
            audio.play().catch(() => {});
        }
    };
    document.addEventListener('click',      tryAutoplay, { once: true });
    document.addEventListener('touchend',   tryAutoplay, { once: true });
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Sets the audio volume (0–1) and syncs the pill slider and dev panel slider.
 * Safe to call when no audio is loaded.
 *
 * @param vol - Volume level, clamped to [0, 1].
 */
export function setAudioVolume(vol: number): void {
    const clamped = Math.max(0, Math.min(1, vol));
    if (audio) audio.volume = clamped;
    const pillSlider = document.getElementById('audioVolSlider') as HTMLInputElement | null;
    if (pillSlider) pillSlider.value = String(clamped);
    const devSlider  = document.getElementById('devAudioVolume') as HTMLInputElement | null;
    if (devSlider)  devSlider.value  = String(clamped);
}

/**
 * Returns the current audio volume (0–1).  Returns 1 when no audio is loaded.
 */
export function getAudioVolume(): number {
    return audio?.volume ?? 1;
}

/**
 * Initialises the audio player with the given URL.
 * Creates the pill DOM element and appends it to `document.body`.
 * If a player already exists it is destroyed and replaced.
 *
 * @param url - URL of the audio file to load.
 */
export function setupAudioPlayer(url: string): void {
    // Tear down any existing player
    destroyAudioPlayer();

    audio = new Audio();
    audio.loop = true;
    audio.preload = 'metadata';
    audio.src = url;

    pillEl = createAudioPill();
    document.body.appendChild(pillEl);

    wireEvents();

    // Store for share URL
    viewerState.audioUrl = url;
}

/**
 * Loads audio from a dropped File (creates a blob URL).
 *
 * @param file - The dropped audio File.
 */
export function loadAudioFromFile(file: File): void {
    const blobUrl = URL.createObjectURL(file);
    setupAudioPlayer(blobUrl);
    // Blob URLs aren't shareable — clear the shareable audioUrl
    viewerState.audioUrl = '';
}

/**
 * Destroys the audio player, freeing resources.
 */
export function destroyAudioPlayer(): void {
    if (seekInterval !== null) {
        clearInterval(seekInterval);
        seekInterval = null;
    }
    if (audio) {
        audio.pause();
        audio.src = '';
        audio = null;
    }
    if (pillEl) {
        pillEl.remove();
        pillEl = null;
    }
}
