/**
 * @file settingsPanel.ts
 * Settings panel — HTML builder and control wiring.
 *
 * Post-effect controls mutate `global.settings.postEffectSettings` and call
 * `viewer.configureCamera()` so the CameraFrame is created/updated immediately.
 *
 * `setupSettingsControls` is split into four focused sub-functions:
 *   - `setupCameraMode`       — orbit / walk mode buttons
 *   - `setupVisualization`    — auto-rotate, bg colour, model scale, FOV, render scale
 *   - `setupPostProcessing`   — sharpen toggle + intensity; FXAA placeholder
 *   - `setupCameraLimits`     — all limit toggles and sliders + reset button
 */

import type { Global } from '../../types.js';
import {
    createToggleSwitch,
    createRangeControl,
    createColorControl,
    setupEnhancedRangeControl,
} from '../controls.js';
import { ICONS } from '../icons.js';
import { showToast } from '../toast.js';
import { viewerState } from '../viewer-state.js';
import { cameraLimits, DEFAULTS as LIMIT_DEFAULTS } from '../camera-limits.js';
import { WALK_DEFAULTS } from '../model-utils.js';

// ─── HTML builders ────────────────────────────────────────────────────────────

/** Returns the HTML string for the camera-mode toggle section. */
function createCameraModeSection(): string {
    return `
        <div class="settings-category">
            <div class="settings-title">Camera Mode</div>
            <div class="settings-category-content">
                <div class="control-group">
                    <div class="camera-mode-buttons">
                        <button id="cameraModeOrbit" class="mode-btn active" title="Orbit around model">
                            Orbit
                        </button>
                        <button id="cameraModeFly" class="mode-btn" title="Fly freely through scene (WASD + mouse)">
                            Fly
                        </button>
                        <button id="cameraModeWalkBtn" class="mode-btn hidden" title="Walk with collision (WASD + mouse, terrain-aware)">
                            Walk
                        </button>
                    </div>
                    <div class="control-hint" id="cameraModeHint">Orbit — drag to rotate, scroll to zoom</div>
                </div>
                <div id="walkHeightGroup" class="control-group" style="display:none; margin-top: 8px;">
                    ${createRangeControl('walkHeightRange', 'Walk Height', 0.2, 20.0, 1.0, 0.1, 'x', 1)}
                </div>
            </div>
        </div>
    `;
}

/** Returns the HTML string for the visualisation settings section. */
function createVisualizationSection(): string {
    return `
        <div class="settings-category">
            <div class="settings-title">Visualization</div>
            <div class="settings-category-content">
                ${createToggleSwitch('autoRotateToggle', 'Auto Rotation', true)}
                ${createRangeControl('renderScaleRange', 'Render Resolution', 0.25, 2.0, 1.0, 0.05, 'x', 2)}
                ${createRangeControl('fovRange', 'Field of View', 20, 120, 75, 1, '°')}
                ${createRangeControl('modelScaleRange', 'Model Scale', 0.001, 5, 1, 0.001, '', 3)}
                ${createColorControl('backgroundColorPicker', 'Background Color', '#191919')}
            </div>
        </div>
    `;
}

/** Returns the HTML string for the post-processing settings section. */
function createPostProcessingSection(): string {
    return `
        <div class="settings-category">
            <div class="settings-title">Post Processing</div>
            <div class="settings-category-content">
                ${createToggleSwitch('sharpenToggle', 'Sharpening', false)}
                ${createRangeControl('sharpenIntensityRange', 'Sharpening Intensity', 0, 2, 0.5, 0.1, '', 1)}
                <div class="control-group">
                    <label for="fxaaToggle" class="control-label-disabled">Anti-Aliasing (FXAA)</label>
                    <label class="switch disabled" title="Not available in this build">
                        <input type="checkbox" id="fxaaToggle" disabled>
                        <span class="slider round"></span>
                    </label>
                </div>
            </div>
        </div>
    `;
    // TODO: wire FXAA toggle once postEffectSettings.fxaa is implemented in the
    //       PlayCanvas viewer settings schema.  Currently the checkbox is
    //       intentionally disabled — do not remove the element.
}

/** Returns the HTML string for the camera limits settings section. */
function createCameraLimitsSection(): string {
    return `
        <div class="settings-category">
            <div class="settings-title">Camera Limits</div>
            <div class="settings-category-content">
                ${createToggleSwitch('cameraLimitsToggle', 'Enable Camera Limits', true)}
                ${createToggleSwitch('limitZoomToggle', 'Limit Zoom', true)}
                ${createRangeControl('minDistanceRange', 'Min Distance', 0.01, 30, 1.0, 0.1, '', 2)}
                ${createRangeControl('maxDistanceRange', 'Max Distance', 0.1, 50, 15, 0.5, '', 1)}
                ${createToggleSwitch('limitVerticalToggle', 'Limit Vertical Rotation', false)}
                ${createRangeControl('verticalUpRange', 'Up Angle Limit', -90, 90, -80, 5, '°')}
                ${createRangeControl('verticalDownRange', 'Down Angle Limit', -90, 90, 5, 5, '°')}
                ${createToggleSwitch('limitHorizontalToggle', 'Limit Horizontal Rotation', false)}
                ${createRangeControl('horizontalAngleRange', 'Horizontal Total Angle', 30, 360, 360, 15, '°')}
                ${createRangeControl('horizontalOffsetRange', 'Horizontal Offset', -180, 180, 0, 15, '°')}
                ${createToggleSwitch('limitPanToggle', 'Enable Panning', true)}
                <div class="control-group">
                    <button id="resetLimitsButton" class="action-button" style="width: 100%; margin-top: 8px;">
                        ${ICONS.reset_view}
                        <span class="button-text">Reset to Defaults</span>
                    </button>
                </div>
            </div>
        </div>
    `;
}

/** Returns the HTML string for the touch-sensitivity settings section (mobile only). */
function createTouchControlsSection(): string {
    return `
        <div class="settings-category">
            <div class="settings-title">Touch Controls</div>
            <div class="settings-category-content">
                ${createRangeControl('touchSensitivityRange', 'Touch Sensitivity', 1, 10, 5, 1)}
            </div>
        </div>
    `;
}

/**
 * Returns the complete HTML string for the settings panel content section.
 *
 * @param hasTouch - When `true` a touch-sensitivity section is appended.
 */
export function createSettingsSection(hasTouch: boolean): string {
    return `
        <div id="settingsContent" class="content-section">
            <h4>Settings</h4>
            ${createCameraModeSection()}
            ${createVisualizationSection()}
            ${createCameraLimitsSection()}
            ${createPostProcessingSection()}
            ${hasTouch ? createTouchControlsSection() : ''}
        </div>
    `;
}

// ─── Control wiring sub-functions ─────────────────────────────────────────────

/**
 * Wires the Orbit / Walk-Fly mode buttons and keeps them in sync with the
 * `cameraMode:changed` event that is fired by the engine whenever the mode
 * changes (including from keyboard shortcuts and the icon bar).
 *
 * @param global - The PlayCanvas Global context object.
 */
function setupCameraMode(global: Global): void {
    const { events, state } = global;

    const orbitBtn = document.getElementById('cameraModeOrbit');
    const flyBtn   = document.getElementById('cameraModeFly');
    const walkBtn  = document.getElementById('cameraModeWalkBtn');
    const modeHint = document.getElementById('cameraModeHint');

    const HINTS: Record<string, string> = {
        orbit: 'Orbit — drag to rotate, scroll to zoom',
        fly:   'Fly — WASD + mouse to move freely, Esc to exit',
        walk:  'Walk — WASD + mouse, terrain-aware with collision, Esc to exit',
        anim:  'Animation playing — press Stop or switch mode to exit',
    };

    const updateModeButtons = (mode: string) => {
        orbitBtn?.classList.toggle('active', mode === 'orbit');
        flyBtn?.classList.toggle('active',   mode === 'fly');
        walkBtn?.classList.toggle('active',  mode === 'walk');
        if (modeHint) modeHint.textContent = HINTS[mode] ?? mode;
    };

    // Orbit button — exit any first-person or animation mode
    orbitBtn?.addEventListener('click', () => {
        const m = state.cameraMode;
        if (m === 'walk' || m === 'fly') {
            events.fire('inputEvent', 'exitWalk');
        } else if (m === 'anim') {
            events.fire('inputEvent', 'stop');
        }
    });

    // Fly button — enter fly mode directly
    flyBtn?.addEventListener('click', () => {
        const m = state.cameraMode;
        if (m === 'orbit' || m === 'walk') {
            state.cameraMode = 'fly';
        } else if (m === 'anim') {
            events.fire('inputEvent', 'stop');
            state.cameraMode = 'fly';
        }
    });

    // Walk button — only shown when collision is present
    walkBtn?.addEventListener('click', () => {
        const m = state.cameraMode;
        if (m === 'orbit' || m === 'fly') {
            state.cameraMode = 'walk';
        } else if (m === 'anim') {
            events.fire('inputEvent', 'stop');
            state.cameraMode = 'walk';
        }
    });

    // Show Walk button when collision becomes available (drag-drop, URL load)
    events.on('hasCollision:changed', (hasCollision: boolean) => {
        walkBtn?.classList.toggle('hidden', !hasCollision);
    });

    // Walk height slider — multiplier for eyeHeight/hoverHeight/capsuleHeight.
    //
    // WHY split input vs change:
    //   setupEnhancedRangeControl fires the callback on every `input` event
    //   (every pixel the slider moves). Applying physics on every `input` abruptly
    //   shifts the spring equilibrium mid-frame — the spring (stiffness=800)
    //   overshoots, then chases a target that's already moved again on the next
    //   pixel → perpetual oscillation that never settles until the user exits walk.
    //
    //   Fix: wire display sync (real-time, every `input`) separately from physics
    //   application (committed value only, `change` = mouseup). We bypass
    //   setupEnhancedRangeControl here and wire the slider manually.
    const walkHeightGroup = document.getElementById('walkHeightGroup');
    const walkSlider      = document.getElementById('walkHeightRange')      as HTMLInputElement | null;
    const walkSliderInput = document.getElementById('walkHeightRangeInput') as HTMLInputElement | null;

    /** Applies the committed multiplier to the walk controller physics. */
    const applyWalkHeight = (value: number) => {
        // Persist so scaleWalkController() re-applies on model reload
        viewerState.walkHeightMultiplier = value;
        const cm = viewerState.cameraManager;
        if (!cm || state.cameraMode !== 'walk') return;
        const sf = viewerState.normalizedScale > 0 ? viewerState.normalizedScale : 1;
        const wc = cm.walkController;
        // setHeights also shifts the eye position by the height delta so the
        // spring stays at rest — without that the camera bounces while the
        // suspension chases the new target after a 1+ m jump.
        wc.setHeights(
            WALK_DEFAULTS.eyeHeight     * sf * value,
            WALK_DEFAULTS.capsuleHeight * sf * value,
            WALK_DEFAULTS.hoverHeight   * sf * value
        );
    };

    // Display sync only while dragging — no physics update yet
    walkSlider?.addEventListener('input', () => {
        if (walkSliderInput) walkSliderInput.value = parseFloat(walkSlider.value).toFixed(1);
    });

    // Physics applied once on mouseup (committed value, spring not disturbed mid-drag)
    walkSlider?.addEventListener('change', () => {
        applyWalkHeight(parseFloat(walkSlider.value));
    });

    // Number field: apply on blur (user typed a value and tabbed/clicked away)
    walkSliderInput?.addEventListener('blur', () => {
        let value = parseFloat(walkSliderInput.value);
        if (isNaN(value)) value = parseFloat(walkSlider?.value ?? '1');
        value = Math.max(0.2, Math.min(20.0, value));
        walkSliderInput.value = value.toFixed(1);
        if (walkSlider) walkSlider.value = String(value);
        applyWalkHeight(value);
    });

    // Allow Enter key to commit the number field value
    walkSliderInput?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') walkSliderInput.blur();
    });

    const showWalkHeight = (mode: string) => {
        if (walkHeightGroup) walkHeightGroup.style.display = mode === 'walk' ? '' : 'none';
    };

    // Auto-rotate is an orbit-only behavior. Disable the toggle in walk/fly so
    // the UI reflects that — and force-uncheck it on entering walk so the
    // rotation doesn't silently resume the next time the user is back in orbit.
    const updateAutoRotateAvailability = (mode: string) => {
        const toggle = document.getElementById('autoRotateToggle') as HTMLInputElement | null;
        if (!toggle) return;
        const isOrbit = mode === 'orbit';
        toggle.disabled = !isOrbit;
        const row = toggle.closest('.control-group') as HTMLElement | null;
        if (row) row.style.opacity = isOrbit ? '' : '0.5';
        if (mode === 'walk' && toggle.checked) {
            toggle.checked = false;
            // Sync the engine flag with the UI so the rotation actually stops
            // and stays off until the user re-enables it explicitly.
            events.fire('inputEvent', 'setAutoRotate', { enabled: false, speed: 0.7 });
        }
    };

    // Keep buttons in sync when mode changes from anywhere (icon bar, Esc key, etc.)
    events.on('cameraMode:changed', (mode: string) => {
        updateModeButtons(mode);
        showWalkHeight(mode);
        updateAutoRotateAvailability(mode);
    });

    // Set initial state (walk button visibility driven by hasCollision:changed above)
    updateModeButtons(state.cameraMode);
    showWalkHeight(state.cameraMode);
    updateAutoRotateAvailability(state.cameraMode);
    if (state.hasCollision) {
        walkBtn?.classList.remove('hidden');
    }
}

/**
 * Wires the visualisation controls: auto-rotate toggle, render resolution
 * slider, field-of-view slider, model scale slider, and background colour
 * picker.
 *
 * @param global - The PlayCanvas Global context object.
 */
function setupVisualization(global: Global): void {
    const { app, events, state, camera } = global;

    // Auto-rotation toggle — CameraManager defaults to enabled=true, so no
    // initial fire needed here. Only wire the change listener for user toggles.
    const autoRotateToggle = document.getElementById('autoRotateToggle') as HTMLInputElement | null;
    if (autoRotateToggle) {
        autoRotateToggle.addEventListener('change', (e) => {
            events.fire('inputEvent', 'setAutoRotate', {
                enabled: (e.target as HTMLInputElement).checked,
                speed: 0.7,
            });
        });
    }

    // Render scale slider
    setupEnhancedRangeControl('renderScaleRange', (value) => {
        state.renderScale = value;
        viewerState.renderScale = value;
    });

    // Field of view slider
    setupEnhancedRangeControl('fovRange', (value) => {
        events.fire('inputEvent', 'setFov', { fov: value });
        app.renderNextFrame = true; // [PC API]
    });

    // Model scale slider
    setupEnhancedRangeControl('modelScaleRange', (value) => {
        viewerState.splatEntity?.setLocalScale(value, value, value); // [PC API]
        app.renderNextFrame = true; // [PC API]
    });

    // Background colour picker
    const bgPicker  = document.getElementById('backgroundColorPicker') as HTMLInputElement | null;
    const bgDisplay = document.getElementById('backgroundColorPickerDisplay') as HTMLElement | null;
    if (bgPicker) {
        bgPicker.addEventListener('input', (e) => {
            const hex = (e.target as HTMLInputElement).value;
            if (bgDisplay) bgDisplay.textContent = hex.toUpperCase();
            const r = parseInt(hex.slice(1, 3), 16) / 255;
            const g = parseInt(hex.slice(3, 5), 16) / 255;
            const b = parseInt(hex.slice(5, 7), 16) / 255;
            camera.camera!.clearColor.set(r, g, b, 1); // [PC API]
            app.renderNextFrame = true; // [PC API]
        });
    }
}

/**
 * Wires the post-processing controls: sharpen toggle, sharpen intensity slider.
 * The FXAA toggle is intentionally left disabled in the DOM — see the TODO in
 * `createPostProcessingSection`.
 *
 * @param global - The PlayCanvas Global context object.
 */
function setupPostProcessing(global: Global): void {
    const { app, settings } = global;

    /**
     * Syncs the background colour picker's current hex value back into
     * `settings.background.color` (RGB 0-1 array) so that calling
     * `configureCamera(settings)` does not revert to the stale default colour.
     */
    const syncBgColor = () => {
        const picker = document.getElementById('backgroundColorPicker') as HTMLInputElement | null;
        if (!picker) return;
        const hex = picker.value;
        settings.background.color = [
            parseInt(hex.slice(1, 3), 16) / 255,
            parseInt(hex.slice(3, 5), 16) / 255,
            parseInt(hex.slice(5, 7), 16) / 255,
        ] as [number, number, number];
    };

    // Sharpen toggle
    const sharpenToggle = document.getElementById('sharpenToggle') as HTMLInputElement | null;
    if (sharpenToggle) {
        sharpenToggle.addEventListener('change', (e) => {
            settings.postEffectSettings.sharpness.enabled = (e.target as HTMLInputElement).checked;
            syncBgColor();
            viewerState.viewer?.configureCamera(settings); // [PC API]
            app.renderNextFrame = true; // [PC API]
        });
    }

    // Sharpening intensity slider
    setupEnhancedRangeControl('sharpenIntensityRange', (value) => {
        settings.postEffectSettings.sharpness.amount = value;
        if (settings.postEffectSettings.sharpness.enabled) {
            syncBgColor();
            viewerState.viewer?.configureCamera(settings); // [PC API]
            app.renderNextFrame = true; // [PC API]
        }
    });

    // TODO: enable when postEffectSettings gains fxaa support
    // fxaaToggle is intentionally left disabled in the DOM — do not remove the element.
}

/**
 * Wires all camera-limits controls: master toggle, per-axis toggles, range
 * sliders, and the reset-to-defaults button.
 *
 * @param global - The PlayCanvas Global context object.
 */
function setupCameraLimits(global: Global): void {
    // Master toggle
    const cameraLimitsToggle = document.getElementById('cameraLimitsToggle') as HTMLInputElement | null;
    if (cameraLimitsToggle) {
        cameraLimitsToggle.addEventListener('change', (e) => {
            cameraLimits.setEnabled((e.target as HTMLInputElement).checked);
        });
    }

    // Zoom limits
    const limitZoomToggle = document.getElementById('limitZoomToggle') as HTMLInputElement | null;
    if (limitZoomToggle) {
        limitZoomToggle.addEventListener('change', (e) => {
            const enabled = (e.target as HTMLInputElement).checked;
            const min = parseFloat((document.getElementById('minDistanceRange') as HTMLInputElement)?.value ?? '1');
            const max = parseFloat((document.getElementById('maxDistanceRange') as HTMLInputElement)?.value ?? '15');
            cameraLimits.setDistanceLimits(enabled, min, max);
        });
    }

    setupEnhancedRangeControl('minDistanceRange', (value) => {
        const max = parseFloat((document.getElementById('maxDistanceRange') as HTMLInputElement)?.value ?? '15');
        cameraLimits.setDistanceLimits(limitZoomToggle?.checked ?? false, value, max);
    });

    setupEnhancedRangeControl('maxDistanceRange', (value) => {
        const min = parseFloat((document.getElementById('minDistanceRange') as HTMLInputElement)?.value ?? '1');
        cameraLimits.setDistanceLimits(limitZoomToggle?.checked ?? false, min, value);
    });

    // Vertical limits
    const limitVerticalToggle = document.getElementById('limitVerticalToggle') as HTMLInputElement | null;
    if (limitVerticalToggle) {
        limitVerticalToggle.addEventListener('change', (e) => {
            const enabled = (e.target as HTMLInputElement).checked;
            const up   = parseFloat((document.getElementById('verticalUpRange')   as HTMLInputElement)?.value ?? '-80');
            const down = parseFloat((document.getElementById('verticalDownRange') as HTMLInputElement)?.value ?? '5');
            cameraLimits.setVerticalLimitsUpDown(enabled, up, down);
        });
    }

    setupEnhancedRangeControl('verticalUpRange', (value) => {
        const down = parseFloat((document.getElementById('verticalDownRange') as HTMLInputElement)?.value ?? '5');
        cameraLimits.setVerticalLimitsUpDown(limitVerticalToggle?.checked ?? false, value, down);
    });

    setupEnhancedRangeControl('verticalDownRange', (value) => {
        const up = parseFloat((document.getElementById('verticalUpRange') as HTMLInputElement)?.value ?? '-80');
        cameraLimits.setVerticalLimitsUpDown(limitVerticalToggle?.checked ?? false, up, value);
    });

    // Horizontal limits
    const limitHorizontalToggle = document.getElementById('limitHorizontalToggle') as HTMLInputElement | null;
    if (limitHorizontalToggle) {
        limitHorizontalToggle.addEventListener('change', (e) => {
            const enabled = (e.target as HTMLInputElement).checked;
            const angle  = parseFloat((document.getElementById('horizontalAngleRange')  as HTMLInputElement)?.value ?? '360');
            const offset = parseFloat((document.getElementById('horizontalOffsetRange') as HTMLInputElement)?.value ?? '0');
            cameraLimits.setHorizontalLimitsAngleOffset(enabled, angle, offset);
        });
    }

    setupEnhancedRangeControl('horizontalAngleRange', (value) => {
        const offset = parseFloat((document.getElementById('horizontalOffsetRange') as HTMLInputElement)?.value ?? '0');
        cameraLimits.setHorizontalLimitsAngleOffset(limitHorizontalToggle?.checked ?? false, value, offset);
    });

    setupEnhancedRangeControl('horizontalOffsetRange', (value) => {
        const angle = parseFloat((document.getElementById('horizontalAngleRange') as HTMLInputElement)?.value ?? '360');
        cameraLimits.setHorizontalLimitsAngleOffset(limitHorizontalToggle?.checked ?? false, angle, value);
    });

    // Panning toggle
    const limitPanToggle = document.getElementById('limitPanToggle') as HTMLInputElement | null;
    if (limitPanToggle) {
        limitPanToggle.addEventListener('change', (e) => {
            cameraLimits.setPanningEnabled((e.target as HTMLInputElement).checked);
        });
    }

    // Reset to defaults button
    document.getElementById('resetLimitsButton')?.addEventListener('click', () => {
        cameraLimits.resetToDefaults();

        // Sync per-axis toggle DOM (all off after reset)
        for (const id of ['limitZoomToggle', 'limitVerticalToggle', 'limitHorizontalToggle']) {
            const el = document.getElementById(id) as HTMLInputElement | null;
            if (el) el.checked = false;
        }
        // Panning is enabled by default
        const panEl = document.getElementById('limitPanToggle') as HTMLInputElement | null;
        if (panEl) panEl.checked = true;

        // Sync slider DOMs to match DEFAULTS in camera-limits.ts
        const setSlider = (id: string, value: number) => {
            const slider = document.getElementById(id) as HTMLInputElement | null;
            if (slider) {
                slider.value = String(value);
                slider.dispatchEvent(new Event('input', { bubbles: true }));
            }
        };
        setSlider('minDistanceRange',      LIMIT_DEFAULTS.zoom.min);
        setSlider('maxDistanceRange',      LIMIT_DEFAULTS.zoom.max);
        setSlider('verticalUpRange',       LIMIT_DEFAULTS.vertical.upDeg);
        setSlider('verticalDownRange',     LIMIT_DEFAULTS.vertical.downDeg);
        setSlider('horizontalAngleRange',  LIMIT_DEFAULTS.horizontal.totalAngle);
        setSlider('horizontalOffsetRange', LIMIT_DEFAULTS.horizontal.offset);

        showToast('Camera limits reset to defaults');
    });

    // Touch sensitivity (mobile only) — wiring deferred to a future step
    const touchSensRange = document.getElementById('touchSensitivityRange') as HTMLInputElement | null;
    if (touchSensRange) {
        touchSensRange.addEventListener('input', () => {
            // Step 5 will wire to OrbitController sensitivity
        });
    }
}

// ─── Entry point ──────────────────────────────────────────────────────────────

/**
 * Wires all settings panel controls.
 * Delegates to four focused sub-functions so each concern is self-contained.
 *
 * @param global - The PlayCanvas Global context object.
 */
export function setupSettingsControls(global: Global): void {
    setupCameraMode(global);
    setupVisualization(global);
    setupPostProcessing(global);
    setupCameraLimits(global);
}
