/**
 * @file scaled-collision.ts
 *
 * Wraps any Collision implementation with a uniform scale factor.
 * Used to align a collision asset (authored at its original scale) with a
 * Gaussian splat model that has been normalised to TARGET_SIZE world units.
 *
 * Strategy (Option B — coordinate transform on every query):
 *   - All incoming world-space coordinates are divided by `sf` before being
 *     forwarded to the inner collision (going into the collision's unscaled space).
 *   - Positions returned by the inner collision are multiplied by `sf` to bring
 *     them back into world space.
 *   - Distances / radii / halfHeights are divided by `sf`.
 *   - Push-out displacement vectors are multiplied by `sf`.
 *   - Directions and surface normals are dimensionless unit vectors — no scaling.
 *
 * No data is modified; the inner collision can be reused with different scale
 * factors or unwrapped (via `inner`) without re-loading.
 */

import type { Collision, PushOut, RayHit } from './collision.js';

class ScaledCollision implements Collision {
    /** The underlying unscaled collision. Exposed so callers can unwrap/re-wrap. */
    readonly inner: Collision;

    /** Uniform scale factor — world units per unscaled unit. */
    readonly sf: number;

    private readonly invSf: number;

    constructor(inner: Collision, sf: number) {
        this.inner = inner;
        this.sf    = sf;
        this.invSf = 1 / sf;
    }

    queryRay(
        ox: number, oy: number, oz: number,
        dx: number, dy: number, dz: number,
        maxDist: number
    ): RayHit | null {
        const inv = this.invSf;
        const hit = this.inner.queryRay(
            ox * inv, oy * inv, oz * inv,
            dx, dy, dz,             // direction is a unit vector — no scaling
            maxDist * inv
        );
        if (!hit) return null;
        return { x: hit.x * this.sf, y: hit.y * this.sf, z: hit.z * this.sf };
    }

    querySphere(
        cx: number, cy: number, cz: number,
        radius: number,
        out: PushOut
    ): boolean {
        const inv = this.invSf;
        const hit = this.inner.querySphere(
            cx * inv, cy * inv, cz * inv,
            radius * inv,
            out
        );
        if (hit) {
            out.x *= this.sf;
            out.y *= this.sf;
            out.z *= this.sf;
        }
        return hit;
    }

    queryCapsule(
        cx: number, cy: number, cz: number,
        halfHeight: number, radius: number,
        out: PushOut
    ): boolean {
        const inv = this.invSf;
        const hit = this.inner.queryCapsule(
            cx * inv, cy * inv, cz * inv,
            halfHeight * inv, radius * inv,
            out
        );
        if (hit) {
            out.x *= this.sf;
            out.y *= this.sf;
            out.z *= this.sf;
        }
        return hit;
    }

    querySurfaceNormal(
        x: number, y: number, z: number,
        rdx: number, rdy: number, rdz: number
    ): { nx: number; ny: number; nz: number } {
        const inv = this.invSf;
        // rdx/rdy/rdz are a unit direction — no scaling needed
        return this.inner.querySurfaceNormal(
            x * inv, y * inv, z * inv,
            rdx, rdy, rdz
        );
        // normals are dimensionless — return as-is
    }
}

export { ScaledCollision };
