/**
 * @file toast.ts
 * Toast notification component — engine-agnostic, pure DOM.
 * Displays a transient message at the bottom of the viewport and removes
 * itself automatically after the display duration elapses.
 */

/** Milliseconds before the `.show` CSS class is added (allows the element to
 *  be painted before the transition starts). */
const TOAST_SHOW_DELAY = 10;

/** Default duration in milliseconds the toast remains visible. */
const TOAST_DISPLAY_DURATION = 3000;

/** Milliseconds for the fade-out transition before the DOM node is removed. */
const TOAST_HIDE_DELAY = 300;

/** DOM id / class used for the toast element. */
const TOAST_ELEMENT_ID = 'custom-toast-message';

/**
 * Shows a toast notification with the given `message`.
 * Any previously visible toast is removed immediately before the new one is
 * inserted, so only one toast is ever in the DOM at a time.
 *
 * @param message  - Text to display inside the toast.
 * @param duration - How long (ms) the toast stays visible before fading out.
 *                   Defaults to {@link TOAST_DISPLAY_DURATION}.
 */
function showToast(message: string, duration = TOAST_DISPLAY_DURATION): void {
    document.getElementById(TOAST_ELEMENT_ID)?.remove();

    const toast = document.createElement('div');
    toast.id = TOAST_ELEMENT_ID;
    toast.className = TOAST_ELEMENT_ID;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => toast.classList.add('show'), TOAST_SHOW_DELAY);

    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => {
            if (toast.parentNode) toast.remove();
        }, TOAST_HIDE_DELAY);
    }, duration);
}

export { showToast };
