/**
 * @file viewer-mode.ts
 * Centralized viewer mode detection — computed once at module load.
 *
 * The viewer operates in two modes determined by URL parameters:
 *   - **editor**: Full UI with all panels and buttons (default, no share params)
 *   - **shared**: Minimal hamburger menu with quality toggle, reset, info
 *
 * Detection uses the decompressed URL parameters so it works with both
 * plain `?camPosX=...` and compressed `?c=<b64>` share links.
 *
 * ENGINE UPGRADE: No PlayCanvas API calls — purely URL-based detection.
 */

import { decompressUrlParameters } from './urlManager.js';

// ─── Types ───────────────────────────────────────────────────────────────────

export type ViewerMode = 'editor' | 'shared';

// ─── Detection ───────────────────────────────────────────────────────────────

/**
 * URL parameters that indicate a shared-viewer link with baked camera state.
 * If ANY of these is present (after decompression), the viewer enters shared mode.
 * Kept as a backwards-compat fallback for links generated before the `sm` marker.
 */
const SHARED_CAMERA_PARAMS = ['camPosX', 'camAngX', 'camDist'] as const;

function detectMode(): ViewerMode {
    // Primary check: explicit shared-mode marker added by the Share button.
    // Lives outside the compressed blob so it survives decompression failures.
    if (new URLSearchParams(location.search).has('sm')) return 'shared';

    // Fallback: old share links that predate the `sm` marker use camera params.
    try {
        const p = decompressUrlParameters();
        if (SHARED_CAMERA_PARAMS.some(param => p.has(param))) return 'shared';
    } catch {
        // Malformed URL or import-order issue — safe fallback to editor
    }
    return 'editor';
}

// ─── Exports ─────────────────────────────────────────────────────────────────

/** Computed once at module load; immutable for the session lifetime. */
export const viewerMode: ViewerMode = detectMode();

/** Convenience: `true` when the page was opened via a share link. */
export const isSharedMode = (): boolean => viewerMode === 'shared';

/** Convenience: `true` when the viewer is in editor/default mode. */
export const isEditorMode = (): boolean => viewerMode === 'editor';
