/**
 * @file index.ts
 * Application entry point. Creates the PlayCanvas graphics device and App, loads
 * the splat model / skybox / collision assets from URL parameters, and wires every
 * subsystem (camera manager, input, annotations, XR, custom UI, drag-drop) together.
 */

import {
    Asset,
    Color,
    createGraphicsDevice,
    Entity,
    EventHandler,
    Keyboard,
    Mouse,
    platform,
    TouchDevice,
    type Texture,
    type AppBase,
    revision as engineRevision,
    version as engineVersion
} from 'playcanvas';

import { App } from './app';
import { MeshCollision, loadVoxelCollision } from './collision';
import type { Collision } from './collision';
import { observe } from './core/observe';
import { importSettings } from './settings';
import type { Config, Global } from './types';
import { initPoster, initUI } from './ui';
import { setupCustomUI } from './custom-ui/ui.js';
import { setupDragDrop } from './custom-ui/drag-drop.js';
import { applyCameraFromUrl, applySettingsFromUrl, decompressUrlParameters } from './custom-ui/urlManager.js';
import { viewerState } from './custom-ui/viewer-state.js';
import { isEditorMode } from './custom-ui/viewer-mode.js';
import { cameraLimits } from './custom-ui/camera-limits.js';
import { normalizeAndReframe } from './custom-ui/model-utils.js';
import { initGallery, navigateTo as galleryNavigateTo } from './custom-ui/gallery.js';
import { showToast } from './custom-ui/toast.js';
import type { GalleryManifest } from './types.js';
import { setupAudioPlayer } from './custom-ui/audio-player.js';
import { SplatParser } from './splat-parser';
import { SpzParser } from './spz-parser';
import { Viewer } from './viewer';
import { WalkCursor } from './walk-cursor';
import { initXr } from './xr';
import { version as appVersion } from '../package.json';

const loadGsplat = async (app: AppBase, config: Config, progressCallback: (progress: number) => void) => {
    // contentUrl may be mutated in place by the gallery resolver in index.html,
    // and `contents` is set up to chain after that resolution. Awaiting it here
    // ensures the URL we read on the next line is the gallery-resolved one.
    if (config.galleryReady) await config.galleryReady;
    const { contents, contentUrl, unified, aa } = config;
    const c = contents as unknown as ArrayBuffer;
    const filename = new URL(contentUrl, location.href).pathname.split('/').pop();
    const data = filename.toLowerCase() === 'meta.json' ? await (await contents).json() : undefined;
    const asset = new Asset(filename, 'gsplat', { url: contentUrl, filename, contents: c }, data);

    return new Promise<Entity>((resolve, reject) => {
        asset.on('load', () => {
            const entity = new Entity('gsplat');
            entity.setLocalEulerAngles(0, 0, 180);
            entity.addComponent('gsplat', {
                unified: unified || filename.toLowerCase().endsWith('lod-meta.json'),
                asset
            });
            const material = entity.gsplat.unified ? app.scene.gsplat.material : entity.gsplat.material;
            material.setDefine('GSPLAT_AA', aa);
            material.setParameter('alphaClip', 1 / 255);
            app.root.addChild(entity);
            resolve(entity);
        });

        let watermark = 0;
        asset.on('progress', (received, length) => {
            const progress = Math.min(1, received / length) * 100;
            if (progress > watermark) {
                watermark = progress;
                progressCallback(Math.trunc(watermark));
            }
        });

        asset.on('error', (err) => {
            console.error(err);
            reject(err);
        });

        app.assets.add(asset);
        app.assets.load(asset);
    });
};

const loadSkybox = (app: AppBase, url: string) => {
    return new Promise<Asset>((resolve, reject) => {
        const asset = new Asset('skybox', 'texture', {
            url
        }, {
            type: 'rgbp',
            mipmaps: false,
            addressu: 'repeat',
            addressv: 'clamp'
        });

        asset.on('load', () => {
            resolve(asset);
        });

        asset.on('error', (err) => {
            console.error(err);
            reject(err);
        });

        app.assets.add(asset);
        app.assets.load(asset);
    });
};

const createApp = async (canvas: HTMLCanvasElement, config: Config) => {
    // Create the graphics device
    const device = await createGraphicsDevice(canvas, {
        deviceTypes: config.webgpu ? ['webgpu'] : [],
        antialias: false,
        depth: true,
        stencil: false,
        xrCompatible: !config.webgpu,
        powerPreference: 'high-performance'
    });

    // Set maxPixelRatio so the XR framebuffer scale factor is computed correctly.
    // Regular rendering bypasses maxPixelRatio via the custom initCanvas sizing.
    device.maxPixelRatio = window.devicePixelRatio;

    // Create the application
    const app = new App(canvas, {
        graphicsDevice: device,
        mouse: new Mouse(canvas),
        touch: new TouchDevice(canvas),
        keyboard: new Keyboard(window)
    });

    // Create entity hierarchy
    const cameraRoot = new Entity('camera root');
    app.root.addChild(cameraRoot);

    const camera = new Entity('camera');
    cameraRoot.addChild(camera);

    const light = new Entity('light');
    light.setEulerAngles(35, 45, 0);
    light.addComponent('light', {
        color: new Color(1.0, 0.98, 0.957),
        intensity: 1
    });
    app.root.addChild(light);

    app.scene.ambientLight.set(0.51, 0.55, 0.65);

    return { app, camera };
};

// initialize canvas size and resizing
const initCanvas = (global: Global) => {
    const { app, events, state } = global;
    const { canvas } = app.graphicsDevice;

    // maximum pixel dimension we will allow along the shortest screen dimension based on platform
    const maxPixelDim = platform.mobile ? 1080 : 2160;

    // cap pixel ratio to limit resolution on high-DPI devices
    const calcPixelRatio = () => Math.min(maxPixelDim / Math.min(screen.width, screen.height), window.devicePixelRatio);

    // last known device pixel size (full resolution, before any quality scaling)
    const deviceSize = { width: 0, height: 0 };

    const set = (width: number, height: number) => {
        const ratio = calcPixelRatio();
        deviceSize.width = width * ratio;
        deviceSize.height = height * ratio;
    };

    const apply = () => {
        // don't resize the canvas during XR - the XR system manages its own framebuffers
        // and resetting canvas dimensions can invalidate the XRWebGLLayer
        if (app.xr?.active) return;

        const s = state.renderScale * (state.retinaDisplay ? 1.0 : 0.5);
        const w = Math.ceil(deviceSize.width * s);
        const h = Math.ceil(deviceSize.height * s);
        if (w !== canvas.width || h !== canvas.height) {
            canvas.width = w;
            canvas.height = h;
        }
    };

    const resizeObserver = new ResizeObserver((entries: ResizeObserverEntry[]) => {
        const e = entries[0]?.contentBoxSize?.[0];
        if (e) {
            set(e.inlineSize, e.blockSize);
            app.renderNextFrame = true;
        }
    });
    resizeObserver.observe(canvas);

    events.on('retinaDisplay:changed', () => {
        app.renderNextFrame = true;
    });

    events.on('renderScale:changed', () => {
        app.renderNextFrame = true;
    });

    // Resize canvas before render() so the swap chain texture is acquired at the correct size.
    app.on('framerender', apply);

    // Disable the engine's built-in canvas resize — we handle it via ResizeObserver
    // @ts-ignore
    app._allowResize = false;
    set(canvas.clientWidth, canvas.clientHeight);
    apply();
};

const main = async (canvas: HTMLCanvasElement, settingsJson: any, config: Config) => {
    const { app, camera } = await createApp(canvas, config);

    // create events
    const events = new EventHandler();

    const state = observe(events, {
        loaded: false,
        readyToRender: false,
        retinaDisplay: platform.mobile ? localStorage.getItem('retinaDisplay') === 'true' : localStorage.getItem('retinaDisplay') !== 'false',
        progress: 0,
        inputMode: platform.mobile ? 'touch' : 'desktop',
        cameraMode: 'orbit',
        hasAnimation: false,
        animationDuration: 0,
        animationTime: 0,
        animationPaused: true,
        hasAR: false,
        hasVR: false,
        hasCollision: false,
        hasVoxelOverlay: false,
        voxelOverlayEnabled: false,
        isFullscreen: false,
        controlsHidden: false,
        gamingControls: localStorage.getItem('gamingControls') === 'true',
        renderScale: 1.0
    });

    const global: Global = {
        app,
        settings: importSettings(settingsJson),
        config,
        state,
        events,
        camera
    };

    initCanvas(global);

    // start the application
    app.start();

    // Initialize the load-time poster
    if (config.poster) {
        initPoster(events);
    }

    camera.addComponent('camera');

    // Initialize XR support
    if (!config.webgpu) {
        initXr(global);
    }

    // Initialize user interface
    initUI(global);

    // Initialize custom UI overlay (icon bar + panels)
    setupCustomUI(global);

    // Initialize drag and drop file loading (editor mode only — shared mode is read-only)
    if (isEditorMode()) {
        setupDragDrop(global);
    }

    // Register custom format parsers (.splat, .spz) on the gsplat handler
    const gsplatHandler = app.loader.getHandler('gsplat') as any;
    if (gsplatHandler?.parsers) {
        gsplatHandler.parsers.splat = new SplatParser(app);
        gsplatHandler.parsers.spz = new SpzParser(app);
    }

    // Load model
    const gsplatLoad = loadGsplat(
        app,
        config,
        (progress: number) => {
            state.progress = progress;
        }
    );

    // Load skybox
    const skyboxLoad = config.skyboxUrl &&
        loadSkybox(app, config.skyboxUrl).then((asset) => {
            app.scene.envAtlas = asset.resource as Texture;
        });

    // Load collision data (type determined by file extension).
    // collisionUrl may be filled in by gallery resolution after main() starts —
    // wait for that to settle before deciding whether to start a collision load.
    let collisionLoad: Promise<Collision> | undefined;
    if (config.galleryReady) {
        collisionLoad = config.galleryReady.then((): Promise<Collision | null> | null => {
            if (!config.collisionUrl) return null;
            const ext = new URL(config.collisionUrl, location.href).pathname.split('.').pop()?.toLowerCase();
            if (ext === 'glb') {
                return MeshCollision.fromGlb(app, config.collisionUrl).catch((err: Error): null => {
                    console.warn('Failed to load mesh collision:', err);
                    return null;
                });
            }
            return loadVoxelCollision(config.collisionUrl).catch((err: Error): null => {
                console.warn('Failed to load voxel data:', err);
                return null;
            });
        }) as Promise<Collision>;
    } else if (config.collisionUrl) {
        const ext = new URL(config.collisionUrl, location.href).pathname.split('.').pop()?.toLowerCase();
        if (ext === 'glb') {
            collisionLoad = MeshCollision.fromGlb(app, config.collisionUrl).catch((err: Error): null => {
                console.warn('Failed to load mesh collision:', err);
                return null;
            });
        } else {
            collisionLoad = loadVoxelCollision(config.collisionUrl).catch((err: Error): null => {
                console.warn('Failed to load voxel data:', err);
                return null;
            });
        }
    }

    // Audio player — URL param takes priority, then settings.soundUrl as legacy fallback
    const audioUrl = config.audioUrl || global.settings.soundUrl || '';
    if (audioUrl) {
        setupAudioPlayer(audioUrl);
        viewerState.audioUrl = audioUrl;
    }

    // Create the viewer
    const viewer = new Viewer(global, gsplatLoad, skyboxLoad, collisionLoad);

    // Populate shared viewer state for custom UI modules.
    viewerState.viewer = viewer;
    viewerState.app = app;
    viewerState.events = events;
    viewerState.audioUrl = config.audioUrl ?? '';
    // contentUrl/collisionUrl may be mutated by gallery resolution; wait for it
    // before snapshotting them onto viewerState (used by the Share button etc).
    if (config.galleryReady) {
        config.galleryReady.then(() => {
            viewerState.contentUrl  = config.contentUrl ?? '';
            viewerState.collisionUrl = config.collisionUrl ?? '';
        });
    } else {
        viewerState.contentUrl  = config.contentUrl ?? '';
        viewerState.collisionUrl = config.collisionUrl ?? '';
    }

    // When collision is hot-swapped via drag-drop or dev panel, update state.hasCollision
    // and auto-switch to walk mode so the user immediately has terrain-aware navigation.
    events.on('collisionLoaded', () => { // [PC API]
        state.hasCollision = true;

        // Ensure the walk cursor (hover reticle + click-to-walk indicator) is
        // initialized. The original Viewer constructor only creates it when
        // collision is present at load time — drag-drop happens later, so we
        // must create it here on demand and update its collision reference on
        // subsequent swaps. Use the scaled collision stored on the walk
        // controller so queries align with the normalized model.

        // Guard: cameraManager is set asynchronously after gsplatLoad resolves.
        // If collision loads from a fast URL before the splat is ready, cm is
        // still undefined here. Log a warning and skip the cursor — it will be
        // created by the Viewer constructor once both promises settle.
        const cm = viewerState.cameraManager;
        if (!cm) {
            console.warn('[collisionLoaded] cameraManager not ready yet — walk cursor will be created by Viewer once the model loads');
            return;
        }

        const scaled = cm.walkController.collision;
        let cursorReady = !!viewer.walkCursor;

        if (scaled) {
            const existing = viewer.walkCursor;
            if (!existing) {
                viewer.walkCursor = new WalkCursor(app, global.camera, scaled, events, state);
                cursorReady = true;
            } else {
                // Update existing cursor's collision reference via the public setter.
                existing.setCollision(scaled);
                cursorReady = true;
            }
        }

        // Only auto-switch when in orbit AND the cursor was successfully
        // initialized — don't leave the user in walk mode without a reticle.
        if (cursorReady && state.cameraMode === 'orbit') {
            events.fire('inputEvent', 'toggleWalk'); // [PC API]
        }
    });

    // When a new model loads it clears the collision — reset hasCollision so the
    // Walk button is hidden until collision is re-loaded for the new model.
    events.on('collisionCleared', () => { // [PC API]
        state.hasCollision = false;
        // If currently in walk mode, exit to orbit so the user isn't stuck
        if (state.cameraMode === 'walk') {
            events.fire('inputEvent', 'exitWalk'); // [PC API]
        }
    });

    // Once the splat is loaded, store the entity reference and apply URL state.
    // Two-tick chain: first .then() runs in the same microtask batch as Viewer's
    // internal Promise.all (which assigns viewer.cameraManager). The second .then()
    // is queued after Viewer's callback has run, so cameraManager is guaranteed set.
    gsplatLoad.then((entity) => {
        viewerState.splatEntity = entity;
        return entity;
    }).then(async (entity) => {
        viewerState.cameraManager = viewer.cameraManager;

        // Enable camera limits now that the orbit controller is ready.
        // applySettingsFromUrl (below) will override these if the URL has limit values.
        cameraLimits.setEnabled(true);
        cameraLimits.setDistanceLimits(true, 1.0, 15.0);

        // Parse URL params once and share across both restore functions.
        const urlParams = decompressUrlParameters();
        applyCameraFromUrl(global, urlParams);
        applySettingsFromUrl(global, urlParams);

        // Normalise scale and reframe camera after one frame so both customAabb
        // and the CameraManager orbit controller are guaranteed to be ready.
        // Skipped automatically for shared viewer URLs (isSharedMode() check
        // is inside normalizeAndReframe) so share links reproduce their saved view.
        app.once('frameend', () => normalizeAndReframe(entity, global.events)); // [PC API]

        // Override the 'reset' input event so Reset View always returns to the
        // normalised home camera instead of the pre-normalisation frame position.
        // Registered AFTER Viewer construction so this handler fires AFTER
        // camera-manager.ts processes 'reset' (which calls orbit.goto(resetCamera)).
        // Our subsequent gotoCamera call runs last and therefore wins.
        global.events.on('inputEvent', (eventName: string) => { // [PC API]
            if (eventName !== 'reset') return;
            const hc = viewerState.homeCamera;
            if (hc) {
                // Slow the cross-fade so the user can follow the camera back to home.
                global.events.fire('inputEvent', 'gotoCamera', { ...hc, transitionSpeed: 0.5 }); // [PC API]
            }
        });

        // Gallery init — fetch manifest and build nav bar (if ?gallery= is in URL)
        if (config.galleryUrl) {
            try {
                const response = await fetch(config.galleryUrl, { signal: AbortSignal.timeout(8000) });
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status} ${response.statusText}`);
                }
                const text = await response.text();
                let manifest: GalleryManifest;
                try {
                    manifest = JSON.parse(text);
                } catch (parseErr) {
                    // Common authoring slip: the optional `version` field is left
                    // unquoted (e.g. `"version": testing,`). Try once more with a
                    // narrow regex repair so a stale deploy doesn't break the
                    // gallery — the user still gets a toast pointing at the issue.
                    const repaired = text.replace(
                        /("version"\s*:\s*)([A-Za-z_][A-Za-z0-9_-]*)(\s*[,}])/,
                        '$1"$2"$3'
                    );
                    if (repaired !== text) {
                        try {
                            manifest = JSON.parse(repaired);
                            showToast('Gallery JSON has an unquoted "version" — please fix it', 5000);
                        } catch {
                            showToast(`Gallery JSON is invalid: ${(parseErr as Error).message}`, 6000);
                            throw parseErr;
                        }
                    } else {
                        showToast(`Gallery JSON is invalid: ${(parseErr as Error).message}`, 6000);
                        throw parseErr;
                    }
                }
                if (manifest?.models?.length > 0) {
                    viewerState.galleryUrl = config.galleryUrl;
                    initGallery(global, manifest, config.galleryUrl);

                    // Apply the first entry's baked camera/settings on top of normalizeAndReframe.
                    // We wait for the frameend that normalizeAndReframe schedules, then override.
                    const firstParams = decompressUrlParameters(manifest.models[0].shareUrl);
                    const hasCamera = firstParams.has('camPosX') && firstParams.has('camAngY') && firstParams.has('camDist');
                    if (hasCamera) {
                        app.once('frameend', () => applyCameraFromUrl(global, firstParams)); // [PC API]
                    }
                    applySettingsFromUrl(global, firstParams);

                    // Set up audio for the first gallery model (only if not already loaded
                    // via the ?audio= URL param — gallery audio takes lower priority).
                    if (!viewerState.audioUrl) {
                        const firstAudioUrl = firstParams.get('audio') ?? '';
                        if (firstAudioUrl) {
                            setupAudioPlayer(firstAudioUrl);
                            viewerState.audioUrl = firstAudioUrl;
                        }
                    }

                    // If the URL includes a gallery index (?gi=N), navigate to that model
                    const giParam = urlParams.get('galleryIndex');
                    const gi = giParam !== null ? parseInt(giParam, 10) : 0;
                    if (gi > 0 && gi < manifest.models.length) {
                        // navigateTo handles its own frameend / camera restoration
                        galleryNavigateTo(gi).catch((err) => console.warn('[gallery] navigateTo failed:', err));
                    }
                }
            } catch (err) {
                console.warn('[gallery] failed to init gallery:', err);
                const msg = err instanceof Error ? err.message : String(err);
                // Avoid double-toast when JSON parse already toasted with the parse error
                if (!msg.startsWith('Unexpected') && !msg.includes('JSON')) {
                    showToast(`Gallery failed to load: ${msg}`, 6000);
                }
            }
        }
    }).catch(() => { /* model load failure handled by viewer */ });

    return viewer;
};

console.log(`SuperSplat Viewer v${appVersion} | Engine v${engineVersion} (${engineRevision})`);

export { main };
