/**
 * @file model-utils.ts
 * Shared helpers for post-load model processing.
 *
 * Strategy
 * ─────────
 * Every freshly-loaded splat is scaled uniformly so its largest bounding-box
 * axis = TARGET_SIZE (2 m).  The camera is then positioned to orbit the
 * bounding-box centre in world space at a fixed initial distance (INITIAL_DISTANCE).
 *
 * The model is NOT translated — it stays wherever the engine places it (entity
 * origin at world origin, splat data offset encoded in the asset).  The orbit
 * pivot is computed as the bounding-box centre in world space after scaling,
 * which is the visual centre of the model regardless of data offset.
 *
 * Call `normalizeAndReframe` from an `app.once('frameend', …)` callback so
 * `entity.gsplat.customAabb` and the CameraManager are both ready.
 */

import { Asset, Entity, Vec3 } from 'playcanvas'; // [PC API]
import type { EventHandler } from 'playcanvas';
// import { enableDebugOverlay } from './debug-overlay.js'; // uncomment with line ~219 for diagnostics
import { ScaledCollision } from '../collision/index.js';
import { viewerState } from './viewer-state.js';
import { isSharedMode } from './viewer-mode.js';

// Euler rotation applied to every loaded gsplat entity (Y-up, Z-flipped data)
const GSPLAT_FLIP_ROTATION = [0, 0, 180] as const;

// ─── Debug flag ──────────────────────────────────────────────────────────────
// Set to true or add ?debug to the URL for verbose normalisation logging.
const DEBUG = new URLSearchParams(location.search).has('debug');

// ─── Walk controller defaults ─────────────────────────────────────────────────
// These are the physical dimensions for a ~human-scale character designed to
// work with voxel collision data at its ORIGINAL (unscaled) coordinate system.
// When the model is normalised to TARGET_SIZE, all values are multiplied by `sf`
// so the capsule stays ~2 voxels wide in original space regardless of scene size.
//
// Why this matters: ScaledCollision multiplies query positions and radii by
// invSf = 1/sf before forwarding to the inner VoxelCollision.  For a 50m scene
// normalised to 2m (sf=0.04, invSf=25), an unscaled 0.2m capsule radius becomes
// 5m (50 voxels) in voxel space.  The bounding-box loop in
// resolveDeepestPenetrationCapsule is O(radius_voxels² × height_voxels), so
// 50²×280 ≈ 700 000 isVoxelSolid calls per query.  Spawning calls that 100 times
// → 70 000 000 calls → ~2 seconds of main-thread freeze.
// Scaling params by sf keeps the capsule at ~2 voxels → O(4×4×14) = 224 calls.
export const WALK_DEFAULTS = {
    capsuleRadius:    0.2,
    capsuleHeight:    1.5,
    eyeHeight:        1.3,
    hoverHeight:      0.2,
    groundProbeRange: 1.0,
    moveGroundSpeed:  7,
    moveAirSpeed:     1,
    jumpSpeed:        4,
    gravity:          9.8,
} as const;

/**
 * Scales the walk controller's physical dimensions by `sf` so the capsule
 * occupies a constant number of voxels in the collision's original coordinate
 * system.  Must be called every time `viewerState.normalizedScale` changes.
 *
 * Call with `sf = 1` to restore defaults (e.g. after model reload).
 */
export function scaleWalkController(sf: number): void {
    const cm = viewerState.cameraManager;
    if (!cm) return;
    const wc = cm.walkController;
    wc.capsuleRadius    = WALK_DEFAULTS.capsuleRadius    * sf;
    wc.capsuleHeight    = WALK_DEFAULTS.capsuleHeight    * sf;
    wc.eyeHeight        = WALK_DEFAULTS.eyeHeight        * sf;
    wc.hoverHeight      = WALK_DEFAULTS.hoverHeight      * sf;
    wc.groundProbeRange = WALK_DEFAULTS.groundProbeRange * sf;
    wc.moveGroundSpeed  = WALK_DEFAULTS.moveGroundSpeed  * sf;
    wc.moveAirSpeed     = WALK_DEFAULTS.moveAirSpeed     * sf;
    wc.jumpSpeed        = WALK_DEFAULTS.jumpSpeed        * sf;
    wc.gravity          = WALK_DEFAULTS.gravity          * sf;

    // Re-apply the user's height multiplier on top of the base scale so that
    // the slider value is preserved across model reloads.  Only the three
    // "visual" height params are affected — radius and speed stay at the
    // sf-scaled default so collision geometry and movement speed remain correct.
    const hm = viewerState.walkHeightMultiplier;
    if (hm !== 1) {
        wc.eyeHeight     = WALK_DEFAULTS.eyeHeight     * sf * hm;
        wc.capsuleHeight = WALK_DEFAULTS.capsuleHeight  * sf * hm;
        wc.hoverHeight   = WALK_DEFAULTS.hoverHeight    * sf * hm;
    }
}

// ─── Constants ────────────────────────────────────────────────────────────────

/** Target world-space size (largest axis) after normalisation. */
const TARGET_SIZE = 2.0;

/**
 * Fixed initial orbit distance in world units.
 * Chosen to comfortably frame a TARGET_SIZE model at the default FOV
 * with a small margin for context.
 */
const INITIAL_DISTANCE = 3.5;

/** Default FOV used for the reframe event — matches the viewer default. */
const REFRAME_FOV = 75;

/**
 * Camera view direction — unit vector from pivot TO camera eye.
 * Matches `createFrameCamera`'s Vec3(2,1,2).normalize() so the initial
 * normalised view is consistent with the engine's "frame" action.
 *  x = 2/3 ≈ 0.6667  (camera is to the +X side)
 *  y = 1/3 ≈ 0.3333  (camera is above the pivot)
 *  z = 2/3 ≈ 0.6667  (camera is to the +Z side)
 */
const VIEW_X = 2 / 3;
const VIEW_Y = 1 / 3;
const VIEW_Z = 2 / 3;

/**
 * Pitch/yaw that correspond to the VIEW direction above.
 * These are the angles of the *look direction* (from eye TOWARD pivot),
 * i.e., the negative of the VIEW vector: (-2/3, -1/3, -2/3).
 *   pitch = asin(-1/3) ≈ -19.47°  (negative = looking down)
 *   yaw   = atan2(+2/3, +2/3) = 45°
 */
const REFRAME_PITCH_DEG = Math.asin(-1 / 3) * (180 / Math.PI); // ≈ -19.47°
const REFRAME_YAW_DEG   = 45;

// ─── Scale normalisation ──────────────────────────────────────────────────────

/**
 * Scales `entity` uniformly so its largest local bounding-box axis =
 * TARGET_SIZE world units.
 *
 * The entity is NOT translated — the orbit pivot is handled separately by
 * `normalizeAndReframe` using the bounding-box centre in world space.
 *
 * Returns the applied scale factor on success, or `false` if skipped (shared
 * URL, missing AABB data, or zero-size model).
 *
 * @param entity - The gsplat entity to scale. // [PC API]
 */
export function normalizeGsplatScale(entity: Entity): number | false {
    if (isSharedMode()) {
        if (DEBUG) console.log('[normalizeGsplatScale] skipped — shared viewer URL');
        return false;
    }

    // @ts-ignore — customAabb typedef gap: remove when PlayCanvas typedefs include it on GSplatComponent
    const aabb = entity.gsplat?.customAabb; // [PC API]

    if (!aabb) {
        if (DEBUG) console.warn('[normalizeGsplatScale] no customAabb — scale NOT normalised');
        return false;
    }

    const { x: hx, y: hy, z: hz } = aabb.halfExtents;
    const maxDim = Math.max(hx, hy, hz) * 2;

    if (!maxDim || !isFinite(maxDim) || maxDim <= 0) return false;

    const sf = TARGET_SIZE / maxDim;
    entity.setLocalScale(sf, sf, sf); // [PC API]
    if (DEBUG) console.log(`[normalizeGsplatScale] sf=${sf.toFixed(4)}, maxDim=${maxDim.toFixed(3)}`);
    return sf;
}

// ─── Reframe ──────────────────────────────────────────────────────────────────

/**
 * Normalises the gsplat entity scale and then fires a `gotoCamera` event that
 * orbits the bounding-box centre in world space at INITIAL_DISTANCE.
 *
 * Pivot computation:
 *   The entity sits at world origin with rotation (0, 0, 180°) and scale = sf.
 *   The bounding-box centre in local space is `aabb.center`.
 *   In world space: pivot = entity.getWorldTransform() × localCenter.
 *   The Z-180° rotation negates X and Y, so pivot = (−cx·sf, −cy·sf, +cz·sf).
 *
 * Also updates the `modelScaleRange` DOM slider to `sf` and stores the
 * resulting camera state in `viewerState.homeCamera` so the Reset button
 * can return here.
 *
 * Must be called from an `app.once('frameend', …)` callback so:
 *   - `entity.gsplat.customAabb` is populated by the engine
 *   - `CameraManager` is initialised and listening for `gotoCamera`
 *
 * No-op when {@link isSharedMode} returns `true`.
 *
 * @param entity - The freshly-loaded gsplat entity. // [PC API]
 * @param events - PlayCanvas EventHandler used to fire input events. // [PC API]
 */
export function normalizeAndReframe(entity: Entity, events: EventHandler): void {
    const sf = normalizeGsplatScale(entity);
    if (sf === false) return;

    // ── Compute pivot = bounding-box centre in world space ────────────────────
    // The entity has setLocalEulerAngles(0, 0, 180) which flips local X→−X and
    // Y→−Y in world space.  Using getWorldTransform() handles any rotation,
    // scale, and translation the entity may have — not just the Z-180 flip.
    //
    // customAabb is guaranteed non-null here: normalizeGsplatScale already
    // validated it (returns false if missing, which exits this function above).
    // @ts-ignore — customAabb typedef gap (see normalizeGsplatScale above)
    const aabb = entity.gsplat!.customAabb; // [PC API] — asserted non-null
    const pivot = new Vec3(); // [PC API]
    entity.getWorldTransform().transformPoint(aabb.center, pivot); // [PC API]
    const pivotX = pivot.x;
    const pivotY = pivot.y;
    const pivotZ = pivot.z;

    // ── Compute camera EYE position ───────────────────────────────────────────
    // Camera.position in the engine is the EYE (not the orbit target).
    //   focusPoint = eye + rotation(angles) * FORWARD * distance
    // We want focusPoint = pivot, so:
    //   eye = pivot + VIEW * distance   (VIEW is the unit vector from pivot to eye)
    const eyeX = pivotX + VIEW_X * INITIAL_DISTANCE;
    const eyeY = pivotY + VIEW_Y * INITIAL_DISTANCE;
    const eyeZ = pivotZ + VIEW_Z * INITIAL_DISTANCE;

    if (DEBUG) console.log(`[normalizeAndReframe] pivot=(${pivotX.toFixed(3)}, ${pivotY.toFixed(3)}, ${pivotZ.toFixed(3)}) eye=(${eyeX.toFixed(3)}, ${eyeY.toFixed(3)}, ${eyeZ.toFixed(3)})`);

    // ── Build home camera ─────────────────────────────────────────────────────
    const homeCamera = {
        position: [eyeX, eyeY, eyeZ] as [number, number, number],
        angles:   [REFRAME_PITCH_DEG, REFRAME_YAW_DEG, 0] as [number, number, number],
        distance: INITIAL_DISTANCE,
        fov:      REFRAME_FOV,
    };

    // Store so the Reset button interceptor in index.ts can return here.
    viewerState.homeCamera = homeCamera;

    // ── Wrap collision with ScaledCollision so walk mode queries align ────────
    // The collision asset was built at its original (unscaled) size.  Wrapping
    // it with sf translates all walk controller queries into the collision's
    // coordinate space and maps results back to world space.
    // Unwrap first if already wrapped (e.g. model reloaded via drag-drop) to
    // avoid stacking scale factors.
    viewerState.normalizedScale = sf;
    // Scale walk controller physical dimensions so the capsule stays ~2 voxels
    // wide in original space regardless of sf (prevents bounding-box blowup).
    scaleWalkController(sf);
    const cm = viewerState.cameraManager;
    if (cm?.walkController.collision) {
        // Unwrap any previous ScaledCollision before re-wrapping with the new sf,
        // so scale factors don't stack on repeated model loads.
        const inner = cm.walkController.collision instanceof ScaledCollision
            ? cm.walkController.collision.inner
            : cm.walkController.collision;
        const scaled = new ScaledCollision(inner, sf);
        cm.walkController.collision = scaled;
        // Keep fly controller in sync — it also does sphere collision
        if (cm.flyController) cm.flyController.collision = scaled;
    }

    // ── Notify viewer that scene bounds must be recomputed ──────────────────
    // sceneBound in viewer.ts was computed before normalization changed the
    // entity's scale.  Fire a custom event so the clip planes update.
    events.fire('sceneBoundsUpdated', entity); // [PC API]

    // ── Fire gotoCamera ───────────────────────────────────────────────────────
    events.fire('inputEvent', 'gotoCamera', homeCamera); // [PC API]

    // ── Sync model-scale slider ───────────────────────────────────────────────
    // Only update the visual slider value — do NOT dispatch 'input'.
    // Dispatching 'input' would re-invoke setLocalScale via the slider handler,
    // and the slider step (0.001) can round sf to a neighbour, corrupting the scale.
    const clampedSf = Math.max(0.001, Math.min(5, sf));
    const sliderEl = document.getElementById('modelScaleRange') as HTMLInputElement | null;
    if (sliderEl) {
        sliderEl.value = String(clampedSf);
    }
    // Keep the paired number input in sync (if it exists)
    const numberEl = document.getElementById('modelScaleRangeInput') as HTMLInputElement | null;
    if (numberEl) {
        numberEl.value = String(clampedSf);
    }
    if (clampedSf !== sf && DEBUG) {
        console.warn(`[normalizeAndReframe] sf=${sf.toFixed(6)} clamped to slider range ${clampedSf}`);
    }

    // ── Debug overlay (disabled by default — enable for diagnostics) ─────────
    // Draws bbox wireframe, pivot/origin markers, and starts live camera logging.
    // Uncomment the line below to re-enable:
    // enableDebugOverlay(entity, new Vec3(pivotX, pivotY, pivotZ)); // [PC API]
}

// ─── Shared model loader ──────────────────────────────────────────────────────

/**
 * Loads a gsplat model from a URL, destroying the previous entity and freeing
 * VRAM.  Shared between drag-drop and gallery navigation.
 *
 * Does NOT run normalizeAndReframe — the caller decides whether to auto-frame
 * (drag-drop) or restore a baked camera from a share URL (gallery).
 *
 * Does NOT revoke blob URLs — the caller manages blob lifecycle.
 *
 * @param app      - PlayCanvas AppBase instance. // [PC API]
 * @param url      - URL (or blob URL) of the splat asset to load.
 * @param filename - Filename hint used for format detection (e.g. "model.sog").
 * @returns Promise resolving to the new gsplat Entity.
 */
export async function loadModelFromUrl(
    app: ReturnType<typeof Object.create> /* AppBase */,
    url: string,
    filename: string
): Promise<Entity> {
    // Clear collision data — belongs to the previous scene.
    // Fire 'collisionCleared' so index.ts can reset state.hasCollision and
    // hide the Walk button before the new model is framed.
    const cm = viewerState.cameraManager;
    if (cm) {
        cm.walkController.collision = null;
        if (cm.flyController) cm.flyController.collision = null;
        scaleWalkController(1); // reset capsule params to defaults
    }
    viewerState.events?.fire('collisionCleared');
    viewerState.normalizedScale = 1;
    viewerState.collisionUrl = '';
    viewerState.galleryUrl   = '';  // prevent stale gallery= appearing in share URL
    viewerState.galleryIndex = -1; // mark gallery inactive

    // Destroy old entity + free VRAM
    const old = viewerState.splatEntity;
    if (old) { old.destroy(); viewerState.splatEntity = null; } // [PC API]
    app.assets.filter((a: Asset) => a.type === 'gsplat').forEach((a: Asset) => app.assets.remove(a)); // [PC API]

    const asset = new Asset(filename, 'gsplat', { url, filename }); // [PC API]

    return new Promise<Entity>((resolve, reject) => {
        asset.on('load', () => { // [PC API]
            const entity = new Entity('gsplat'); // [PC API]
            entity.setLocalEulerAngles(...GSPLAT_FLIP_ROTATION); // [PC API]
            entity.addComponent('gsplat', { asset }); // [PC API]
            app.root.addChild(entity); // [PC API]

            viewerState.splatEntity = entity;
            app.renderNextFrame = true; // [PC API]
            resolve(entity);
        });

        asset.on('error', (err: string) => { // [PC API]
            reject(new Error(err));
        });

        app.assets.add(asset); // [PC API]
        app.assets.load(asset); // [PC API]
    });
}
