/**
 * @file ui.ts
 * Custom UI controller — dual-mode icon bar, panel toggle system, and touch swipe-to-close.
 *
 * Architecture:
 *   - **Editor mode** (default): A fixed icon bar on the right edge with buttons
 *     for Settings, Info, Dev, Reset, Walk, Fullscreen, and Share. Clicking a
 *     panel button toggles a slide-out content panel.
 *   - **Shared mode** (share link detected): A minimal hamburger button in the
 *     bottom-right corner that opens a dropdown with Quality, Reset View, and
 *     Controls. Only the Info panel is available for slide-out.
 *   - On touch devices a downward swipe of at least {@link SWIPE_CLOSE_THRESHOLD_PX}
 *     pixels closes the open panel.
 *   - Engine interactions are limited to `events.fire('inputEvent', ...)` and
 *     `events.on('cameraMode:changed', ...)` — all routed through the PlayCanvas
 *     event bus on `global.events`.
 */

import type { Global } from '../types.js';
import { ICONS } from './icons.js';
import { createElement } from './controls.js';
import { showToast } from './toast.js';
import { shareCompleteViewerState } from './urlManager.js';
import { viewerState } from './viewer-state.js';
import { createInfoSection } from './panels/infoPanel.js';
import { createSettingsSection, setupSettingsControls } from './panels/settingsPanel.js';
import { createDevSection, setupDevPanel } from './panels/devPanel.js';
import { viewerMode } from './viewer-mode.js';
import type { ViewerMode } from './viewer-mode.js';

// ─── Module state ────────────────────────────────────────────────────────────

/**
 * AbortController for document-level event listeners. Aborted and replaced on
 * each `setupCustomUI` call so hot-reload doesn't leak listeners.
 */
let documentListenerAc: AbortController | null = null;

// ─── Constants ────────────────────────────────────────────────────────────────

/**
 * Minimum vertical swipe distance (in CSS pixels) required to close the open
 * panel via a downward touch gesture.
 */
const SWIPE_CLOSE_THRESHOLD_PX = 50;

/**
 * Render scale presets for the Quality toggle in shared mode.
 * Cycles through: Low → Medium → High → Ultra → Low → ...
 */
const QUALITY_PRESETS: { label: string; scale: number }[] = [
    { label: 'Low',    scale: 0.5  },
    { label: 'Medium', scale: 0.75 },
    { label: 'High',   scale: 1.0  },
    { label: 'Ultra',  scale: 1.5  },
];

// ─── DOM construction ────────────────────────────────────────────────────────

/**
 * Creates the outer wrapper element for the entire custom control panel
 * (icon bar + collapsible content area).
 */
function createControlPanel(): HTMLElement {
    return createElement('div', { id: 'customControlPanel', className: 'custom-control-panel' });
}

/**
 * Creates the full vertical icon bar for **editor mode** with all action and
 * panel-toggle buttons.
 */
function createEditorIconBar(): HTMLElement {
    return createElement('div', {
        id: 'customIconBar',
        className: 'custom-icon-bar',
        innerHTML: `
            <button id="customSettingsBtn" class="custom-icon-btn" title="Settings">${ICONS.settings}</button>
            <button id="customInfoBtn"     class="custom-icon-btn" title="Controls">${ICONS.info}</button>
            <button id="customDevBtn"      class="custom-icon-btn" title="Developer">${ICONS.dev}</button>
            <div class="custom-icon-spacer"></div>
            <button id="customResetBtn"    class="custom-icon-btn" title="Reset View">${ICONS.reset_view}</button>
            <button id="customWalkBtn"     class="custom-icon-btn" title="Walk Mode">${ICONS.walk}</button>
            <button id="customFsBtn"       class="custom-icon-btn" title="Fullscreen">${ICONS.fullscreen}</button>
            <button id="customShareBtn"    class="custom-icon-btn" title="Share">${ICONS.share}</button>
        `
    });
}

/**
 * Creates the minimal hamburger menu for **shared mode** — a floating button
 * and a dropdown with Quality, Reset View, and Controls items.
 */
function createSharedMenu(): HTMLElement {
    const wrapper = createElement('div', {
        id: 'sharedMenuWrapper',
        className: 'shared-menu-wrapper',
        innerHTML: `
            <div id="sharedMenuDropdown" class="shared-menu-dropdown" style="display:none">
                <button id="sharedQualityBtn" class="shared-menu-item">${ICONS.settings}<span>Quality: High</span></button>
                <button id="sharedResetBtn"   class="shared-menu-item">${ICONS.reset_view}<span>Reset View</span></button>
                <button id="sharedInfoBtn"    class="shared-menu-item">${ICONS.info}<span>Controls</span></button>
            </div>
            <button id="sharedMenuBtn" class="shared-menu-toggle" title="Menu">
                <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
                    <line x1="3" y1="5" x2="17" y2="5"/>
                    <line x1="3" y1="10" x2="17" y2="10"/>
                    <line x1="3" y1="15" x2="17" y2="15"/>
                </svg>
            </button>
        `
    });
    return wrapper;
}

/**
 * Creates the slide-out content area that hosts panel sections.
 *
 * In editor mode: Settings, Info, and Dev panels.
 * In shared mode: Info panel only.
 *
 * @param hasTouch - When `true` the Settings/Info section includes touch controls.
 * @param mode     - Current viewer mode.
 */
function createContentArea(hasTouch: boolean, mode: ViewerMode): HTMLElement {
    const area = createElement('div', { id: 'customPanelContent', className: 'custom-panel-content' });
    area.style.display = 'none';

    if (mode === 'editor') {
        area.innerHTML = `
            <button id="customClosePanelBtn" class="custom-close-btn" title="Close">×</button>
            ${createSettingsSection(hasTouch)}
            ${createInfoSection(hasTouch)}
            ${createDevSection()}
        `;
    } else {
        // Shared mode — info panel only
        area.innerHTML = `
            <button id="customClosePanelBtn" class="custom-close-btn" title="Close">×</button>
            ${createInfoSection(hasTouch)}
        `;
    }
    return area;
}

// ─── Panel switching ─────────────────────────────────────────────────────────

/**
 * Builds and returns a `toggle(sectionId)` function that controls which panel
 * section is currently visible.
 *
 * Calling `toggle` with a section ID opens that section (closing any other
 * open section first).  Calling it with the already-open section ID, or with
 * `null`, closes the panel entirely.
 */
function buildPanelController(global: Global): (sectionId: string | null) => void {
    let openSectionId: string | null = null;

    const panel    = document.getElementById('customControlPanel');
    const content  = document.getElementById('customPanelContent');
    const closeBtn = document.getElementById('customClosePanelBtn');

    if (!panel || !content || !closeBtn) {
        console.error('[ui] buildPanelController: required DOM elements missing');
        return () => {};
    }

    /** Maps content section IDs to their corresponding icon bar button IDs. */
    const iconBtnMap: Record<string, string> = viewerMode === 'editor'
        ? {
            settingsContent: 'customSettingsBtn',
            infoContent:     'customInfoBtn',
            devContent:      'customDevBtn',
          }
        : {
            infoContent: 'sharedInfoBtn',
          };

    function toggle(sectionId: string | null): void {
        const allSections = content.querySelectorAll<HTMLElement>('.content-section');
        allSections.forEach(s => { s.style.display = 'none'; });

        // Deactivate all icon buttons
        Object.values(iconBtnMap).forEach(btnId => {
            document.getElementById(btnId)?.classList.remove('active');
        });

        if (sectionId && sectionId !== openSectionId) {
            const section = document.getElementById(sectionId);
            if (section) {
                section.style.display = 'block';
                content.style.display = 'block';
                closeBtn.style.display = 'block';
                panel.classList.add('expanded');
                document.getElementById(iconBtnMap[sectionId])?.classList.add('active');
                openSectionId = sectionId;
            }
        } else {
            content.style.display = 'none';
            closeBtn.style.display = 'none';
            panel.classList.remove('expanded');
            openSectionId = null;
        }

        if (sectionId === 'devContent') {
            global.events.fire('controlsHidden:changed', openSectionId !== null); // [PC API]
        }
    }

    return toggle;
}

// ─── Editor mode event wiring ────────────────────────────────────────────────

/**
 * Attaches click handlers to all editor-mode icon bar buttons and wires the
 * PlayCanvas event bus for camera-mode feedback and reset/walk events.
 */
function setupEditorIconHandlers(global: Global, toggle: (id: string | null) => void): void {
    const { events } = global;

    // Panel toggles
    document.getElementById('customSettingsBtn')?.addEventListener('click', () => toggle('settingsContent'));
    document.getElementById('customInfoBtn')?.addEventListener('click',     () => toggle('infoContent'));
    document.getElementById('customDevBtn')?.addEventListener('click',      () => toggle('devContent'));
    document.getElementById('customClosePanelBtn')?.addEventListener('click', () => toggle(null));

    // Reset view
    document.getElementById('customResetBtn')?.addEventListener('click', () => {
        events.fire('inputEvent', 'reset'); // [PC API]
    });

    // Walk mode toggle
    document.getElementById('customWalkBtn')?.addEventListener('click', () => {
        events.fire('inputEvent', 'toggleWalk'); // [PC API]
    });

    // Reflect walk/fly state on the button + show toast
    events.on('cameraMode:changed', (mode: string) => { // [PC API]
        const firstPerson = mode === 'walk' || mode === 'fly';
        document.getElementById('customWalkBtn')?.classList.toggle('active', firstPerson);
        if (mode === 'walk')       showToast('Walk mode — WASD to move, mouse to look, Esc to exit');
        else if (mode === 'fly')   showToast('Fly mode — WASD to move, mouse to look, Esc to exit');
        else if (mode === 'orbit') showToast('Orbit mode');
    });

    // Fullscreen
    const fsBtn = document.getElementById('customFsBtn');
    fsBtn?.addEventListener('click', () => {
        if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(() => {
                showToast('Fullscreen not available');
            });
        } else {
            document.exitFullscreen();
        }
    });
    document.addEventListener('fullscreenchange', () => {
        if (!fsBtn) return;
        const full = !!document.fullscreenElement;
        fsBtn.innerHTML = full ? ICONS.fullscreen_exit : ICONS.fullscreen;
        fsBtn.title     = full ? 'Exit Fullscreen' : 'Fullscreen';
    }, { signal: documentListenerAc?.signal });

    // Share
    document.getElementById('customShareBtn')?.addEventListener('click', () => {
        shareCompleteViewerState(global);
    });
}

// ─── Shared mode event wiring ────────────────────────────────────────────────

/**
 * Wires the shared-mode hamburger menu: toggle dropdown, quality cycle,
 * reset view, and info panel toggle.
 */
function setupSharedMenuHandlers(global: Global, toggle: (id: string | null) => void): void {
    const { events, state } = global;
    const menuBtn    = document.getElementById('sharedMenuBtn');
    const dropdown   = document.getElementById('sharedMenuDropdown');
    const qualityBtn = document.getElementById('sharedQualityBtn');
    const resetBtn   = document.getElementById('sharedResetBtn');
    const infoBtn    = document.getElementById('sharedInfoBtn');
    const closeBtn   = document.getElementById('customClosePanelBtn');

    if (!menuBtn || !dropdown) return;

    let menuOpen = false;

    /** Toggle the dropdown menu visibility. */
    const toggleMenu = (forceClose = false) => {
        menuOpen = forceClose ? false : !menuOpen;
        dropdown.style.display = menuOpen ? 'flex' : 'none';
        menuBtn.classList.toggle('active', menuOpen);
    };

    menuBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleMenu();
    });

    // Close menu when clicking outside (use .contains to catch clicks on SVG children)
    document.addEventListener('click', (e) => {
        if (menuOpen && !dropdown.contains(e.target as Node) && !menuBtn.contains(e.target as Node)) {
            toggleMenu(true);
        }
    }, { signal: documentListenerAc?.signal });

    // Quality cycle — sync initial index with actual renderScale from URL params
    let qualityIndex = QUALITY_PRESETS.findIndex(p => p.scale === state.renderScale);
    if (qualityIndex === -1) qualityIndex = QUALITY_PRESETS.findIndex(p => p.scale === 1.0);
    if (qualityIndex === -1) qualityIndex = 2;
    // Update label to match actual initial state
    if (qualityBtn) {
        const span = qualityBtn.querySelector('span');
        if (span) span.textContent = `Quality: ${QUALITY_PRESETS[qualityIndex].label}`;
    }

    qualityBtn?.addEventListener('click', () => {
        qualityIndex = (qualityIndex + 1) % QUALITY_PRESETS.length;
        const preset = QUALITY_PRESETS[qualityIndex];
        state.renderScale = preset.scale;
        viewerState.renderScale = preset.scale;
        const span = qualityBtn.querySelector('span');
        if (span) span.textContent = `Quality: ${preset.label}`;
        showToast(`Quality: ${preset.label} (${preset.scale}x)`);
        // Keep menu open for quick cycling
    });

    // Reset view
    resetBtn?.addEventListener('click', () => {
        events.fire('inputEvent', 'reset'); // [PC API]
        toggleMenu(true);
        showToast('View reset');
    });

    // Info panel toggle
    infoBtn?.addEventListener('click', () => {
        toggle('infoContent');
        toggleMenu(true);
    });

    // Close panel button
    closeBtn?.addEventListener('click', () => toggle(null));
}

// ─── Touch: swipe-down to close panel ────────────────────────────────────────

/**
 * Adds touch event listeners to the panel that close it when the user swipes
 * downward by at least {@link SWIPE_CLOSE_THRESHOLD_PX} pixels.
 */
function setupTouchClose(toggle: (id: string | null) => void): void {
    const panel = document.getElementById('customControlPanel') ?? document.body;
    let touchStartY = 0;

    panel.addEventListener('touchstart', (e) => {
        if (panel.classList.contains('expanded')) {
            touchStartY = (e as TouchEvent).touches[0].clientY;
        }
    }, { passive: true });

    panel.addEventListener('touchmove', (e) => {
        const te = e as TouchEvent;
        if (panel.classList.contains('expanded') && touchStartY > 0) {
            if (te.touches[0].clientY - touchStartY > SWIPE_CLOSE_THRESHOLD_PX) {
                toggle(null);
                touchStartY = 0;
                e.preventDefault();
            }
        }
    }, { passive: false });

    panel.addEventListener('touchend', () => { touchStartY = 0; }, { passive: true });
}

// ─── Entry point ─────────────────────────────────────────────────────────────

/**
 * Builds and mounts the entire custom UI into `document.body`, then wires all
 * panel controls, icon handlers, and deeper panel logic.
 *
 * Branches on {@link viewerMode}:
 *   - **editor**: Full icon bar + Settings/Info/Dev panels
 *   - **shared**: Hamburger menu + Info panel only
 *
 * Safe to call multiple times — any previously mounted panel is removed first
 * (hot-reload safety).
 */
function setupCustomUI(global: Global): void {
    // Remove any existing custom panel and document listeners (hot-reload safety)
    document.getElementById('customControlPanel')?.remove();
    document.getElementById('sharedMenuWrapper')?.remove();
    documentListenerAc?.abort();
    documentListenerAc = new AbortController();

    const hasTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    const mode = viewerMode;

    const panel   = createControlPanel();
    const content = createContentArea(hasTouch, mode);

    if (mode === 'editor') {
        // ── Editor mode: full icon bar + all panels ──────────────────────────
        const iconBar = createEditorIconBar();
        panel.appendChild(content);   // left of icon bar in flex row
        panel.appendChild(iconBar);
        document.body.appendChild(panel);

        // Hide all content sections initially
        panel.querySelectorAll<HTMLElement>('.content-section').forEach(s => { s.style.display = 'none'; });
        const closePanelBtn = document.getElementById('customClosePanelBtn');
        if (closePanelBtn) closePanelBtn.style.display = 'none';

        const toggle = buildPanelController(global);
        setupEditorIconHandlers(global, toggle);

        if (hasTouch) {
            setupTouchClose(toggle);
        }

        // Wire up deeper panel logic
        setupSettingsControls(global);
        setupDevPanel(global);
    } else {
        // ── Shared mode: hamburger menu + info panel only ────────────────────
        panel.appendChild(content);
        document.body.appendChild(panel);

        // Hide all content sections initially
        panel.querySelectorAll<HTMLElement>('.content-section').forEach(s => { s.style.display = 'none'; });
        const closePanelBtn = document.getElementById('customClosePanelBtn');
        if (closePanelBtn) closePanelBtn.style.display = 'none';

        // Hamburger menu is positioned independently (fixed bottom-right)
        const sharedMenu = createSharedMenu();
        document.body.appendChild(sharedMenu);

        const toggle = buildPanelController(global);
        setupSharedMenuHandlers(global, toggle);

        if (hasTouch) {
            setupTouchClose(toggle);
        }
    }
}

export { setupCustomUI };
