/**
 * @file walk-source.ts
 * Synthetic CameraFrame generator for click-to-walk navigation.
 * Produces move and rotate input frames that steer the walker toward a target
 * point, and detects arrival or blockage to stop the walk automatically.
 */

import { Vec3 } from 'playcanvas';

import type { CameraFrame } from './camera';

const RAD_TO_DEG = 180 / Math.PI;

/**
 * XZ distance (world units) below which the walker considers itself arrived.
 * Sized to work for both raw scenes (m-scale) and `normalizeAndReframe`-shrunk
 * scenes (where the model is rescaled to ~2 m on its longest axis). 0.5 m was
 * sometimes larger than the entire normalized scene, causing instant arrival.
 */
const ARRIVAL_DIST = 0.1;

/**
 * Per-frame world-space movement (in meters) below which the camera is
 * considered to be at a true standstill. Position-delta is used instead of
 * a speed threshold so the same value works at any scene scale — actual
 * walking moves the camera by orders of magnitude more than this per frame
 * even in heavily-normalized scenes, while collision-locked or velocity-
 * decayed cameras drop to ~0.
 */
const STANDSTILL_DIST = 1e-5;

/** Seconds of continuous standstill (while aligned) before we give up. */
const STANDSTILL_DURATION = 1.5;

/**
 * Yaw error (degrees) below which we consider the camera "aligned" enough
 * that low forward speed is suspicious. Above this we assume we're still
 * turning toward the target and don't count it toward standstill.
 */
const ALIGN_DEG = 25;

/**
 * Generates synthetic move/rotate input to auto-walk toward a target position.
 *
 * Designed to feed into WalkController's existing update path so there is no
 * duplicated physics. Each frame it appends yaw-rotation and forward-movement
 * deltas to the shared CameraFrame, and monitors arrival / blocked conditions.
 */
class WalkSource {
    /**
     * Forward input scale (matches InputController.moveSpeed for consistent
     * speed with regular WASD walking).
     */
    walkSpeed = 4;

    /**
     * Maximum yaw turn rate in degrees per second.
     */
    maxTurnRate = 192;

    /**
     * Proportional gain mapping yaw error (degrees) to desired turn rate.
     * Below maxTurnRate / turnGain degrees the turn rate scales linearly;
     * above that it is capped at maxTurnRate. The rate filter is
     * automatically critically damped so there is no overshoot.
     */
    turnGain = 5;

    /**
     * Callback fired when an auto-walk completes (arrival or obstacle).
     */
    onComplete: (() => void) | null = null;

    private _target: Vec3 | null = null;

    private _yawRate = 0;

    private _stillTime = 0;

    /** Camera world-space position last frame, used for standstill detection. */
    private _prevPosition = new Vec3();

    /** Whether _prevPosition has been seeded since the last walkTo() — guards
     *  against the very first frame's bogus zero-delta cancelling the walk. */
    private _prevPositionValid = false;

    get isWalking(): boolean {
        return this._target !== null;
    }

    /**
     * Begin auto-walking toward a world-space target position.
     *
     * @param target - The destination (XZ used for navigation).
     */
    walkTo(target: Vec3) {
        if (!this._target) {
            this._target = new Vec3();
        }
        this._target.copy(target);
        this._stillTime = 0;
        this._prevPositionValid = false;
    }

    /**
     * Cancel any active auto-walk.
     */
    cancelWalk() {
        if (this._target) {
            this._target = null;
            this._yawRate = 0;
            this._stillTime = 0;
            this._prevPositionValid = false;
            this.onComplete?.();
        }
    }

    /**
     * Compute walk deltas and append them to the frame. Must be called
     * before* the camera controller reads the frame.
     *
     * @param dt - Frame delta time in seconds.
     * @param cameraPosition - Camera world position (previous frame output).
     * @param cameraAngles - Camera Euler angles in degrees (previous frame output).
     * @param frame - The shared CameraFrame to append deltas to.
     */
    update(dt: number, cameraPosition: Vec3, cameraAngles: Vec3, frame: CameraFrame) {
        if (!this._target) return;

        const target = this._target;

        const dx = target.x - cameraPosition.x;
        const dz = target.z - cameraPosition.z;
        const xzDist = Math.sqrt(dx * dx + dz * dz);

        // arrival
        if (xzDist < ARRIVAL_DIST) {
            this.cancelWalk();
            return;
        }

        // yaw toward target — computed first so the standstill detector can
        // ignore frames where we're still rotating to face the destination
        // (forward motion is intentionally throttled by alignment in that phase).
        const targetYaw = Math.atan2(-dx, -dz) * RAD_TO_DEG;
        let yawDiff = targetYaw - cameraAngles.y;
        yawDiff = ((yawDiff % 360) + 540) % 360 - 180;
        const aligned = Math.abs(yawDiff) < ALIGN_DEG;

        // Standstill detection — scale-invariant. A blocked-by-collision walker
        // velocity-decays to ~0 so the camera position barely changes; a real
        // walker (even in a heavily-normalized 2 m scene) advances orders of
        // magnitude more than STANDSTILL_DIST per frame. We only count frames
        // where the camera is supposed to be moving forward, i.e. aligned.
        const moved = this._prevPositionValid
            ? this._prevPosition.distance(cameraPosition)
            : Infinity;
        this._prevPosition.copy(cameraPosition);
        this._prevPositionValid = true;

        if (aligned && moved < STANDSTILL_DIST) {
            this._stillTime += dt;
            if (this._stillTime >= STANDSTILL_DURATION) {
                this.cancelWalk();
                return;
            }
        } else {
            this._stillTime = 0;
        }

        const desiredRate = Math.max(-this.maxTurnRate, Math.min(yawDiff * this.turnGain, this.maxTurnRate));
        const smoothing = 1 - Math.exp(-4 * this.turnGain * dt);
        this._yawRate += (desiredRate - this._yawRate) * smoothing;

        // WalkController applies: _angles.y += -rotate[0]
        frame.deltas.rotate.append([-(this._yawRate * dt), 0, 0]);

        // scale forward speed by alignment: turn in place first, then accelerate
        const alignment = Math.max(0, Math.cos(yawDiff * Math.PI / 180));
        frame.deltas.move.append([0, 0, this.walkSpeed * dt * alignment]);
    }
}

export { WalkSource };
