/**
 * @file ViewerExporter.ts
 * ViewerExporter — PlayCanvas port of ViewerExporter.js
 *
 * Generates standalone HTML viewers that embed the current index.js + index.css
 * and pre-configure the content URL + camera state.
 *
 * Key difference from the original Babylon version:
 *   Old: generated a new BABYLON.Engine init script from scratch.
 *   New: embeds the existing rollup bundle (which already knows how to init
 *        everything) and passes state via URL params baked into the <script>
 *        that calls main().
 *
 * Public surface:
 *   - {@link ViewerExporter} — class that builds and downloads HTML/ZIP exports.
 *   - {@link showExportDialog} — renders a modal dialog for choosing export format.
 */

import type { Global } from '../types.js';
import { shareCompleteViewerState } from './urlManager.js';
import { viewerState } from './viewer-state.js';
import { showToast } from './toast.js';

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Formats a byte count into a human-readable string (B / KB / MB / GB).
 *
 * @param bytes - Raw byte count.
 * @returns Formatted string such as `'1.4 MB'`, or `'?'` when `bytes` is falsy.
 */
function formatFileSize(bytes: number): string {
    if (!bytes) return '?';
    const units = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return (bytes / 1024 ** i).toFixed(1) + ' ' + units[i];
}

/**
 * Creates a temporary anchor element to trigger a browser file download.
 *
 * @param blob     - The data to download.
 * @param filename - Suggested filename for the downloaded file.
 */
function downloadBlob(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
}

/**
 * Fetches a URL and returns its body as plain text.
 *
 * @param url - The resource URL to fetch.
 * @returns Resolves with the response body text.
 * @throws When the response status is not OK.
 */
async function fetchText(url: string): Promise<string> {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`Failed to fetch ${url}: ${r.status}`);
    return r.text();
}

// ─── Main export logic ───────────────────────────────────────────────────────

/**
 * Builds and downloads standalone viewer exports (single HTML file or ZIP
 * package) by fetching the live rollup bundle from the running dev/prod server
 * and baking in the current camera + settings state as URL params.
 *
 * Usage:
 * ```ts
 * const exporter = new ViewerExporter(global);
 * await exporter.exportViewer('html');   // single-file export
 * await exporter.exportViewer('zip');    // zip package export
 * ```
 */
export class ViewerExporter {
    private global: Global;

    constructor(global: Global) {
        this.global = global;
    }

    /**
     * Runs the export pipeline for the given format, showing toast notifications
     * for progress and errors.
     *
     * @param format - `'html'` for a single self-contained file, `'zip'` for a
     *                 folder-style package with separate JS/CSS assets.
     */
    async exportViewer(format: 'html' | 'zip' = 'html'): Promise<void> {
        showToast('Preparing export…', 5000);
        try {
            if (format === 'html') {
                await this.exportAsHTML();
            } else {
                await this.exportAsZip();
            }
            showToast('Export complete!');
        } catch (err) {
            showToast('Export failed');
            console.error('[ViewerExporter]', err);
        }
    }

    // ── HTML export ───────────────────────────────────────────────────────────

    private async exportAsHTML(): Promise<void> {
        const html = await this.buildHTML();
        const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
        downloadBlob(blob, `viewer-${Date.now()}.html`);
    }

    private async buildHTML(): Promise<string> {
        const baseUrl = `${location.protocol}//${location.host}${location.pathname.replace(/[^/]*$/, '')}`;

        // Fetch the built bundles from the running server
        const [js, css] = await Promise.all([
            fetchText(`${baseUrl}index.js`),
            fetchText(`${baseUrl}index.css`)
        ]);

        // Build a share URL fragment to bake in current camera + settings
        const shareUrl = this.buildShareUrl();
        const baked = shareUrl ? `'?${shareUrl.split('?')[1] ?? ''}'` : "''";

        // Model URL (use the current content URL if present)
        const contentUrl = JSON.stringify(viewerState.contentUrl || '');

        const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>3D Viewer Export</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>${css}</style>
</head>
<body>
<canvas id="application-canvas" style="width:100%;height:100%;display:block;touch-action:none;outline:none;"></canvas>
<script>
// Baked camera + settings params — applied before main() reads location.search
(function () {
    const baked = ${baked};
    if (baked && !location.search) {
        history.replaceState(null, '', location.pathname + baked);
    }
})();
</script>
<script>
// ── Embedded supersplat-viewer bundle ──
${js}
</script>
<script>
// ── Auto-start ──
(async function () {
    const canvas = document.getElementById('application-canvas');
    if (!canvas || typeof main !== 'function') return;
    const settingsJson = {};
    const config = {
        contentUrl: ${contentUrl},
        noui: false,
        noanim: false,
        nofx: false,
        ministats: false,
        colorize: false,
        unified: false,
        fullload: false,
        aa: false,
        webgpu: false,
        gpusort: false,
        heatmap: false
    };
    await main(canvas, settingsJson, config);
})();
</script>
</body>
</html>`;
        return html;
    }

    // ── ZIP export ────────────────────────────────────────────────────────────

    private async exportAsZip(): Promise<void> {
        // Dynamically load JSZip
        if (!('JSZip' in window)) {
            await new Promise<void>((resolve, reject) => {
                const s = document.createElement('script');
                s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
                s.onload = () => resolve();
                s.onerror = () => reject(new Error('Failed to load JSZip'));
                document.head.appendChild(s);
            });
        }

        const JSZip = (window as any).JSZip;
        const zip = new JSZip();

        const baseUrl = `${location.protocol}//${location.host}${location.pathname.replace(/[^/]*$/, '')}`;
        const [js, css] = await Promise.all([
            fetchText(`${baseUrl}index.js`),
            fetchText(`${baseUrl}index.css`)
        ]);

        const shareUrl = this.buildShareUrl();
        const baked = shareUrl ? `'?${shareUrl.split('?')[1] ?? ''}'` : "''";
        const contentUrl = JSON.stringify(viewerState.contentUrl || '');

        zip.file('index.css', css);
        zip.file('index.js', js);
        zip.file('index.html', this.buildZipHTML(contentUrl, baked));
        zip.file('README.md', this.buildReadme());

        const blob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 6 } });
        downloadBlob(blob, `viewer-${Date.now()}.zip`);
    }

    private buildZipHTML(contentUrl: string, baked: string): string {
        return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>3D Viewer</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="stylesheet" href="index.css">
</head>
<body>
<canvas id="application-canvas" style="width:100%;height:100%;display:block;touch-action:none;outline:none;"></canvas>
<script>
(function () {
    const baked = ${baked};
    if (baked && !location.search) history.replaceState(null, '', location.pathname + baked);
})();
</script>
<script src="index.js"></script>
<script>
(async function () {
    const canvas = document.getElementById('application-canvas');
    if (!canvas || typeof main !== 'function') return;
    await main(canvas, {}, {
        contentUrl: ${contentUrl},
        noui: false, noanim: false, nofx: false, ministats: false,
        colorize: false, unified: false, fullload: false,
        aa: false, webgpu: false, gpusort: false, heatmap: false
    });
})();
</script>
</body>
</html>`;
    }

    private buildReadme(): string {
        const cm = viewerState.cameraManager;
        return `# Exported 3D Viewer

Generated: ${new Date().toISOString()}
Model: ${viewerState.contentUrl || '(drag-dropped file)'}
Camera dist: ${cm?.camera.distance.toFixed(2) ?? '?'}

## Usage
Open index.html in a modern browser with WebGL2 support.
For ZIP export, serve from a local web server (e.g. \`npx serve .\`).
`;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    /**
     * Captures the share URL that `shareCompleteViewerState` would copy to the
     * clipboard, without actually writing to the clipboard.
     *
     * TODO: extract buildShareUrl() as a pure function in urlManager.ts so
     * exporters can call it directly without clipboard side-effects.
     *
     * HACK: `shareCompleteViewerState` has no return value — it only writes to
     * `navigator.clipboard`.  We temporarily monkey-patch `writeText` with a
     * synchronous interceptor to capture the URL string, then restore the
     * original method.  This works because `shareCompleteViewerState` calls
     * `writeText` synchronously (no await before the call), so `captured` is
     * populated before `writeText` is restored.  If that function ever becomes
     * async before the `writeText` call this interception will silently return
     * an empty string.
     */
    private buildShareUrl(): string {
        // The Clipboard API is only available in secure contexts (HTTPS / localhost).
        // On plain HTTP navigator.clipboard is undefined — accessing it would throw.
        if (typeof navigator.clipboard === 'undefined') {
            console.warn(
                '[ViewerExporter] Clipboard API unavailable (page is not served over HTTPS). ' +
                'Exported viewer will open at the default camera position rather than the current view. ' +
                'Serve over HTTPS to enable camera-state baking in exports.'
            );
            showToast('Export: camera state not baked (requires HTTPS)', 5000);
            return '';
        }

        try {
            let captured = '';
            const origWrite = navigator.clipboard.writeText.bind(navigator.clipboard);
            navigator.clipboard.writeText = async (text) => { captured = text; };
            shareCompleteViewerState(this.global);
            navigator.clipboard.writeText = origWrite;
            return captured;
        } catch (err) {
            console.warn('[ViewerExporter] Failed to capture share URL:', err);
            return '';
        }
    }
}

// ─── Dialog ───────────────────────────────────────────────────────────────────

/**
 * Creates and mounts a modal export dialog that lets the user choose between
 * a single HTML export and a ZIP package export.
 *
 * Removes any pre-existing instance of the dialog before mounting a fresh one,
 * so it is safe to call multiple times (e.g. from a toolbar button).
 *
 * @param global - The viewer global context, forwarded to {@link ViewerExporter}.
 */
export function showExportDialog(global: Global): void {
    const existing = document.getElementById('viewerExportDialog');
    if (existing) existing.remove();

    const exporter = new ViewerExporter(global);
    const dialog = document.createElement('div');
    dialog.id = 'viewerExportDialog';
    dialog.style.cssText = `
        position:fixed;inset:0;background:rgba(0,0,0,.8);
        display:flex;align-items:center;justify-content:center;z-index:9999;
    `;
    dialog.innerHTML = `
        <div style="background:#252525;border-radius:12px;padding:24px;width:320px;color:#fff;font-family:inherit;">
            <h3 style="margin:0 0 12px;color:var(--cui-accent,#00aaff)">Export Viewer</h3>
            <p style="margin:0 0 16px;opacity:.8;font-size:13px">
                Embeds the built viewer bundle + current camera state.<br>
                The model URL must remain accessible.
            </p>
            <div style="display:flex;gap:10px;margin-bottom:16px">
                <button id="exportHtmlBtn" style="flex:1;padding:10px;background:#333;border:1px solid #555;border-radius:6px;color:#fff;cursor:pointer">
                    HTML file
                </button>
                <button id="exportZipBtn" style="flex:1;padding:10px;background:#333;border:1px solid #555;border-radius:6px;color:#fff;cursor:pointer">
                    ZIP package
                </button>
            </div>
            <button id="exportCancelBtn" style="width:100%;padding:8px;background:transparent;border:1px solid #555;border-radius:6px;color:#aaa;cursor:pointer">
                Cancel
            </button>
        </div>
    `;
    document.body.appendChild(dialog);

    dialog.querySelector('#exportHtmlBtn')!.addEventListener('click', () => {
        dialog.remove();
        exporter.exportViewer('html');
    });
    dialog.querySelector('#exportZipBtn')!.addEventListener('click', () => {
        dialog.remove();
        exporter.exportViewer('zip');
    });
    dialog.querySelector('#exportCancelBtn')!.addEventListener('click', () => dialog.remove());
    dialog.addEventListener('click', (e) => { if (e.target === dialog) dialog.remove(); });
}
