/**
 * @file infoPanel.ts
 * Info panel — static controls help text, engine-agnostic.
 * Returns an HTML string describing keyboard/mouse/touch controls for the
 * viewer.  Conditionally includes a touch-controls section based on the
 * `hasTouch` flag so desktop users don't see irrelevant instructions.
 */

/**
 * Returns the HTML string for the info panel content section.
 *
 * @param hasTouch - When `true` a touch-controls section is appended.
 */
function createInfoSection(hasTouch: boolean): string {
    return `
        <div id="infoContent" class="content-section">
            <h4>Controls</h4>

            <div class="info-group">
                <div class="info-title">Navigation (Orbit)</div>
                <ul class="info-list">
                    <li><span class="info-action">Left Click + Drag</span>: Orbit Camera</li>
                    <li><span class="info-action">Right Click + Drag</span>: Pan Camera</li>
                    <li><span class="info-action">Scroll</span>: Zoom In/Out</li>
                    <li><span class="info-action">Double Click</span>: Focus Point</li>
                </ul>
            </div>

            <div class="info-group">
                <div class="info-title">Walk Mode</div>
                <ul class="info-list">
                    <li><span class="info-action">Click to enter</span>: Activates walk mode</li>
                    <li><span class="info-action">WASD / Arrow Keys</span>: Move</li>
                    <li><span class="info-action">Mouse Drag</span>: Look around</li>
                    <li><span class="info-action">Space</span>: Jump</li>
                    <li><span class="info-action">Esc</span>: Exit walk mode</li>
                </ul>
            </div>

            ${hasTouch ? `
            <div class="info-group">
                <div class="info-title">Touch Controls</div>
                <ul class="info-list">
                    <li><span class="info-action">One Finger Drag</span>: Orbit Camera</li>
                    <li><span class="info-action">Two Finger Drag</span>: Pan Camera</li>
                    <li><span class="info-action">Pinch</span>: Zoom In/Out</li>
                    <li><span class="info-action">Double Tap</span>: Focus Point</li>
                </ul>
            </div>` : ''}

            <div class="info-group">
                <div class="info-title">General</div>
                <ul class="info-list">
                    <li><span class="info-action">Reset View</span>: Returns to initial camera position</li>
                    <li><span class="info-action">Share</span>: Copies URL with current camera &amp; settings</li>
                </ul>
            </div>
        </div>
    `;
}

export { createInfoSection };
