/**
 * @file viewer-state.ts
 * Shared mutable references that are set once after the PlayCanvas viewer
 * initialises (in `src/index.ts`) and subsequently read by urlManager,
 * settingsPanel, devPanel, and other modules.
 *
 * Treat this module as a lightweight service-locator; do not import it from
 * modules that run before viewer init.
 */

import type { AppBase, Entity, EventHandler } from 'playcanvas';
import type { CameraManager } from '../camera-manager.js';
import type { Viewer } from '../viewer.js';

/**
 * Camera state captured after normalisation, used to restore the home view
 * when the Reset button is pressed.  Matches the `gotoCamera` payload shape.
 */
interface HomeCameraState {
    position: [number, number, number];
    angles:   [number, number, number];
    distance: number;
    fov:      number;
}

/**
 * Shape of the shared viewer state object.
 * All fields are nullable so callers can check for readiness at runtime.
 */
interface ViewerState {
    /** The supersplat Viewer instance. Null until viewer.ts finishes init. */
    viewer: Viewer | null;
    /** Current gallery index when gallery mode is active. -1 means gallery is not active. */
    galleryIndex: number;
    /** PlayCanvas camera manager — owns orbit + walk controllers. */
    cameraManager: CameraManager | null;
    /** The currently loaded gsplat entity. Null when no model is loaded. */
    splatEntity: Entity | null;
    /** Current pixel ratio multiplier (1.0 = native resolution). */
    renderScale: number;
    /** URL of the currently loaded model. Empty string when loaded via drag-drop blob. */
    contentUrl: string;
    /** URL of the currently loaded collision mesh. Empty string means none. */
    collisionUrl: string;
    /** URL of the currently loaded audio file. Empty string means none / blob. */
    audioUrl: string;
    /**
     * URL of the active gallery manifest JSON.
     * Set when a gallery is loaded from a URL (via `?gallery=` param or dev panel URL input).
     * Empty string when no gallery is active or when loaded from a local file (not shareable).
     */
    galleryUrl: string;
    /**
     * Scale factor applied to the last normalised model (TARGET_SIZE / maxDim).
     * 1.0 until the first model load completes normalisation.
     * Used by drag-drop to wrap freshly loaded collision with ScaledCollision.
     */
    normalizedScale: number;
    /**
     * User-chosen walk height multiplier from the Walk Height slider (default 1.0).
     * Stored here so scaleWalkController() can re-apply it after every model
     * reload — otherwise the slider value would be ignored on model change.
     */
    walkHeightMultiplier: number;
    /** PlayCanvas app instance — needed for MeshCollision.fromGlb. // [PC API] */
    app: AppBase | null;
    /**
     * PlayCanvas EventHandler — set from index.ts after init.
     * Used by collision loaders (drag-drop, dev panel) to fire 'collisionLoaded'
     * so index.ts can update state.hasCollision and auto-switch to walk mode.
     */
    events: EventHandler | null;
    /**
     * Home camera state set by `normalizeAndReframe` after each model load.
     * Used to override the default `reset` behaviour so Reset View always
     * returns to the normalised view, not the pre-normalisation frame.
     */
    homeCamera: HomeCameraState | null;
    /**
     * Whether orbit panning (middle-mouse / right-click drag) is allowed.
     * Set by CameraLimits.setPanningEnabled(); read by InputController.
     * Default true — panning is enabled until explicitly disabled.
     */
    panningEnabled: boolean;
}

/**
 * Singleton viewer state.  Set fields from `src/index.ts` after init;
 * read from UI modules.
 */
const viewerState: ViewerState = {
    viewer: null,
    galleryIndex: -1,
    cameraManager: null,
    splatEntity: null,
    renderScale: 1.0,
    contentUrl: '',
    collisionUrl: '',
    audioUrl: '',
    normalizedScale: 1,
    walkHeightMultiplier: 1,
    galleryUrl: '',
    app: null,
    events: null,
    homeCamera: null,
    panningEnabled: true,
};

export { viewerState };
export type { ViewerState, HomeCameraState };
