/**
 * @file parser-utils.ts
 * Shared utilities for custom gsplat format parsers (.splat, .spz).
 *
 * Centralises the fetch-with-progress and PlyElement construction patterns
 * so individual parsers only need to handle format-specific byte decoding.
 *
 * ENGINE UPGRADE NOTES:
 *   - GSplatData constructor: `new GSplatData([vertexElement])` // [PC API]
 *   - GSplatResource constructor: `new GSplatResource(device, data)` // [PC API]
 *   If either signature changes, both parsers break at build time.
 */

import type { Asset } from 'playcanvas';
import { GSplatData, GSplatResource } from 'playcanvas'; // [PC API]
import type { GraphicsDevice } from 'playcanvas';

// ─── Types ───────────────────────────────────────────────────────────────────

/** Property descriptor for a PlyElement (matches PlayCanvas internal format). */
interface PlyProperty {
    type: string;
    name: string;
    storage: Float32Array;
    byteSize: number;
}

/** A single element (vertex group) for GSplatData construction. */
export interface PlyElement {
    name: string;
    count: number;
    properties: PlyProperty[];
}

// ─── Fetch helper ────────────────────────────────────────────────────────────

/**
 * Fetches binary data from a URL or asset contents, with progress reporting.
 *
 * Handles both drag-drop (asset.file.contents) and URL-based loading.
 * Reports progress via `asset.fire('progress', received, total)`.
 */
export async function fetchBinaryWithProgress(
    url: { load: string; original: string } | string,
    asset: Asset,
): Promise<Uint8Array> {
    const loadUrl = typeof url === 'string' ? url : url.load;

    // @ts-ignore — asset.file.contents typedef gap (same pattern as PlyParser in PlayCanvas)
    const response: Response = asset.file?.contents
        ? (asset.file.contents as unknown as Response)
        : await fetch(loadUrl);

    if (!response?.body) {
        throw new Error('Empty response');
    }

    const totalLength = parseInt(response.headers.get('content-length') ?? '0', 10);
    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let totalReceived = 0;

    // eslint-disable-next-line no-constant-condition
    while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        totalReceived += value.byteLength;
        asset.fire('progress', totalReceived, totalLength || totalReceived);
    }

    // Merge chunks into a single buffer
    const buffer = new Uint8Array(totalReceived);
    let offset = 0;
    for (const chunk of chunks) {
        buffer.set(chunk, offset);
        offset += chunk.byteLength;
    }

    return buffer;
}

// ─── GSplatData factory ──────────────────────────────────────────────────────

/**
 * Builds a PlyElement with 14 standard gsplat properties from parallel arrays.
 *
 * This is the format GSplatData expects: a 'vertex' element with named
 * Float32Array storage for position, scale, color (SH0), opacity, and rotation.
 */
export function buildVertexElement(
    numSplats: number,
    arrays: {
        x: Float32Array; y: Float32Array; z: Float32Array;
        scale_0: Float32Array; scale_1: Float32Array; scale_2: Float32Array;
        f_dc_0: Float32Array; f_dc_1: Float32Array; f_dc_2: Float32Array;
        opacity: Float32Array;
        rot_0: Float32Array; rot_1: Float32Array; rot_2: Float32Array; rot_3: Float32Array;
    },
): PlyElement {
    return {
        name: 'vertex',
        count: numSplats,
        properties: Object.entries(arrays).map(([name, storage]) => ({
            type: 'float',
            name,
            storage,
            byteSize: 4,
        })),
    };
}

/**
 * Creates a GSplatResource from a vertex element.
 * Reorders data for optimal rendering performance before uploading to GPU.
 */
export function createGSplatResource(
    device: GraphicsDevice,
    vertexElement: PlyElement,
): any {
    const gsplatData = new GSplatData([vertexElement]); // [PC API]
    gsplatData.reorderData();
    return new GSplatResource(device, gsplatData); // [PC API]
}
