/**
 * @file urlManager.ts
 * URL Parameter Management System — PlayCanvas port of urlManager.js.
 *
 * ## URL compression scheme
 * Long-form parameter names (e.g. `camPosX`, `backgroundColor`) are mapped to
 * short codes (e.g. `a`, `bg`) via {@link URL_PARAM_MAP}.  When the resulting
 * query string exceeds {@link COMPRESSION_THRESHOLD} characters the whole
 * short-coded string is base-64 encoded and stored as a single `c=<b64>`
 * parameter — identified by the {@link COMPRESSION_MARKER} key.
 *
 * ## Backwards-compatibility contract
 * The `URL_PARAM_MAP` short codes MUST NOT be changed.  Existing share links
 * use the short codes, and changing them would silently break those links.
 * New parameters may be added; existing ones must keep their codes.
 *
 * ## content / collision placement rule
 * `content` and `collision` are ALWAYS kept OUTSIDE the compressed blob.
 * `index.html` loads the model before the JS bundle runs, reading these
 * parameters directly from `location.search`.  If they were inside the blob
 * the page would fail to start the initial load.
 */

import { compressToEncodedURIComponent, decompressFromEncodedURIComponent } from 'lz-string';
import type { Global } from '../types.js';
import { getAudioVolume, setAudioVolume } from './audio-player.js';
import { showToast } from './toast.js';
import { viewerState } from './viewer-state.js';
import { cameraLimits, DEFAULTS as LIMIT_DEFAULTS } from './camera-limits.js';

// ─── Constants ────────────────────────────────────────────────────────────────

/**
 * The query-string key used to store the base-64 encoded compressed parameter
 * blob.  Must match the key checked in {@link decompressUrlParameters}.
 */
const COMPRESSION_MARKER = 'c';

/**
 * Minimum compressed string length (characters) before base-64 encoding is
 * attempted.  Below this threshold the uncompressed form is shorter.
 */
const COMPRESSION_THRESHOLD = 50;

/**
 * Decimal places for camera position components (x, y, z) and orbit distance.
 * 3 dp gives sub-millimetre precision at typical scene scales.
 */
const CAMERA_POSITION_PRECISION = 3;

/**
 * Decimal places for camera angle values (pitch, yaw) in degrees.
 * 2 dp gives precision < 0.01 degree — imperceptible in practice.
 */
const CAMERA_ANGLE_PRECISION = 2;

/**
 * Decimal places for field of view in degrees.
 * 1 dp is sufficient; FOV differences below 0.1° are not visible.
 */
const FOV_PRECISION = 1;

/**
 * Decimal places for render scale multiplier.
 * 1 dp covers the meaningful range 0.25–2.0 with steps of 0.05.
 */
const RENDER_SCALE_PRECISION = 1;

/**
 * Decimal places for model scale and the generic position/size short codes
 * `a`, `b`, `r`, `s`.
 */
const GENERIC_PRECISION = 2;

// ─── Parameter maps ───────────────────────────────────────────────────────────

/**
 * Maps verbose URL parameter names to backwards-compatible short codes.
 * Short codes are identical to the original Babylon viewer for link continuity.
 *
 * WARNING: Never change existing short codes — doing so silently breaks all
 * previously generated share links.
 */
const URL_PARAM_MAP: Record<string, string> = {
    // Model / content
    'content':             'm',       // supersplat-viewer uses ?content=, short code stays 'm'
    'collision':           'col',     // collision mesh URL (.glb or voxel)

    // Camera (PlayCanvas orbit: position+angles+distance instead of alpha+beta+radius)
    'camPosX':             'a',       // reuse 'a' short code (was alpha) — now camera pos X
    'camPosY':             'b',       // reuse 'b' short code (was beta)  — now camera pos Y
    'camPosZ':             'r',       // reuse 'r' short code (was radius) — now camera pos Z
    'camAngX':             'x',       // pitch (degrees)
    'camAngY':             'y',       // yaw (degrees)
    'camDist':             'z',       // orbit distance
    'fov':                 'f',
    'scale':               's',

    // Settings panel
    'autoRotate':          'ar',
    'renderScale':         'rs',
    'sharpen':             'sh',
    'sharpenIntensity':    'si',
    'fxaa':                'fx',
    'touchSensitivity':    'ts',
    'backgroundColor':     'bg',

    // Audio
    'audioVolume':         'av',

    // Gallery
    'galleryIndex':        'gi',

    // Camera limits toggles
    'cameraLimits':        'cl',
    'limitZoom':           'lz',
    'limitVertical':       'lv',
    'limitHorizontal':     'lh',
    'enablePanning':       'ep',

    // Camera limits values
    'alphaMin':            'an',
    'alphaMax':            'ax',
    'betaMin':             'bn',
    'betaMax':             'bx',
    'radiusMin':           'rn',
    'radiusMax':           'rx',
    'horizontalAngle':     'ha',
    'horizontalOffset':    'ho',
    'zoomMinDistance':     'zmin',
    'zoomMaxDistance':     'zmax',
    'verticalUpAngle':     'vu',
    'verticalDownAngle':   'vd',
};

/**
 * Reverse lookup: short code → verbose parameter name.
 * Derived from {@link URL_PARAM_MAP}; used during decompression.
 */
const REVERSE_URL_PARAM_MAP: Record<string, string> = Object.fromEntries(
    Object.entries(URL_PARAM_MAP).map(([k, v]) => [v, k])
);

// ─── Compression / decompression ──────────────────────────────────────────────

/**
 * Converts a verbose `URLSearchParams` object into a compressed query string.
 *
 * Each parameter name is replaced with its short code, numeric values are
 * rounded to the appropriate precision, and the result is base-64 encoded as
 * `c=<b64>` if that encoding is shorter than the uncompressed form.
 *
 * @param params - The full-name parameters to compress.
 * @returns A query string (without leading `?`) suitable for appending to a URL.
 */
function compressUrlParameters(params: URLSearchParams): string {
    const compressed = new URLSearchParams();

    for (const [key, value] of params.entries()) {
        const shortKey = URL_PARAM_MAP[key] ?? key;

        if (['a', 'b', 'r', 's'].includes(shortKey)) {
            compressed.set(shortKey, parseFloat(value).toFixed(GENERIC_PRECISION));
        } else if (shortKey === 'f') {
            compressed.set(shortKey, parseFloat(value).toFixed(FOV_PRECISION));
        } else if (shortKey === 'x' || shortKey === 'y') {
            // Camera angles (pitch / yaw) — 2 decimal places
            compressed.set(shortKey, parseFloat(value).toFixed(CAMERA_ANGLE_PRECISION));
        } else if (shortKey === 'z') {
            // camDist — orbit distance, not an angle; use position precision (3dp)
            compressed.set(shortKey, parseFloat(value).toFixed(CAMERA_POSITION_PRECISION));
        } else if (shortKey === 'rs') {
            compressed.set(shortKey, parseFloat(value).toFixed(RENDER_SCALE_PRECISION));
        } else {
            compressed.set(shortKey, value);
        }
    }

    const compressedString = compressed.toString();

    if (compressedString.length > COMPRESSION_THRESHOLD) {
        try {
            // LZString produces output shorter than the input for typical camera/settings
            // query strings. compressToEncodedURIComponent is URL-safe (no % encoding needed).
            const lz = compressToEncodedURIComponent(compressedString);
            if (lz.length < compressedString.length) {
                return `${COMPRESSION_MARKER}=${lz}`;
            }
        } catch {
            // fall through to uncompressed short-code form
        }
    }

    return compressedString;
}

/**
 * Reads URL parameters and returns a `URLSearchParams` object with verbose
 * parameter names regardless of whether the URL was compressed.
 *
 * If the URL contains a `c=<b64>` blob it is decoded first; any plain
 * parameters outside the blob (notably `content` and `collision`) are merged
 * in afterwards.
 *
 * @param searchString - Optional query string to parse (e.g. a share URL's
 *   `?...` portion).  When omitted, `location.search` is used.  Pass a full
 *   URL or just the `?key=value` part — both are handled.
 */
function decompressUrlParameters(searchString?: string): URLSearchParams {
    // Accept full URLs, bare query strings, or undefined (→ location.search)
    let search = searchString ?? location.search;
    const qIdx = search.indexOf('?');
    if (qIdx !== -1) search = search.slice(qIdx);
    const urlParams = new URLSearchParams(search);

    if (urlParams.has(COMPRESSION_MARKER)) {
        try {
            const decoded = decompressFromEncodedURIComponent(urlParams.get(COMPRESSION_MARKER)!);
            if (!decoded) throw new Error('LZString decompression returned null');
            const decodedParams = new URLSearchParams(decoded);
            const full = new URLSearchParams();
            for (const [shortKey, value] of decodedParams.entries()) {
                full.set(REVERSE_URL_PARAM_MAP[shortKey] ?? shortKey, value);
            }
            // Merge plain params that live outside the compressed blob.
            // content and collision are always kept uncompressed so index.html
            // can read them before the JS bundle decompresses the rest.
            for (const [key, value] of urlParams.entries()) {
                if (key === COMPRESSION_MARKER) continue;
                full.set(REVERSE_URL_PARAM_MAP[key] ?? key, value);
            }
            return full;
        } catch {
            // fall through to uncompressed handling
        }
    }

    const full = new URLSearchParams();
    for (const [shortKey, value] of urlParams.entries()) {
        full.set(REVERSE_URL_PARAM_MAP[shortKey] ?? shortKey, value);
    }
    return full;
}

/**
 * Builds a complete share URL from a set of camera + settings parameters.
 * The parameters are compressed before being appended.
 *
 * @param params - The parameters to encode (verbose names).
 * @returns A full absolute URL string.
 */
function createShareUrl(params: URLSearchParams): string {
    const baseUrl = `${location.protocol}//${location.host}${location.pathname}`;
    const compressedParams = compressUrlParameters(params);
    return `${baseUrl}?${compressedParams}`;
}

// ─── Camera state ─────────────────────────────────────────────────────────────

/**
 * Reads the current camera state from the PlayCanvas CameraManager and returns
 * it as a `URLSearchParams` object with verbose parameter names.
 *
 * Returns `null` if the camera manager is not yet initialised.
 */
function getCameraParams(): URLSearchParams | null {
    const cm = viewerState.cameraManager;
    if (!cm) return null;

    const cam = cm.camera; // [PC API]
    const params = new URLSearchParams();

    params.set('camPosX', cam.position.x.toFixed(CAMERA_POSITION_PRECISION));
    params.set('camPosY', cam.position.y.toFixed(CAMERA_POSITION_PRECISION));
    params.set('camPosZ', cam.position.z.toFixed(CAMERA_POSITION_PRECISION));
    params.set('camAngX', cam.angles.x.toFixed(CAMERA_ANGLE_PRECISION));
    params.set('camAngY', cam.angles.y.toFixed(CAMERA_ANGLE_PRECISION));
    params.set('camDist', cam.distance.toFixed(CAMERA_POSITION_PRECISION));
    params.set('fov',     cam.fov.toFixed(FOV_PRECISION));

    return params;
}

// ─── Settings panel → URL ─────────────────────────────────────────────────────

/**
 * Reads the current settings panel DOM state and appends non-default values to
 * `params` as verbose URL parameter names.
 *
 * This is a DOM-only read function — no engine API calls are made here.
 * Mirrors `addSettingsPanelToUrl` from the original Babylon version.
 *
 * @param params - The URLSearchParams object to append settings into.
 */
function addSettingsPanelToUrl(params: URLSearchParams): void {
    const autoRotateToggle = document.getElementById('autoRotateToggle') as HTMLInputElement | null;
    if (autoRotateToggle && !autoRotateToggle.checked) {
        params.set('autoRotate', '0');
    }

    const vol = getAudioVolume();
    if (vol !== 1) {
        params.set('audioVolume', vol.toFixed(2));
    }

    if (viewerState.renderScale !== 1.0) {
        params.set('renderScale', viewerState.renderScale.toFixed(RENDER_SCALE_PRECISION));
    }

    const sharpenToggle = document.getElementById('sharpenToggle') as HTMLInputElement | null;
    if (sharpenToggle?.checked) {
        params.set('sharpen', '1');
        // Only persist intensity when sharpening is actually on — no point serialising
        // a value that has no effect and would bloat every share URL.
        const sharpenIntensityRange = document.getElementById('sharpenIntensityRange') as HTMLInputElement | null;
        if (sharpenIntensityRange) {
            params.set('sharpenIntensity', parseFloat(sharpenIntensityRange.value).toFixed(FOV_PRECISION));
        }
    }

    const fxaaToggle = document.getElementById('fxaaToggle') as HTMLInputElement | null;
    if (fxaaToggle?.checked) params.set('fxaa', '1');

    const bgPicker = document.getElementById('backgroundColorPicker') as HTMLInputElement | null;
    if (bgPicker && bgPicker.value !== '#191919') {
        params.set('backgroundColor', bgPicker.value);
    }

    // Camera limits — always serialise the master toggle so that sharing with
    // limits OFF is preserved. Absence of the key means "use index.ts defaults"
    // (enabled), so we must write cameraLimits=0 to explicitly record disabled.
    const cameraLimitsToggle = document.getElementById('cameraLimitsToggle') as HTMLInputElement | null;
    if (cameraLimitsToggle) {
        if (cameraLimitsToggle.checked) {
            params.set('cameraLimits', '1');

            // Per-axis toggles are only meaningful when limits are active.
            for (const [id, key] of [
                ['limitZoomToggle',       'limitZoom'],
                ['limitVerticalToggle',   'limitVertical'],
                ['limitHorizontalToggle', 'limitHorizontal'],
                ['limitPanToggle',        'enablePanning'],
            ] as [string, string][]) {
                const el = document.getElementById(id) as HTMLInputElement | null;
                if (el) params.set(key, el.checked ? '1' : '0');
            }
            // Slider values are only meaningful when limits are active — keep
            // them inside this block so disabled-limits URLs stay clean.
            for (const [id, key, def] of [
                ['horizontalAngleRange',  'horizontalAngle',  LIMIT_DEFAULTS.horizontal.totalAngle],
                ['horizontalOffsetRange', 'horizontalOffset', LIMIT_DEFAULTS.horizontal.offset],
                ['minDistanceRange',      'zoomMinDistance',  LIMIT_DEFAULTS.zoom.min],
                ['maxDistanceRange',      'zoomMaxDistance',  LIMIT_DEFAULTS.zoom.max],
                ['verticalUpRange',       'verticalUpAngle',  LIMIT_DEFAULTS.vertical.upDeg],
                ['verticalDownRange',     'verticalDownAngle',LIMIT_DEFAULTS.vertical.downDeg],
            ] as [string, string, number][]) {
                const el = document.getElementById(id) as HTMLInputElement | null;
                if (el && parseFloat(el.value) !== def) {
                    params.set(key, el.value);
                }
            }
        } else {
            params.set('cameraLimits', '0');
        }
    }
}

// ─── Apply URL → camera state ─────────────────────────────────────────────────

/**
 * Reads camera state from the URL (if present) and fires the appropriate
 * PlayCanvas events to restore the view.
 *
 * Also restores model scale from the `scale` URL parameter if present.
 *
 * @param global - The PlayCanvas Global context object.
 * @param params - Pre-parsed URL params. When omitted the URL is parsed fresh.
 *                 Pass the result of {@link decompressUrlParameters} when calling
 *                 alongside {@link applySettingsFromUrl} to avoid parsing twice.
 */
function applyCameraFromUrl(global: Global, params = decompressUrlParameters()): void {

    const hasCamera = params.has('camPosX') && params.has('camAngY') && params.has('camDist');
    if (!hasCamera) return;

    const payload = {
        position: [
            parseFloat(params.get('camPosX') ?? '0'),
            parseFloat(params.get('camPosY') ?? '0'),
            parseFloat(params.get('camPosZ') ?? '0'),
        ] as [number, number, number],
        angles: [
            parseFloat(params.get('camAngX') ?? '0'),
            parseFloat(params.get('camAngY') ?? '0'),
            0,
        ] as [number, number, number],
        distance: parseFloat(params.get('camDist') ?? '1'),
        fov: parseFloat(params.get('fov') ?? '75'),
    };

    global.events.fire('inputEvent', 'gotoCamera', payload);

    // Store as homeCamera so Reset View returns to the URL-specified position.
    // In shared mode normalizeAndReframe is skipped (homeCamera stays null otherwise),
    // leaving the reset handler with nothing to go back to.
    viewerState.homeCamera = payload;

    // Apply model scale if present — also update slider so it reflects the value
    const scale = params.has('scale') ? parseFloat(params.get('scale')!) : NaN;
    if (!isNaN(scale) && scale > 0 && viewerState.splatEntity) {
        viewerState.splatEntity.setLocalScale(scale, scale, scale); // [PC API]
        const scaleEl = document.getElementById('modelScaleRange') as HTMLInputElement | null;
        if (scaleEl) {
            scaleEl.value = String(scale);
            scaleEl.dispatchEvent(new Event('input', { bubbles: true }));
        }
    }
}

// ─── Apply URL → settings panel ───────────────────────────────────────────────

/**
 * Reads settings state from the URL (if present) and restores it — updating
 * both the PlayCanvas engine and the DOM so sliders/toggles reflect the values.
 *
 * @param global - The PlayCanvas Global context object.
 * @param params - Pre-parsed URL params. When omitted the URL is parsed fresh.
 *                 Pass the result of {@link decompressUrlParameters} when calling
 *                 alongside {@link applyCameraFromUrl} to avoid parsing twice.
 */
function applySettingsFromUrl(global: Global, params = decompressUrlParameters()): void {
    const { app, events, state, settings, camera } = global;

    if (params.has('backgroundColor')) {
        const bgColor = params.get('backgroundColor')!;
        if (/^#[0-9A-F]{6}$/i.test(bgColor)) {
            const r = parseInt(bgColor.slice(1, 3), 16) / 255;
            const g = parseInt(bgColor.slice(3, 5), 16) / 255;
            const b = parseInt(bgColor.slice(5, 7), 16) / 255;
            camera.camera!.clearColor.set(r, g, b, 1); // [PC API]
            const el = document.getElementById('backgroundColorPicker') as HTMLInputElement | null;
            if (el) {
                el.value = bgColor;
                el.dispatchEvent(new Event('input', { bubbles: true }));
            }
        }
    }

    /** Sets a slider value and fires `input` so the display label updates. */
    const setSlider = (id: string, value: number) => {
        const el = document.getElementById(id) as HTMLInputElement | null;
        if (el) {
            el.value = String(value);
            el.dispatchEvent(new Event('input', { bubbles: true }));
        }
    };

    if (params.has('renderScale')) {
        const rs = parseFloat(params.get('renderScale')!);
        if (!isNaN(rs) && rs > 0) {
            state.renderScale = rs;
            viewerState.renderScale = rs;
            setSlider('renderScaleRange', rs);
        }
    }

    if (params.has('autoRotate')) {
        const ar = params.get('autoRotate') !== '0';
        events.fire('inputEvent', 'setAutoRotate', { enabled: ar, speed: 0.7 });
        const el = document.getElementById('autoRotateToggle') as HTMLInputElement | null;
        if (el) {
            el.checked = ar;
            el.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }

    if (params.has('audioVolume')) {
        const vol = parseFloat(params.get('audioVolume')!);
        if (!isNaN(vol)) setAudioVolume(vol);
    }

    if (params.has('sharpen')) {
        const enabled = params.get('sharpen') === '1';
        const intensity = params.has('sharpenIntensity')
            ? parseFloat(params.get('sharpenIntensity')!)
            : 0.5;
        settings.postEffectSettings.sharpness.enabled = enabled;
        settings.postEffectSettings.sharpness.amount = isNaN(intensity) ? 0.5 : intensity;
        viewerState.viewer?.configureCamera(settings); // [PC API]
        const toggleEl = document.getElementById('sharpenToggle') as HTMLInputElement | null;
        if (toggleEl) {
            toggleEl.checked = enabled;
            toggleEl.dispatchEvent(new Event('change', { bubbles: true }));
        }
        setSlider('sharpenIntensityRange', settings.postEffectSettings.sharpness.amount);
    }

    if (params.has('fov')) {
        const fov = parseFloat(params.get('fov')!);
        if (!isNaN(fov)) {
            events.fire('inputEvent', 'setFov', { fov });
            setSlider('fovRange', fov);
        }
    }

    // fxaa — toggle is currently disabled in the UI (not yet implemented in postEffectSettings)
    // restoration deferred until fxaa is wired up in the settings schema.

    // Camera limits — only restore when the URL explicitly carries a cameraLimits param.
    // Absence means "use defaults" (index.ts initialises to enabled + zoom 1–15).
    if (params.has('cameraLimits')) {
        const clEnabled = params.get('cameraLimits') === '1';

        const masterEl = document.getElementById('cameraLimitsToggle') as HTMLInputElement | null;
        if (masterEl) masterEl.checked = clEnabled;

        if (clEnabled) {
            const lzEnabled  = params.get('limitZoom')       === '1';
            const lvEnabled  = params.get('limitVertical')   === '1';
            const lhEnabled  = params.get('limitHorizontal') === '1';
            const panEnabled = params.get('enablePanning')   !== '0';

            const setChecked = (id: string, checked: boolean) => {
                const el = document.getElementById(id) as HTMLInputElement | null;
                if (el) el.checked = checked;
            };
            setChecked('limitZoomToggle',       lzEnabled);
            setChecked('limitVerticalToggle',   lvEnabled);
            setChecked('limitHorizontalToggle', lhEnabled);
            setChecked('limitPanToggle',        panEnabled);

            // parseOrDefault: falls back to the canonical DEFAULTS when the
            // param is absent OR contains a non-numeric value (e.g. corrupted URL).
            const parseOrDefault = (key: string, def: number) => {
                if (!params.has(key)) return def;
                const v = parseFloat(params.get(key)!);
                return isNaN(v) ? def : v;
            };

            const zmin     = parseOrDefault('zoomMinDistance',  LIMIT_DEFAULTS.zoom.min);
            const zmax     = parseOrDefault('zoomMaxDistance',  LIMIT_DEFAULTS.zoom.max);
            const vuAngle  = parseOrDefault('verticalUpAngle',  LIMIT_DEFAULTS.vertical.upDeg);
            const vdAngle  = parseOrDefault('verticalDownAngle',LIMIT_DEFAULTS.vertical.downDeg);
            const haAngle  = parseOrDefault('horizontalAngle',  LIMIT_DEFAULTS.horizontal.totalAngle);
            const hoOffset = parseOrDefault('horizontalOffset', LIMIT_DEFAULTS.horizontal.offset);

            // Update slider DOM + fire 'input' so display labels refresh.
            // Toggles are already set above so the setupEnhancedRangeControl
            // callbacks will read the correct enabled state from the DOM.
            setSlider('minDistanceRange',      zmin);
            setSlider('maxDistanceRange',      zmax);
            setSlider('verticalUpRange',       vuAngle);
            setSlider('verticalDownRange',     vdAngle);
            setSlider('horizontalAngleRange',  haAngle);
            setSlider('horizontalOffsetRange', hoOffset);

            // Apply limit values and panning directly (no DOM events needed).
            cameraLimits.setDistanceLimits(lzEnabled, zmin, zmax);
            cameraLimits.setVerticalLimitsUpDown(lvEnabled, vuAngle, vdAngle);
            cameraLimits.setHorizontalLimitsAngleOffset(lhEnabled, haAngle, hoOffset);
            cameraLimits.setPanningEnabled(panEnabled);
        }

        // Apply master toggle last so apply() sees the correct enabled state.
        cameraLimits.setEnabled(clEnabled);
    }

    app.renderNextFrame = true; // [PC API]
}

// ─── Clipboard helpers ────────────────────────────────────────────────────────

/**
 * Legacy clipboard fallback using `document.execCommand('copy')`.
 * Used when the async Clipboard API is unavailable (plain HTTP contexts).
 *
 * `execCommand` is deprecated but still supported in all major browsers.
 * We check its boolean return value and show a distinct message on failure
 * rather than silently claiming success.
 *
 * @param text - The string to copy to the clipboard.
 */
function copyFallback(text: string): void {
    const input = document.createElement('input');
    input.value = text;
    // Must be in the DOM and not display:none for execCommand to work
    input.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0';
    document.body.appendChild(input);
    input.select();
    const ok = document.execCommand('copy');
    input.remove();
    if (ok) {
        showToast('URL copied to clipboard!');
    } else {
        // execCommand failed — surface the URL so the user can copy it manually
        console.warn('[urlManager] execCommand copy failed. URL:', text);
        showToast('Copy failed — see console for URL', 6000);
    }
}

// ─── Main share function ──────────────────────────────────────────────────────

/**
 * Captures the complete current viewer state (camera + settings) and copies a
 * share URL to the clipboard.
 *
 * `content` and `collision` are intentionally kept OUTSIDE the compressed blob
 * so that `index.html` (which runs before JS decompression) can always read
 * them to initiate the initial model load.
 *
 * @param global - The PlayCanvas Global context object.
 */
function shareCompleteViewerState(global: Global): void {
    const camParams = getCameraParams();
    if (!camParams) {
        showToast('Viewer not ready yet');
        return;
    }

    // Scale — goes into the compressed blob (camera data)
    if (viewerState.splatEntity) {
        const scale = viewerState.splatEntity.getLocalScale().x; // [PC API]
        if (Math.abs(scale - 1.0) > 0.001) {
            camParams.set('scale', scale.toFixed(GENERIC_PRECISION));
        }
    }

    addSettingsPanelToUrl(camParams);

    // Parse location.search once — used for several fallback reads below.
    const searchParams = new URLSearchParams(location.search);

    // Gallery is active when viewerState.galleryIndex >= 0 AND a manifest URL is known.
    // viewerState.galleryIndex is -1 by default and reset to -1 on model reload, so
    // ">= 0" correctly guards against the "gallery was once active but model was replaced" case.
    // viewerState.galleryUrl is authoritative; fall back to location.search only when it
    // hasn't been set yet (e.g. very early Share click before index.ts assigns it).
    const galleryUrl = viewerState.galleryUrl || searchParams.get('gallery') || '';
    const galleryActive = !!(galleryUrl && viewerState.galleryIndex >= 0);

    // Gallery index — must be added to camParams BEFORE createShareUrl compresses the blob.
    // galleryIndex=0 is the default and is omitted to keep URLs short.
    if (galleryActive && viewerState.galleryIndex > 0) {
        camParams.set('galleryIndex', String(viewerState.galleryIndex));
    }

    // Compress camera + settings params into the base URL.
    // content, collision, audio, and gallery are kept OUTSIDE the compressed blob
    // so that index.html (which runs before JS decompression) can always read them.
    const baseUrl = createShareUrl(camParams);
    const finalUrl = new URL(baseUrl);

    // Explicit shared-mode marker — kept outside the compressed blob so detection
    // works even if decompression fails. Camera-param detection remains as fallback
    // for old links that predate this param.
    finalUrl.searchParams.set('sm', '1');

    // When gallery is active, content= comes from the manifest — omit it to keep URLs clean.
    if (!galleryActive) {
        const contentUrl = viewerState.contentUrl || searchParams.get('content') || '';
        if (contentUrl) finalUrl.searchParams.set('content', contentUrl);
    }

    const collisionUrl = viewerState.collisionUrl || searchParams.get('collision') || '';
    if (collisionUrl) {
        finalUrl.searchParams.set('collision', collisionUrl);
    }

    const audioUrl = viewerState.audioUrl || searchParams.get('audio') || '';
    if (audioUrl) {
        finalUrl.searchParams.set('audio', audioUrl);
    }

    // Gallery — preserve manifest URL outside the blob so index.html can read it.
    if (galleryActive) {
        finalUrl.searchParams.set('gallery', galleryUrl);
    }

    const shareUrl = finalUrl.toString();

    // Prefer the modern async Clipboard API (requires HTTPS / localhost).
    // Fall back to the legacy execCommand path for HTTP contexts.
    if (navigator.clipboard) {
        navigator.clipboard.writeText(shareUrl).then(() => {
            showToast('URL copied to clipboard!');
        }).catch(() => {
            copyFallback(shareUrl);
        });
    } else {
        copyFallback(shareUrl);
    }
}

export {
    URL_PARAM_MAP,
    REVERSE_URL_PARAM_MAP,
    compressUrlParameters,
    decompressUrlParameters,
    createShareUrl,
    addSettingsPanelToUrl,
    applyCameraFromUrl,
    applySettingsFromUrl,
    shareCompleteViewerState,
};
