/**
 * @file devPanel.ts
 * Developer panel — live FPS, resolution, splat count, model URL loader,
 * and export button.
 *
 * Stats are only updated when the panel is visible to avoid unnecessary DOM
 * writes while it is hidden.
 */

import type { Global } from '../../types.js';
import { setAudioVolume, setupAudioPlayer } from '../audio-player.js';
import { applyVoxelCollision } from '../drag-drop.js';
import { isGalleryManifest, activateGallery } from '../gallery.js';
import { viewerState } from '../viewer-state.js';
import { showToast } from '../toast.js';
import { showExportDialog } from '../viewer-exporter.js';

// ─── Constants ────────────────────────────────────────────────────────────────

/** Number of frames used for the rolling FPS average. */
const FPS_WINDOW = 30;

/** Camera URL params that should be stripped when navigating to a new model
 *  so the new model gets auto-framed rather than inheriting a stale camera. */
const CAMERA_PARAMS_TO_STRIP = ['camPosX', 'camPosY', 'camPosZ', 'camAngX', 'camAngY', 'camDist'];

// ─── HTML builder ─────────────────────────────────────────────────────────────

/**
 * Returns the HTML string for the developer panel content section.
 * Contains live stats displays, a URL loader for remote models, and an
 * "Export Viewer" button.
 */
export function createDevSection(): string {
    return `
        <div id="devContent" class="content-section">
            <h4>Developer</h4>

            <div class="dev-stats">
                <div class="dev-stat-row">
                    <span class="dev-stat-label">FPS</span>
                    <span class="dev-stat-value" id="devFps">—</span>
                </div>
                <div class="dev-stat-row">
                    <span class="dev-stat-label">Resolution</span>
                    <span class="dev-stat-value" id="devResolution">—</span>
                </div>
                <div class="dev-stat-row">
                    <span class="dev-stat-label">Splats</span>
                    <span class="dev-stat-value" id="devSplats">—</span>
                </div>
            </div>

            <div class="control-group" style="margin-top: 12px;">
                <label for="devModelUrl">Model URL (.ply / .sog / .splat / .spz)</label>
            </div>
            <div class="dev-url-row">
                <input type="text" id="devModelUrl" class="dev-text-input" placeholder="https://…/model.sog">
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <label for="devCollisionUrl">Collision URL (.glb or .voxel.json) <span style="opacity:0.5">optional</span></label>
            </div>
            <div class="dev-url-row">
                <input type="text" id="devCollisionUrl" class="dev-text-input" placeholder="https://…/collision.glb or collision.voxel.json">
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <input type="file" id="devVoxelFileInput" accept=".json,.bin" multiple style="display:none">
                <button id="devVoxelBtn" class="action-button" style="width: 100%;">Load Voxel Collision… <span style="opacity:0.5;font-size:11px">(select both files)</span></button>
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <label for="devAudioUrl">Audio URL (.mp3 / .ogg / .wav) <span style="opacity:0.5">optional</span></label>
            </div>
            <div class="dev-url-row">
                <input type="text" id="devAudioUrl" class="dev-text-input" placeholder="https://…/ambient.mp3">
                <button id="devLoadBtn" class="action-button" style="margin-top: 8px; width: 100%;">Load</button>
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <label for="devAudioVolume">Audio Volume</label>
                <input type="range" id="devAudioVolume" class="dev-volume-slider" min="0" max="1" step="0.01" value="1">
            </div>

            <div class="control-group" style="margin-top: 16px;">
                <label for="devGalleryUrl">Gallery manifest URL (.json) <span style="opacity:0.5">optional</span></label>
            </div>
            <div class="dev-url-row">
                <input type="text" id="devGalleryUrl" class="dev-text-input" placeholder="https://…/gallery.json">
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <input type="file" id="devGalleryFileInput" accept=".json" style="display:none">
                <button id="devGalleryBtn" class="action-button" style="width: 100%;">Load Gallery JSON… <span style="opacity:0.5;font-size:11px">(or enter URL above)</span></button>
            </div>

            <div class="control-group" style="margin-top: 8px;">
                <button id="devExportBtn" class="action-button" style="width: 100%;">Export Viewer…</button>
            </div>
        </div>
    `;
}

// ─── Setup ────────────────────────────────────────────────────────────────────

/**
 * Wires up all developer panel interactivity:
 *  - Rolling FPS / resolution / splat-count stats updated on each `frameend`.
 *  - URL loader navigates to a new model URL on button click or Enter key.
 *  - Export button opens the {@link showExportDialog} overlay.
 *
 * @param global - The PlayCanvas Global context object.
 */
export function setupDevPanel(global: Global): void {
    const { app } = global;

    setupLiveStats(app);
    setupUrlLoader();
    setupDevAudioVolume();
    setupVoxelLoader();
    setupGalleryLoader(global);
    setupExportButton(global);
}

// ─── Sub-functions ────────────────────────────────────────────────────────────

/**
 * Registers a `frameend` listener that updates the FPS, resolution, and splat
 * count displays.  Updates are skipped when the dev panel is hidden.
 *
 * @param app - The PlayCanvas AppBase instance. // [PC API]
 */
function setupLiveStats(app: Global['app']): void {
    const fpsEl    = document.getElementById('devFps');
    const resEl    = document.getElementById('devResolution');
    const splatsEl = document.getElementById('devSplats');

    const frameTimes: number[] = [];
    let lastTime = performance.now();

    app.on('frameend', () => { // [PC API]
        const now = performance.now();
        frameTimes.push(now - lastTime);
        lastTime = now;
        if (frameTimes.length > FPS_WINDOW) frameTimes.shift();

        // Only update DOM if dev panel is open (avoids hidden-element overhead)
        const devPanel = document.getElementById('devContent');
        if (!devPanel || devPanel.style.display === 'none') return;

        if (fpsEl && frameTimes.length > 1) {
            const avgMs = frameTimes.reduce((a, b) => a + b, 0) / frameTimes.length;
            fpsEl.textContent = Math.round(1000 / avgMs).toString();
        }

        if (resEl) {
            const { canvas } = app.graphicsDevice; // [PC API]
            resEl.textContent = `${canvas.width} × ${canvas.height}`;
        }

        if (splatsEl && viewerState.splatEntity) {
            const gsplat = viewerState.splatEntity.gsplat; // [PC API]
            // TODO: remove @ts-ignore when PlayCanvas typedefs include numSplats on GSplatInstance
            // @ts-ignore
            const count = gsplat?.instance?.numSplats ?? gsplat?.resource?.numSplats;
            splatsEl.textContent = count != null ? count.toLocaleString() : '—';
        }
    });
}

/**
 * Wires the model URL input, gallery URL input, and Load button.
 * - Model URL → navigates to `?content=<url>` (page reload, auto-frames new model).
 * - Gallery URL → navigates to `?gallery=<url>` (page reload, activates gallery mode).
 * - Audio URL only → hot-swaps audio in-page (no reload, Share picks it up).
 * - Gallery URL takes priority when both model and gallery are filled.
 */
function setupUrlLoader(): void {
    const urlInput       = document.getElementById('devModelUrl')     as HTMLInputElement | null;
    const collisionInput = document.getElementById('devCollisionUrl') as HTMLInputElement | null;
    const audioInput     = document.getElementById('devAudioUrl')     as HTMLInputElement | null;
    const galleryInput   = document.getElementById('devGalleryUrl')   as HTMLInputElement | null;
    const loadBtn        = document.getElementById('devLoadBtn');

    // Pre-fill inputs from current URL params so user can see/edit what's loaded
    const currentParams = new URLSearchParams(location.search);
    if (urlInput && currentParams.has('content'))   urlInput.value = currentParams.get('content')!;
    if (collisionInput && currentParams.has('collision')) collisionInput.value = currentParams.get('collision')!;
    if (audioInput && currentParams.has('audio'))   audioInput.value = currentParams.get('audio')!;
    if (galleryInput && currentParams.has('gallery')) galleryInput.value = currentParams.get('gallery')!;

    /** Navigate to a single model URL (page reload). */
    const loadFromUrl = (modelUrl: string, collisionUrl: string, audioUrl: string) => {
        if (!modelUrl) return;
        const params = new URLSearchParams(location.search);
        params.set('content', modelUrl);
        // Strip baked camera params so new model gets auto-framed.
        // Also delete the compressed blob ('c=') — it may contain camera params that
        // would trigger shared mode, preventing auto-frame and full editor UI.
        // Also delete 'gallery' so loading a standalone URL exits gallery mode.
        CAMERA_PARAMS_TO_STRIP.forEach(k => params.delete(k));
        params.delete('c');
        params.delete('gallery');
        if (collisionUrl) {
            params.set('collision', collisionUrl);
        } else {
            params.delete('collision');
        }
        if (audioUrl) {
            params.set('audio', audioUrl);
        } else {
            params.delete('audio');
        }
        window.location.href = `${location.origin}${location.pathname}?${params.toString()}`;
    };

    /** Validate and navigate to a gallery manifest URL (page reload). */
    const loadGalleryFromUrl = async (manifestUrl: string) => {
        if (!manifestUrl) return;
        // Pre-validate: fetch the manifest before navigating so the user gets a
        // clear error instead of a silent reload to the default model.
        showToast('Checking gallery manifest…');
        try {
            const res = await fetch(manifestUrl, {
                signal: AbortSignal.timeout(8000),
            });
            if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
            const data = await res.json();
            if (!isGalleryManifest(data)) throw new Error('Not a valid gallery manifest (missing models[].shareUrl)');
        } catch (err) {
            showToast(`Gallery URL invalid: ${(err as Error).message}`);
            return;
        }
        // Navigate with only ?gallery=<url> — strip everything else so the page
        // starts clean and the gallery's first entry sets its own content/camera.
        window.location.href = `${location.origin}${location.pathname}?gallery=${encodeURIComponent(manifestUrl)}`;
    };

    loadBtn?.addEventListener('click', () => {
        const modelUrl   = urlInput?.value.trim() ?? '';
        const colUrl     = collisionInput?.value.trim() ?? '';
        const audUrl     = audioInput?.value.trim() ?? '';
        const galUrl     = galleryInput?.value.trim() ?? '';

        if (galUrl) {
            // Gallery URL takes priority — validate then reload into gallery mode.
            loadGalleryFromUrl(galUrl).catch(() => { /* error shown as toast */ });
        } else if (modelUrl) {
            // Full model reload — includes collision + audio URLs.
            loadFromUrl(modelUrl, colUrl, audUrl);
        } else if (audUrl) {
            // Audio-only: hot-swap without page reload so Share picks it up.
            setupAudioPlayer(audUrl);
            // viewerState.audioUrl is set inside setupAudioPlayer
            showToast('Audio loaded');
        }
    });

    urlInput?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            loadFromUrl(
                urlInput.value.trim(),
                collisionInput?.value.trim() ?? '',
                audioInput?.value.trim() ?? ''
            );
        }
    });

    galleryInput?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') loadGalleryFromUrl(galleryInput.value.trim()).catch(() => { /* error shown as toast */ });
    });
}

/**
 * Wires the dev panel audio volume slider.
 * Calls {@link setAudioVolume} which also syncs the pill slider.
 */
function setupDevAudioVolume(): void {
    const slider = document.getElementById('devAudioVolume') as HTMLInputElement | null;
    slider?.addEventListener('input', () => {
        setAudioVolume(parseFloat(slider.value));
    });
}

/**
 * Wires the "Load Voxel Collision…" multi-file picker.
 * The user selects both .voxel.json and .voxel.bin from their OS dialog.
 * Shows a clear error if only one file is selected instead of silently failing.
 */
function setupVoxelLoader(): void {
    const btn   = document.getElementById('devVoxelBtn');
    const input = document.getElementById('devVoxelFileInput') as HTMLInputElement | null;
    if (!btn || !input) return;

    btn.addEventListener('click', () => input.click());

    input.addEventListener('change', async () => {
        const files = Array.from(input.files ?? []);
        input.value = ''; // reset so the same files can be re-picked

        const jsonFile = files.find(f => f.name.endsWith('.voxel.json'));
        const binFile  = files.find(f => f.name.endsWith('.voxel.bin'));

        if (!jsonFile && !binFile) return; // no voxel files selected

        if (!jsonFile) { showToast('Also select the matching .voxel.json'); return; }
        if (!binFile)  { showToast('Also select the matching .voxel.bin');  return; }

        await applyVoxelCollision(jsonFile, binFile);
    });
}

/**
 * Wires the "Load Gallery JSON…" button to open a file picker.
 * Parses the selected JSON and activates gallery mode if valid.
 */
function setupGalleryLoader(global: Global): void {
    const btn   = document.getElementById('devGalleryBtn');
    const input = document.getElementById('devGalleryFileInput') as HTMLInputElement | null;
    if (!btn || !input) return;

    btn.addEventListener('click', () => input.click());

    input.addEventListener('change', async () => {
        const file = input.files?.[0];
        if (!file) return;
        input.value = ''; // reset so same file can be picked again

        try {
            const text = await file.text();
            const data = JSON.parse(text);
            if (isGalleryManifest(data)) {
                showToast(`Gallery: ${file.name}`);
                await activateGallery(global, data);
            } else {
                showToast(`Not a gallery manifest: ${file.name}`);
            }
        } catch {
            showToast(`Invalid JSON: ${file.name}`);
        }
    });
}

/**
 * Wires the "Export Viewer…" button to open the export dialog.
 *
 * @param global - The PlayCanvas Global context object.
 */
function setupExportButton(global: Global): void {
    document.getElementById('devExportBtn')?.addEventListener('click', () => {
        showExportDialog(global);
    });
}
